SELECT 'moj-all-verified-judgments-review-002-chunk-117' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"e1eab3f2-2955-58c1-b1ca-52754c2e0845","document_type":"judgment","category":"judicial","subcategory":"general","title":"ممارسة مهنة بطريقة غير نظامية -توليد وإجهاض النساء - شهادة على إقرار -إنكار املدعى عليها -ثبوت إدانة املدعى عليها -تعزير بالسجن ومصادرة األجهزة الطبية -صرف النظر عن مصادرة املبلغ املالي املضبوط .","document_number":"3446763","case_number":"33702646","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/02/5","year":"1434","subject":"ممارسة مهنة بطريقة غير نظامية -توليد وإجهاض النساء - شهادة على إقرار -إنكار املدعى عليها -ثبوت إدانة املدعى عليها -تعزير بالسجن ومصادرة األجهزة الطبية -صرف النظر عن مصادرة املبلغ املالي املضبوط .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 3446763 :‬تاريخه ‪1434/02/5 :‬هـ‬\n                        ‫رقم الدعوى‪33702646 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34181595‬تاريخه‪1434/5/5 :‬هـ‬\n\n\n      ‫ممارســة مهنــة بطريقــة غيــر نظاميــة ‪ -‬توليــد وإجهــاض النســاء ‪-‬‬\n      ‫شــهادة علــى إقــرار ‪ -‬إنــكار املدعــى عليهــا ‪ -‬ثبــوت إدانــة املدعــى عليهــا‬\n      ‫‪ -‬تعزيــر بالســجن ومصــادرة األجهــزة الطبيــة ‪ -‬صــرف النظــر عــن‬\n                                                ‫مصــادرة املبلــغ املالــي املضبــوط ‪.‬‬\n\n\n\n\n                             ‫‪ .1‬قاعدة (األصل أن ما بحوزة اإلنسان ملك له)‪.‬‬\n                                   ‫‪ .2‬ما أشار إليه القاضي يف تسبيب حكمه‪.‬‬\n\n\n\n\n      ‫الئحــة الدعــوى ضــد املدعــى عليهــا بتوجيــه االتهــام لهمــا مبزاولــة‬\n      ‫مهنــة توليــد وإجهــاض النســاء بطريقــة غيــر نظاميــة بغــرض الكســب‬\n      ‫املــادي وطلــب إثبــات مــا أســند إليهمــا وتعزيرهــا شــرع ًا ‪ ،‬حيــث وردت‬\n      ‫معلومــات عــن قيــام املدعــى عليهــا بعمليــات التوليــد واإلجهــاض بطريقــة‬\n      ‫غيــر نظاميــة ‪ -‬فتــم طلــب اإلذن مــن اجلهــات الرســمية لتفتيــش منزلهــا‬\n      ‫‪ -‬فتمــت املوافقــة علــى ذلــك‪ -‬فوجــد يف بيتهــا عــدد مــن األدوات الطبيــة‬\n      ‫املوصوفــة يف الدعــوى ‪ -‬كمــا اعترفــت أمــام الفرقــة القابضــة بأنهــا‬\n      ‫تقــوم بالتوليــد للفقــراء‪ ،‬وطلــب املدعــي العــام تعزيرهــا لقــاء ذلــك وطلــب‬\n      ‫مصــادرة األدوات واألجهــزة الطبيــة واملبلــغ املالــي‪ ،‬أنكــرت املدعــى‬\n\n‫‪339‬‬\n\f‫عليهــا مــا جــاء بدعــوى املدعــي العــام‪ ،‬بطلــب البينــة مــن املدعــي العــام‬\n‫علــى دعــواه احضــر الشــاهد والشــاهدتني الذيــن شــهدوا علــى إقــرار‬\n‫املــرأة بالتوليــد للفقــراء‪ ،‬الذيــن ال يحملــون إثبــات‪ ،‬حكمــت احملكمــة‬\n‫بتعزيــر املدعــى عليهــا بالســجن واجللــد لقــاء إدانتهــا بتوليــد النســاء‬\n‫بطريقــة غيــر نظاميــة ومبصــادرة األدوات الطبيــة املضبوطــة والتصــرف‬\n‫بهــا حســب األنظمــة والتعليمــات وصــرف النظــر عــن طلــب املدعــي العام‬\n‫مصــادرة املبلــغ احلكومــي لعــدم ثبــوت كونــه حصيلــة عمليــة توليــد ‪،‬‬\n‫قنعــت املدعــى عليهــا باحلكــم وقــرر املدعــي العــام اعتراضــه احلكــم‬\n         ‫بالئحــة االعتــراض‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة اجلزائيــة‬\n‫مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة مبكــة املكرمــة برقــم وتاريــخ ‪1434/12/25‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم وتاريــخ ‪1433/12/25‬ه ـ ففــي يــوم األحــد‬\n‫املوافــق ‪1434/01/18‬ه ـ افتتحــت اجللســة الســاعة ‪ 10 : 45‬وفيهــا‬\n‫حضــر املدعــي العــام مبوجــب خطــاب التكليــف مــن مرجعــه رقــم ‪1513‬‬\n‫يف ‪1431/11/11‬ه ـ وادعــى علــى احلاضــرة معــه باملجلــس الشــرعي ‪.....‬‬\n‫ا بدعــواه حيــث أنــه باالطــاع علــى األوراق‬  ‫اجلنســية باإلقامــة رقــم قائ ـ ً‬\n‫الــواردة بخطــاب مركــز شــرطة ‪ .....‬رقــم ‪ 370096‬يف ‪1433/12/5‬ه ـ‬\n‫املشــتملة علــى محضــر القبــض املعــد مــن قبــل البحــث املتضمــن أنــه‬\n‫وبنــاء علــى املعلومــات الــواردة لهــم بخصــوص قيــام املدعــى عليهــا‬\n‫بعمليــات التوليــد واإلجهــاض بطريقــة غيــر نظاميــة وبعــد التأكــد‬\n\n                                                                                     ‫‪340‬‬\n\f      ‫مت الرفــع ملقــام اإلمــارة لطلــب اإلذن يف تفتيــش منزلهــا حيــث جــاء‬\n      ‫التوجيــه باملوافقــة فبتاريــخ ‪1433/12/4‬ه ـ جــرى القبــض عليهــا بعــد‬\n      ‫أن أدخلــت املصــدر الســري ملنزلهــا الكائــن بشــارع ‪ ...‬للكشــف عليهــا‬\n      ‫وقــد وجــد بحوزتهــا جهــاز جــوال صينــي لونــه ذهبــي وبــه شــريحة رقــم‬\n      ‫(‪ ).......‬وجــوال آخــر مــن نــوع ( ‪ ) .....‬ال يعمــل وليــس بــه شــريحة ومبلــغ‬\n      ‫(‪ 520‬خمســمائة وعشــرون ريــال ) وجــواز ســفر يحمــل الرقــم (‪)....‬‬\n      ‫كمــا عثــر داخــل املنــزل املكــون مــن غرفــة واحــدة مبنافعهــا علــى مــا‬\n      ‫يلــي ‪ :‬عــدد(‪ )3‬جهــاز قيــاس ضغــط عــدد(‪ )2‬ســماعة أذن عــدد(‪)26‬‬\n      ‫حبــة خياطــة عــدد (‪ )2‬كرتــون تخطيــط حمــل عــدد (‪ )27‬براويــز إبــر‬\n      ‫عــدد(‪ )1‬مســحات طبيــة ‪ ،‬عــدد(‪ )1‬لــي مغــذي ‪ ،‬عــدد(‪ )6‬كرتــون إبــر‬\n      ‫ميزوســيت ‪ ،‬عــدد(‪ )2‬مقــص ‪ ،‬عــدد(‪ )11‬قــارورة قــزاز صغيــرة (بنــج )‬\n      ‫‪ ،‬عــدد(‪ )5‬كرتــون إبــر قلــم إنســولني ‪ ،‬عــدد(‪ )7‬كرتــون عــاج معــدة‬\n      ‫‪ ،‬عــدد(‪ )2‬كرتــون عــاج دوخــة ‪ ،‬عــدد(‪ )2‬كرتــون قطــرات للعــن ‪،‬‬\n      ‫عــدد(‪ )1‬شــنطة صغيــرة ســوداء بهــا أدوات عمليــات جراحيــة ‪ ،‬عــدد (‪)3‬‬\n      ‫كرتــون بوتاســيوم ‪ ،‬عــدد (‪ )1‬علبــة بداخلهــا (‪ )54‬كبســولة ‪ ،‬عــدد‬\n      ‫(‪ )31‬كرتــون (ســينتوكنون ) ‪ ،‬عــدد (‪ )1‬جهــاز حتليــل اللــون أحمــر‬\n      ‫بداخلــه (‪ )8‬قواريــر صغيــرة وبســماع أقــوال املدعــى عليهــا ‪/‬أفــادت‬\n      ‫بــأن املــرأة املصــدر حضــرت لهــا ملنزلهــا ومعهــا امــرأة حامــل وطلبــوا‬\n      ‫الكشــف عليهــا فرفضــت وأخبرتهــم أن عليهــم التوجــه للمستشــفى‬\n      ‫إلجراء الكشــف ‪ ،‬كما أفات أن األجهزة واألدوات الطبية املضبوطة‬\n      ‫معهــا باملنــزل قــد اشــترتها إلرســالها لشــقيقتها املمرضــة بالســودان‬\n      ‫ألنهــا طلبتهــا ذلــك وباســتجوابها‪ /‬افــادت بأنــه مت القبــض عليهــا داخــل‬\n      ‫منزلهــا الكائــن خلــف بشــارع ‪...‬واملكــون مــن غرفــة واحــدة تســكنها‬\n\n\n‫‪341‬‬\n\f‫وزوجهــا فقــط وأنهــا ال تعمــل وليــس لهــا مصــدر رزق ســوى زوجهــا ‪،‬‬\n‫وان مــا عثــر داخلــه علــى األدوات واألجهــزة الطبيــة املفنــدة بالتفصيــل‬\n‫مبحضــر القبــض التــي تســتخدم جميعهــا يف مجــال توليــد النســاء قــد‬\n‫اشــترتها لبعثهــا للســودان حيــث مقــر إقامتهــا وحيــث تــؤدي هــي مهنــة‬\n‫توليــد النســاء هنــاك مبستشــفى الــوالدة ‪ ،‬كمــا بــررت تناقضهــا مــع‬\n‫مــا أدلــت بــه بســماع أقوالهــا مــن أن األدوات الطبيــة املضبوطــة معهــا‬\n‫لشــقيقتها الطبيبــة بالســودان وأنهــا موكلــة بشــرائها وبعثهــا لهــا ‪،‬‬\n‫بأنهــا ذكــرت ذلــك بالفعــل ألن شــقيقتها ممرضــة نســاء هنــاك وقــد‬\n‫انتهــى التحقيــق إلــى توجيــه االتهــام للمدعــى عليهــا‪ /‬مبزاولــة مهنــة‬\n‫توليــد وإجهــاض النســاء بطريقــة غيــر نظاميــة بغــرض الكســب املــادي‬\n‫وذلــك لألدلــة والقرائــن التاليــة ‪ -1:‬شــهادة الشــهود املدونــة مبحضــر‬\n‫القبــض والتفتيــش املنــوه عنــه واملرفــق لفــه (‪ -2 )3-2‬مــا جــاء يف تناقــض‬\n‫أقوالهــا ‪ ،‬إضافــة إلقرارهــا بــأن املنــزل ال يســكنه غيرهــا وزوجهــا ‪،‬‬\n‫وأن املضبوطــات التــي داخــل املنــزل عائــدة لهــا وهــي مــن قامــت بشــرائها‬\n‫‪ ،‬قرائــن تــدل علــى صحــة مــا نســب إليهــا وحيــث إن مــا قامــت بــه املدعــى‬\n‫عليهــا فعــل محــرم ومعاقــب عليــه شــرع ًا لــذا اطلــب إثبــات مــا أســند‬\n‫إليهــا وتعزيرهــا شــرع ًا ‪ ،‬واحلكــم مبصــادرة األجهــزة واألدوات الطبيــة‬\n‫‪ ،‬واملبلــغ املالــي البالــغ (‪ 520‬ريــال) خمســمائة وعشــرون ريــا ًال ‪ .‬هــذه‬\n‫دعــواي وبســؤال املدعــى عليهــا أجابــت بقولهــا مــا ذكــره املدعــي العــام‬\n‫مــن ضبــط جميــع املضبوطــات الطبيــة املذكــورة يف منزلــي فصحيــح‬\n‫ومــا ذكــره مــن قيامــي بالتوليــد واإلجهــاض فغيــر صحيــح وأنــا ال‬\n‫أســتعمل هــذه األدوات والواقــع أننــي اشــتريت هــذه األدوات الطبيــة‬\n‫ألرســلها ألختــي املقيمــة يف الســودان والتــي تعمــل قابلــة لتوليــد النســاء‬\n\n\n                                                                                     ‫‪342‬‬\n\f      ‫حيــث أوصتنــي بشــراء أفضــل األدوات وإرســالها لهــا ولكــن قبــض‬\n      ‫علــي قبــل ســفري بهــا هــذه إجابتــي وقــال املدعــي العــام الصحيــح مــا‬\n      ‫ذكــرت وبطلــب البينــة قــال ســأفيدكم يف اجللســة القادمــة لــذا رفعــت‬\n      ‫اجللســة ففــي يــوم الســبت املوافــق ‪1434/2/2‬ه ـ افتتحــت اجللســة وحضر‬\n      ‫فيهــا املدعــي العــام واملدعــى عليهــا ولــم يحضــر املدعــي العــام بينتــه لــذا‬\n      ‫رفعــت اجللســة إلحضارهــا ويف يــوم الثالثــاء املوافــق ‪1434/4/12‬ه ـ‬\n      ‫افتتحــت اجللســة وحضــر فيهــا املدعــي العــام واملدعــى عليهــا وحضــر‬\n      ‫للشــهادة وادائهــا ‪ ......‬بســجل مدنــي رقــم (‪ )....‬ســعودية اجلنســية بســجل‬\n      ‫مدنــي رقــم وشــهدا بقولهمــا أننــا شــاركنا يف مداهمــة غرفــة املدعــى‬\n      ‫عليهــا ووجدنــا األدوات الطبيــة املذكــورة ووجدنــا بعضهــا مســتعمال‬\n      ‫وبعضهــا يف الثالجــة وقــد اعترفــت املدعــى عليهــا مبزاولــة مهنــة التوليــد‬\n      ‫للفقــراء والذيــن ال يحملــون اثبــات هويــة وأنكــرت االجهــاض هــذه‬\n      ‫شــهادتنا كمــا حضــرت للشــهادة ‪ ....‬ســعودية اجلنســية بســجل مدنــي‬\n      ‫رقــم وشــهدت بقولهــا انــه جــرى تكليفــي مبواجهــة املدعــى عليهــا بعــد‬\n      ‫اإلخباريــة عنهــا فذهبــت إليهــا بغرفتهــا وطلبــت منهــا إجــراء اإلجهــاض‬\n      ‫فأفادتنــي بانهــا ال تقــوم باإلجهــاض وأنهــا تقــوم بالكشــف والتوليــد‬\n      ‫فقــط والعمــل كدايــة وعندمــا ذكــرت لــي ذلــك ورأيــت املعــدات الطبيــة‬\n      ‫اعطيــت اشــارة القبــض هــذه شــهادتي وقالــت املدعــى عليهــا مــا ذكــره‬\n      ‫الشــهود غيــر صحيــح وال اعرفهــم قبــل القبــض علــي ثــم جــرى تعديــل‬\n      ‫الشــهود الثالثــة مــن قبــل ‪ .......‬و‪ ........‬وقالــت املدعــى عليهــا ان املبلــغ‬\n      ‫املضبــوط معــي ملكــي وهــو مجمــوع مــن املصاريــف التــي يعطينــي‬\n      ‫إياهــا زوجــي وقــال املدعــي العــام ليــس لــدي بينــة علــى أن املبلــغ حصيلــة‬\n      ‫عمليــات التوليــد فرفعــت اجللســة للتأمــل ويف يــوم االثنــن املوافــق ‪/ 25‬‬\n\n\n‫‪343‬‬\n\f‫‪1434/2‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي العــام واملدعــى عليهــا‬\n‫وقــد جــرى تأمــل القضيــة فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n‫وإلــى إقــرار املدعــى عليهــا بحيــازة املضبوطــات الطبيــة املذكــورة يف‬\n‫منزلهــا وإنكارهــا اســتعمالها وإنكارهــا التوليــد واإلجهــاض وال بينــة‬\n‫علــى اإلجهــاض وبنــاء علــى شــهادة البينــة املعدلــة شــرعا حيــث شــهد‬\n‫الرجــل واملرأتــان علــى إقــرار املدعــى عليهــا بالقيــام بالتوليــد كمــا‬\n‫شــهدوا بــأن بعــض األدوات مســتعمل وبعضهــا يف الثالجــة لــذا فقــد‬\n‫ثبــت لــدي إدانــة املدعــى عليهــا مبزاولــة مهنــة توليــد النســاء بطريقــة‬\n‫غيــر نظاميــة وحكمــت بتعزيرهــا علــى ذلــك بالســجن مــدة أربعــة اشــهر‬\n‫ومصــادرة األدوات الطبيــة املضبوطــة والتصــرف بهــا حســب األنظمــة‬\n‫والتعليمــات ولــم يثبــت لــدي إدانتهــا بالقيــام بعمليــات اإلجهــاض كمــا‬\n‫صرفــت النظــر عــن طلــب املدعــي العــام مصــادرة املبلــغ املالــي املضبــوط‬\n‫بحوزتهــا وقــدره خمســمائة وعشــرون ريــاال لعــدم ثبــوت كونــه حصيلــة‬\n‫عمليــات توليــد وألن األصــل أن مــا بحــوزة اإلنســان ملــك لــه وبعــرض‬\n‫احلكــم علــى املدعــى عليهــا قنعــت بــه وقــد عــارض املدعــي العــام وطلــب‬\n                      ‫االســتئناف بالئحــة فأجيــب لطلبــه وبــاهلل التوفيــق ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ثــم عــادة املعاملــة مــن محكمــة االســتئناف‬\n‫وبرفقهــا القــرار رقــم يف ‪1434/4/8‬ه ـ املتضمــن املوافقــة والتصديــق‬\n‫علــى احلكــم وبــاهلل التوفيــق ‪.‬قاضــي اســتئناف‪ /‬ختــم‪ .‬توقيــع ‪.‬قاضــي‬\n‫اســتئناف‪ /‬ختــم ‪.‬توقيــع ‪.‬رئيــس الدائــرة‪ /‬ختــم ‪.‬توقيــع لــذا جــرى إحلاقــه‬\n                                               ‫واثباتــه حــرر يف ‪1434/5/5‬هــ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد‪-:‬‬\n‫فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة األولــى يف محكمــة‬\n\n\n                                                                                   ‫‪344‬‬\n\f      ‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبكــة املكرمــة برقــم‬\n      ‫وتاريــخ ‪1434/3/28‬هـ ـ املرفــق بهــا القــرار الشــرعي رقــم وتاريــخ‬\n      ‫‪1434/2/25‬هـ ـ الصــادر مــن فضيلــة الشــيخ‪ ...../‬القاضــي يف احملكمة‬\n      ‫اجلزائيــة مبكــة املكرمــة ‪ ،‬املتضمــن دعــوى املدعــي العــام ضــد ‪....../‬‬\n      ‫نيجيريــة اجلنســية املتهمــة بقضيــة ممارســة مهنــة التوليــد واإلجهــاض‬\n      ‫بطريقــة غيــر نظاميــة احملكــوم فيــه مبــا دون باطنــه‪ .‬وبدراســة احلكــم‬\n      ‫وصــورة ضبطــه والالئحــة االعتراضيــة قررنــا املوافقــة علــى احلكــم‪،‬‬\n      ‫واهلل املوفــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪345‬‬\n\f346\n\f                      ‫كشاف املوضوعات‬\n\n‫الصفحة‬                     ‫املوضوع‬                      ‫التصنيف‬   ‫م‬\n\n\n         ‫شخصا‬\n          ‫ً‬   ‫دعوى عامة وخاصة ضد مدعى عليه ضرب‬\n  ‫‪5‬‬                                                      ‫اعتداء‬   ‫‪1‬‬\n                ‫بعصا على رأسه أدت لوفاته‬\n\n\n           ‫دعوى عامة وخاصة لرمي املدعى عليه فنجانا‬\n  ‫‪16‬‬       ‫والتسبب يف إصابة املدعي باحلق اخلاص بجرح‬      ‫اعتداء‬   ‫‪2‬‬\n                 ‫بالرأس احتاج عشرة أيام للعالج‬\n\n\n         ‫دعوى عامة ضد زوج ضرب زوجته‪ ،‬وتنازلت الزوجة‬\n  ‫‪25‬‬                                                     ‫اعتداء‬   ‫‪3‬‬\n                         ‫عن حقها اخلاص‬\n\n\n          ‫دعوى عامة ضد مدعى عليه بالشروع يف قتل زوج‬\n  ‫‪34‬‬                                                     ‫اعتداء‬   ‫‪4‬‬\n            ‫أخته وذلك بضربه بفأس يف أطرافه األربعة‬\n\n\n          ‫دعوى عامة ضد مدعى عليه لقيامه بدخول منزل‬\n  ‫‪41‬‬                                                     ‫اعتداء‬   ‫‪5‬‬\n         ‫عنو ًة وطعن صاحبه بسكني مما تسبب يف إصابته‬\n\n\n            ‫دعوى عامة ضد مدعى عليه بطعن شخص‪،‬‬\n  ‫‪45‬‬                                                     ‫اعتداء‬   ‫‪6‬‬\n             ‫واملدعى عليه يدفع بأنه دافع عن نفسه‬\n\n\n          ‫دعوى عامة ضد مدعى عليه بقيامه بسكب زيت‬\n  ‫‪52‬‬                                                     ‫اعتداء‬   ‫‪7‬‬\n           ‫ساخن على أحد السجناء مما تسبب يف إصابته‬\n\n\n          ‫مطالبة مدعية (مقيمة عند أهلها) بتعزير زوجها‬\n  ‫‪57‬‬                                                     ‫اعتداء‬   ‫‪8‬‬\n            ‫لضربه لها وسبها وشتمها وتعريضه بقذفها‬\n\f‫الصفحة‬                      ‫املوضوع‬                         ‫التصنيف‬   ‫م‬\n\n\n          ‫دعوى عامة وخاصة ضد مدعى عليها التهامها‬\n  ‫‪65‬‬                                                         ‫اعتداء‬   ‫‪9‬‬\n         ‫بإساءة سمعة امرأة والتشهير بها يف مواقع اإلنترنت‬\n\n\n            ‫مطالبة مدعية بتعزير زوجها إلسائته عشرتها‬\n  ‫‪75‬‬                                                         ‫اعتداء‬   ‫‪10‬‬\n                    ‫وضربها والشروع يف قتلها‬\n\n\n         ‫دعوى عامة ضد مدعى عليهما أحدهما لم يحضر‬\n  ‫‪81‬‬     ‫باجتماعهما على شرب مسكر إثر القبض عليهما‬            ‫اعتداء‬   ‫‪11‬‬\n                         ‫نتيجة مضاربة‬\n\n\n            ‫دعوى عامة وخاصة ضد مدعى عليه العتدائه‬\n            ‫بسيارته على مواطنني يسيران على أقدامهما‬\n  ‫‪89‬‬                                                         ‫اعتداء‬   ‫‪12‬‬\n           ‫مبطاردتهما بقصد إصابتهما‪ ،‬وإصابة أحدهما‬\n                         ‫والهروب من املوقع‬\n\n\n          ‫عمدا‬\n           ‫دعوى عامة بتعزير مدعى عليه لضربه آخر ً‬\n  ‫‪98‬‬                                                         ‫اعتداء‬   ‫‪13‬‬\n                     ‫نتج عنه إصابته‬\n\n\n         ‫دعوى عامة وخاصة ضد مدعى عليها بضرب زوجها‬\n ‫‪103‬‬                                                         ‫اعتداء‬   ‫‪14‬‬\n                   ‫بكأس زجاج على رأسه‬\n\n\n           ‫مطالبة مدعية تأديب مدعى عليه كان زوجا لها‬\n         ‫اتهمها أثناء نظر قضية حضانة أوالدهما حكم فيها‬\n ‫‪109‬‬       ‫بحضانتها‪ ،‬بأنها مصابة باضطرابات عقلية وأنها‬       ‫اعتداء‬   ‫‪15‬‬\n                           ‫حاولت االنتحار‬\n\f‫الصفحة‬                      ‫املوضوع‬                       ‫التصنيف‬   ‫م‬\n\n\n         ‫دعوى عامة وخاصة ضد مدعى عليه إلتالفه إطارات‬\n ‫‪115‬‬     ‫سيارة املدعي باحلق اخلاص وقطع التيار الكهربائي‬    ‫اعتداء‬   ‫‪16‬‬\n                 ‫عن منزله وانتحال شخصية الغير‬\n\n\n          ‫دعوى عامة بتعزير مدعى عليهما العتدائهما على‬\n ‫‪126‬‬      ‫بعض والتسبب يف اإلصابة التي حلقت بكل منهما‬       ‫اعتداء‬   ‫‪17‬‬\n                    ‫على إثر سوء تفاهم بينهما‬\n\n\n          ‫دعوى عامة بتعزير مدعى عليهم سبعة العتدائهم‬\n ‫‪131‬‬      ‫على بعض بأدوات حادة والتسبب باإلصابات التي‬       ‫اعتداء‬   ‫‪18‬‬\n                ‫حلقت بهم على إثر سوء تفاهم بينهم‬\n\n\n           ‫دعوى عامة وخاصة ضد مدعى عليه بأذيته جاره‬\n ‫‪145‬‬      ‫وعمه من خالل تسوره على سترة منزلهم واطالعه‬       ‫اعتداء‬   ‫‪19‬‬\n                          ‫على عورات منزله‬\n\n\n           ‫دعوى عامة وخاصة ضد مدعى عليهم عشرة‬\n ‫‪156‬‬       ‫بالتحريض على اقتحام منزل والتجمهر وقذف‬          ‫اعتداء‬   ‫‪20‬‬\n              ‫حجارة عليه والقفز ومحاولة اقتحامه‬\n\n\n          ‫دعوى عامة ضد مدعى عليه لقيامه باالعتداء على‬\n ‫‪177‬‬                                                       ‫اعتداء‬   ‫‪21‬‬\n          ‫زوجته بالضرب وخنقها بيده والتسبب يف إصابتها‬\n\n\n          ‫دعوى عامة ضد مقيم العتدائه على أحد الوافدين‬\n ‫‪182‬‬     ‫وسرقة ما طور كهربائي والتستر على شركائه يف‬        ‫اعتداء‬   ‫‪22‬‬\n                              ‫اجلرمية‬\n\f‫الصفحة‬                      ‫املوضوع‬                      ‫التصنيف‬   ‫م‬\n\n\n          ‫دعوى عامة ضد مدعى عليه العتدائه على رجال‬\n ‫‪188‬‬        ‫األمن بإحلاق الضرر مبركبتيهم بعد محاولة‬       ‫اعتداء‬   ‫‪23‬‬\n                            ‫استيقافه‬\n\n\n         ‫دعوى عامة مدعى عليه العتدائه على زوجته التي‬\n         ‫تنازلت عن حقها بالضرب بيده وجتاوز حد التأديب‬\n ‫‪193‬‬                                                      ‫اعتداء‬   ‫‪24‬‬\n          ‫الشرعي والتسبب يف جرح وفقد جزء من إحدى‬\n                            ‫أسنانها‬\n\n\n         ‫دعوى عامة ضد مدعى عليه إلشهاره السالح على‬\n           ‫مواطن‪ ،‬بقصد التهديد ومقاومة رجل األمن‪،‬‬\n ‫‪199‬‬                                                      ‫اعتداء‬   ‫‪25‬‬\n          ‫واالعتداء على مركبته بالصدم والهروب منه‪،‬‬\n          ‫وصدم سيارة مواطن عمدا وانتهاك حرمة منزل‬\n\n\n         ‫دعوى عامة ضد مدعى عليه لطعنه شقيقه املجني‬\n ‫‪205‬‬                                                      ‫اعتداء‬   ‫‪26‬‬\n                         ‫عليه وإصابته‬\n\n\n            ‫دعوى عامة ضد مدعى عليه الرتكابه جرمية‬\n ‫‪211‬‬      ‫االجتار بالبشر بتعذيب طفله القاصر ‪ ،‬و جتاوزه‬    ‫اعتداء‬   ‫‪27‬‬\n             ‫حد التأديب الشرعي‪ ،‬والتسبب يف إصابته‬\n\n\n         ‫دعوى عامة ضد مدعى عليه لطعنه شخصا تنازل‬\n ‫‪222‬‬     ‫عن حقه اخلاص على يده اليمنى طعنتني بسكني‬         ‫اعتداء‬   ‫‪28‬‬\n                         ‫وإصابته‬\n\n\n         ‫دعوى عامة ضد مدعى عليه (مريض نفسي) لتعديه‬\n ‫‪227‬‬                                                      ‫اعتداء‬   ‫‪29‬‬\n          ‫بالضرب على موظف حكومي أثناء تأديته عمله‬\n\f‫الصفحة‬                       ‫املوضوع‬                        ‫التصنيف‬   ‫م‬\n\n\n         ‫دعوى عامة ضد مدعى عليه إلشهاره السالح على‬\n ‫‪232‬‬      ‫زوجته التي تنازلت عن حقها اخلاص وتهديدها‬           ‫اعتداء‬   ‫‪30‬‬\n                 ‫وضربها وإحداث إصابات بها‬\n\n\n         ‫وتعد‬\n         ‫ٍّ‬   ‫دعوى عامة ضد مدعى عليهم للخلوة احملرمة‬\n ‫‪236‬‬     ‫لفظي على جهة الضبط وتهديدهم بالقتل ومحاولة‬          ‫اعتداء‬   ‫‪31‬‬\n                              ‫تهريب‬\n\n\n          ‫عمدا‬\n            ‫دعوى عامة ضد مدعى عليه لصدمه سيارة ً‬\n ‫‪245‬‬       ‫وإحداث تلفيات بها والتلفظ على صاحبها نتيجة‬        ‫اعتداء‬   ‫‪32‬‬\n                    ‫سوء تفاهم بينه وبني صاحبها‬\n\n\n          ‫دعوى عامة ضد مدعى عليه العتدائه عمد ًا على‬\n ‫‪252‬‬      ‫شخص تنازل عن حقه اخلاص بضربه على رأسه‬              ‫اعتداء‬   ‫‪33‬‬\n                  ‫بأداة خشبية و التسبب يف إصابته‬\n\n\n         ‫دعوى عامة ضد مدعى عليها لضربها امرأة بحذاء‬\n ‫‪257‬‬                                                         ‫اعتداء‬   ‫‪34‬‬\n             ‫على عينها اليمنى مما أدى إلى إصابتها‬\n\n\n          ‫دعوى عامة ضد مدعى عليه لتهديده رجل أمن‬\n ‫‪263‬‬     ‫والتعدي عليه بألفاظ غير الئقة و اعتداء بالضرب‬       ‫اعتداء‬   ‫‪35‬‬\n                ‫على أحد املوقوفني أثناء إيقافه‬\n\n\n         ‫دعوى عامة ضد مدعى عليه لشروعه يف قتل زوجته‬\n ‫‪269‬‬     ‫التي تنازلت عن حقها اخلاص واالعتداء بضربها مما‬      ‫اعتداء‬   ‫‪36‬‬\n           ‫أدى إلصابتها وطلب إيقاع العقوبة التعزيرية عليه‬\n\n\n           ‫دعوى عامة ضد مدعى عليه إلطالقه النار على‬\n ‫‪276‬‬                                                         ‫اعتداء‬   ‫‪37‬‬\n             ‫سيارة شخص آخر مما تسبب يف إحراقها‬\n\f‫الصفحة‬                      ‫املوضوع‬                       ‫التصنيف‬      ‫م‬\n\n\n         ‫دعوى عامة وخاصة ضد مدعى عليه لوضعه حجارة‬\n ‫‪280‬‬       ‫وبهائم على الطريق عمد ًا مما تسبب يف حدوث‬       ‫اعتداء‬      ‫‪38‬‬\n                 ‫تلفيات لسيارتني وإصابة امرأة‬\n\n\n           ‫دعوى عامة ضد مدعى عليه لقيامه بسب رجال‬          ‫مقاومة‬\n ‫‪291‬‬                                                                   ‫‪39‬‬\n              ‫األمن وقذفهم واحلكم عليه بحد القذف‬           ‫سلطات‬\n\n\n         ‫دعوى عامة ضد مدعى عليه لهروبه من رجال األمن‬\n                                                           ‫مقاومة‬\n ‫‪294‬‬     ‫وإشهاره السالح عليهم والتستر على مرافقه الهارب‬                ‫‪40‬‬\n                                                           ‫سلطات‬\n                         ‫من رجال األمن‬\n\n\n           ‫دعوى عامة ضد مدعى عليه (حدث) لهروبه من‬          ‫مقاومة‬\n ‫‪301‬‬                                                                   ‫‪41‬‬\n                  ‫نقطة تفتيش وصدم دورية أمنية‬              ‫سلطات‬\n\n\n          ‫دعوى عامة ضد مدعى عليه لصدمه دورية أمنية‬\n                                                           ‫مقاومة‬\n ‫‪307‬‬     ‫مما تسبب يف إصابة قائدها املتنازل عن حقه اخلاص‬                ‫‪42‬‬\n                                                           ‫سلطات‬\n              ‫وإتالف ممتلكات عامة وهربه من املوقع‬\n\n\n           ‫دعوى عامة ضد مدعى عليهم أربعة ملجاهرتهم‬        ‫اإلفطار يف‬\n ‫‪313‬‬                                                                   ‫‪43‬‬\n                      ‫بالفطر يف نهار رمضان‬                 ‫رمضان‬\n\n\n         ‫دعوى عامة ضد مدعى عليه لفطره يف نهار رمضان‬       ‫اإلفطار يف‬\n ‫‪321‬‬                                                                   ‫‪44‬‬\n                    ‫عامدا من غير عذر‬\n                                  ‫ً‬  ‫عاملًا‬                ‫رمضان‬\n\n\n            ‫دعوى عامة ضد مدعى عليه إلفطاره يف نهار‬        ‫اإلفطار يف‬\n ‫‪324‬‬                                                                   ‫‪45‬‬\n         ‫رمضان وهروبه من الدورية األمنية وصدم سيارتها‬      ‫رمضان‬\n\f‫الصفحة‬                      ‫املوضوع‬                      ‫التصنيف‬   ‫م‬\n\n\n                                                          ‫انتحال‬\n ‫‪333‬‬     ‫دعوى عامة ضد مدعى عليه النتحاله شخصية محام‬                ‫‪46‬‬\n                                                         ‫شخصية‬\n\n\n          ‫دعوى عامة ضد مدعى عليها ملزاولتها مهنة توليد‬\n                                                          ‫انتحال‬\n ‫‪339‬‬        ‫وإجهاض النساء بطريقة غير نظامية بغرض‬                   ‫‪47‬‬\n                                                         ‫شخصية‬\n                           ‫الكسب املادي‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":339,"source_page_end":353,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"e6ed8a1a7c3447178b4298c4cfa61fea579b82b4923d9fb1a6696325b2340837","normalized_text_hash":"f028bef243c79dde0a4252ff9f38ed42e93e6386f79ca584c2329484870bd7c8","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p339-3446763"},{"id":"284061b0-81e9-525e-a41f-aba35606d971","document_type":"judgment","category":"judicial","subcategory":"general","title":"تزوير -تستر على واقعة تزوير بتقدمي معلومات غير صحيحة جلهة حكومية -ظروف مخففة للتعزير -تعزير بالتوبيخ وأخذ التعهد.","document_number":"3423238","case_number":"33135559","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بينبع","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/26","year":"1434","subject":"تزوير -تستر على واقعة تزوير بتقدمي معلومات غير صحيحة جلهة حكومية -ظروف مخففة للتعزير -تعزير بالتوبيخ وأخذ التعهد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪ 3423238:‬تاريخه‪1434/1/26 :‬هـ‬\n                       ‫رقم الدعوى‪33135559 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 3422619‬تاريخه‪1434/5/22:‬هـ‬\n\n\n    ‫تزويــر‪ -‬تســتر علــى واقعــة تزويــر بتقــدمي معلومــاتٍ غيــر صحيحــة جلهة‬\n     ‫حكوميــة ‪ -‬ظــروف مخففــة للتعزيــر ‪ -‬تعزيــر بالتوبيــخ وأخــذ التعهد‪.‬‬\n\n\n\n\n            ‫‪ -‬قوله صلى اهلل عليه وسلم ((أقيلوا ذوي الهيئات عثراتهم ))‪.‬‬\n\n\n\n\n    ‫مت توجيــه االتهــام للمدعــى عليــه بالتســتر علــى واقعــة تزويــر تتمثــل‬\n    ‫بالتقــدم مبعلومــات غيــر صحيحــة مبســاعدة شــخص آخــر حيــث أرفــق‬\n    ‫تقريــر ًا طبي ـ ًا غيــر صحيــح لزوجتــه لطلــب املوافقــة علــى الــزواج مــن‬\n    ‫أجنبيــة‪ -‬بالبحــث عــن ســوابقه تبــن عــدم وجــود ســوابق عليــه‪ -‬طلــب‬\n    ‫املدعــي العــام احلكــم علــى املدعــى عليــه بعقوبة تعزيريــة‪ -‬بعرض دعوى‬\n    ‫املدعــي العــام علــى املدعــى عليــه صــادق عليهــا ودفــع أنــه كان محتاجــا‬\n    ‫املعقــب ولــم‬\n             ‫إلــى الــزواج بزوجــة ثالثــة وأن ورقــة التقريــر الطبــي وضعهــا ِّ‬\n    ‫يعلــم هــو عــن مضمونهــا ولــو علــم أنهــا مــزورة مــا وافــق عليهــا‪ ،‬وقــرر‬\n    ‫أنــه صاحــب أســرة حيــث يعــول اثنتــي عشــر نفس ـ ًا كمــا أنــه يعمــل‬\n    ‫معلم ـاً‪ -‬جــرى االطــاع علــى ســجل األســرة اخلــاص بــه فوجــد يتضمــن‬\n    ‫أن لــه عشــرة مــن األوالد مــا بــن أبنــاء وبنــات‪ -‬نظــر ًا لكــون املدعــى‬\n    ‫عليــه ذو عيــال وخشــية علــى ضيــاع مســتقبل مــن يعولهــم مت احلكــم‬\n‫‪5‬‬\n\f‫بتعزيــر املدعــى عليــه بتوبيخــه يف مجلــس احلكــم وأخــذ التعهــد الشــديد‬\n‫والــازم عليــه بعــدم العــودة إلــى مثــل مــا بــدر منــه ‪ -‬بعــرض احلكــم علــى‬\n‫املدعــى عليــه قــرر قناعتــه بــه وبعرضــه علــى املدعــي العــام قــرر عــدم‬\n‫القناعــة وطلــب االســتئناف مكتفيـ ًا بالئحــة الدعــوى العامــة وبعــد رفــع‬\n                      ‫احلكــم حملكمــة االســتئناف متــت املصادقــة عليهــا‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .........‬القــاض ـ ــي يف احملكمــة العامــة‬\n‫بينبــع وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بينبع‪/‬املســاعد برقــم ‪ 33135559‬وتاريــخ ‪1433/02/22‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 33354860‬وتاريــخ ‪1433/2/22‬ه ـ ففــي يــوم‬\n             ‫االثنــن املوافق‪1433/11/22‬ه ـ افتتحــت اجلـ ــلسـ ــة السـ ــاعة‬\n‫‪ 10 : 30‬وفيهــا حضــر املدعــي العــام بينبــع ‪ ......‬واملكلــف مــن قبــل‬\n‫ال بصفتي مدعيا‬      ‫م ــرجعه برقم ‪......‬وتاريخ ‪1426/12/22‬هـ وادعى قائ ً‬\n‫عامــا بدائــرة االدعــاء العــام بينبــع أدعــي علــى ‪ 39 ......‬عامــا ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪......‬لــم يوقــف يقيــم مبحافظــة‬\n‫ينبــع وحيــث إنــه بتاريــخ ‪1429/3/22‬ه ـ ورد إلــى الدائــرة خطــاب ســعادة‬\n‫محافــظ ينبــع رقــم ‪......‬املتضمــن التحقيــق مــع املدعــى عليــه الرتكابــه‬\n‫مخالفــة تتمثــل بالتقــدم مبعلومــات غيــر صحيحــة مبســاعدة آخــر حيــث‬\n‫أرفــق تقريــر ًا طبي ـ ًا غيــر صحيــح لزوجتــه لطلــب املوافقــة علــى الــزواج‬\n‫مــن أجنبيــة وباســتجوابه أنــه قــام بتوكيــل شــخص يدعــى ‪ ......‬ملتابعــة‬\n‫املعاملــة يف وزارة الداخليــة وأنــه شــاهد مــن ضمــن األوراق التــي كان‬\n‫ينــوي الوكيــل تقدميهــا إلــى الــوزارة تقريــر ًا طبي ـ ًا لزوجتــه صــادر ًا مــن‬\n\n                                                                                        ‫‪6‬‬\n\f    ‫مستشــفى لــم يراجعــه ومتضمن ـ ًا ملعلومــات غيــر صحيحــة وقــد انتهــى‬\n    ‫التحقيــق إلــى توجيــه االتهــام إليــه بالتســتر علــى واقعــة تزويــر وذلــك ملــا‬\n    ‫جــاء يف أقوالــه املدونــة ص ‪ 1‬ـ ‪ 4‬مــن دفتــر التحقيــق املرفــق لفــة ‪22‬‬\n    ‫وببحــث حالتــه اجلنائيــة تبــن عــدم وجــود ســوابق مســجلة عليــه وحيث إن‬\n    ‫مــا أقــدم عليــه املتهــم وهــو بكامــل أهليتــه املعتبــرة شــرع ًا فعــل محــرم‬\n    ‫ومعاقــب عليــه شــرع ًا أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة‬\n    ‫تعزيريــة هكــذا ادعــى املدعــي العــام وحيــث إنــه مت تكليــف املدعــى‬\n    ‫عليــه باحلضــور هــذا اليــوم وذلــك بخطابنــا املوجــه ملديــر أمــن احملكمــة‬\n    ‫برقــم ‪ 331790492‬وتاريــخ ‪1433/10/14‬ه ـ ولــم يحضــر لــذا وبنــاء‬\n    ‫علــى املــادة احلاديــة واألربعــن بعــد املائــة مــن نظــام اإلجــراءات اجلزائيــة‬\n    ‫ونصهــا اآلتــي إذا لــم يحضــر املتهــم املكلــف باحلضــور حســب النظــام يف‬\n    ‫اليــوم املعــن يف ورقــة التكليــف باحلضــور ولــم يرســل وكيــا عنــه يف‬\n    ‫األحــوال التــي يســوغ فيهــا التوكيــل فيســمع القاضــي دعــوى املدعــي‬\n    ‫وبيناتــه ويرصدهــا يف ضبــط القضيــة وال يحكــم إال بعــد حضــور املتهــم‬\n    ‫لــذا فقــد جــرى رفــع اجللســة ويف جلســة أخــرى لــدي أنــا ‪ ......‬القاضــي‬\n    ‫باحملكمــة العامــة بينبــع والقائــم بعمــل الشــيخ ‪ ......‬حضــر املدعــي العــام‬\n    ‫واملدعــى عليه‪......‬ثــم جــرى عــرض الئحــة املدعــي العــام علــى املدعــى‬\n    ‫ا مــا جــاء يف الئحــة‬  ‫عليــه احلاضــر وبســؤاله عمــا جــاء فيهــا أجــاب قائ ـ ً‬\n    ‫املدعــي العــام صحيــح وحقيقــة األمــر أنــي كنــت محتاجـ ًا إلــى الــزواج‬\n    ‫بزوجــة ثالثــة ولــم أكــن مســتطيع ًا أن أتــزوج ســعودية وذلــك ألن لــدي‬\n    ‫ظروفـ ًا خاصــة ال تســمح لــي بذلــك فقمــت بالتقــدمي علــى وزارة الداخليــة‬\n    ‫بطلــب اإلذن لــي بالــزواج مــن أجنبيــة فذهبــت إلــى الريــاض وقابلــت‬\n    ‫شــخص ًا يدعــى ‪ ......‬وأخبرنــي بأنــه معقــب ويســتطيع أن يتابــع معاملتــي‬\n\n\n‫‪7‬‬\n\f‫بــوزارة الداخليــة وينهــي إجراءاتهــا فاقتنعــت بــه وبكالمــه ثــم أعطيتــه‬\n‫معاملتــي ليتابعهــا بالــوزارة ورجعــت إلــى محافظــة ينبــع حيــث أقيــم‬\n‫فاتصــل بــي بعــد عــدة أيــام وأخبرنــي أنــه البــد لقبــول املعاملــة مــن أن‬\n‫تكــون زوجتــي تعانــي مــن مــرض أو متــر بظــروف صحيــة فأخبرتــه أن‬\n‫ا تعانــي مــن بعــض األمــراض فقــال لــي إنــه وضــع ورقــة يف‬      ‫زوجتــي فع ـ ً‬\n‫معاملتــي تفيــد بذلــك ولــم أكــن أعلــم مبحتواهــا ولــو علمــت أن القضيــة‬\n‫قضيــة تزويــر ملــا وافقــت علــى فعلــه وأنــا رجــل ذو عيــال حيــث أننــي أعــول‬\n‫اثنــي عشــر نفسـ ًا وأنــا معلــم ودخلــي محــدود وأخشــى أن أفقــد وظيفتــي‬\n‫وتضيــع أســرتي الكبيــرة هكــذا أجــاب ثــم قــدم أصــل ســجل األســرة‬\n‫اخلــاص بــه وباالطــاع عليــه وجــد أن لديــه عشــرة مــن األوالد مــا بــن‬\n‫أبنــاء وبنــات ثــم جــرى الرجــوع للمعاملــة ووجــد بهــا وعلــى ملــف التحقيــق‬\n‫لفــة (‪ )22‬ص(‪ )4-3-2-1‬محضــر اســتجواب للمدعــى عليــه احلاضــر‬\n‫املــؤرخ يف ‪1429/4/29‬ه ـ وليــس فيــه ســوى مــا ذكــره املدعــى عليــه يف‬\n‫ا ال بينــة‬\n          ‫جوابــه وبســؤال املدعــي العــام هــل لديــه زيــادة بينــة أجــاب قائـ ً‬\n‫لــدي ســوى مــا ذكرتــه هكــذا ‪ .‬أجــاب هــذا وألجــل مــا جــاء يف الدعــوى‬\n‫واإلجابــة وملصادقــة املدعــى عليــه علــى جــاء يف دعــوى املدعــي العــام‬\n‫وملــا ظهــر لــي مــن حــال املدعــى عليــه مــن أنــه مــن ذوي الهيئــات ولقولــه‬\n‫صلــى اهلل عليــه وســلم ((أقيلــوا ذوي الهيئــات عثراتهــم)) وألن املدعــى‬\n‫عليــه ذو عيــال وخشــية علــى ضيــاع مســتقبل مــن يعولهــم لــذا فقــد قــررت‬\n‫تعزيــر املدعــى عليــه احلاضــر بتوبيخــه يف مجلــس احلكــم وأخــذ التعهــد‬\n‫الشــديد والــازم عليــه بعــدم العــودة إلــى مثــل مــا بــدر منــه هــذا مــا‬\n‫ظهــر لــي وبــه حكمــت وبعــرض احلكــم علــى املدعــى عليــه قــرر قناعتــه‬\n‫بــه وبعرضــه علــى املدعــي العــام قــرر عــدم القناعــة وطلــب االســتئناف‬\n\n\n                                                                                       ‫‪8‬‬\n\f    ‫مكتفي ـ ًا بالئحــة الدعــوى العامــة وأمــرت برفــع املعاملــة لالســتئناف‬\n    ‫حســب املتبــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                     ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/1/19‬ه ـ ‪.‬‬\n    ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n    ‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة اخلامســة مبحكمــة االســتئناف‬\n    ‫يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n    ‫رئيــس احملكمــة العامــة بينبــع املســاعد برقــم ‪32969456‬وتاريــخ‬\n    ‫‪1434/5/6‬ه ـ املرفــق بها القرار رقم ‪ 3423238‬وتاريخ‪1434/1/26‬هـ‬\n    ‫الصــادر مــن فضيلــة الشــيخ‪....../‬القاضي باحملكمــة العامــة بينبــع‬\n    ‫القائــم بعمــل فضيلــة الشــيخ ‪......‬املتضمــن دعــوى املدعــي العــام ضــد ‪/‬‬\n    ‫‪ ......‬فســعودي اجلنســية املتهــم يف التســتر علــى واقعــة تزويــر ‪ ،‬احملكــوم‬\n    ‫فيــه مبــا دون بباطنــه ‪ ،‬وبدراســة القــرار وصــورة ضبطــه قررنــا املوافقــة‬\n    ‫علــى احلكــم ‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                                 ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪9‬‬\n\f10\n\f11\n\f12\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"ca29cb00-ff93-515e-9771-74b0d5d4a25f","source_page_start":5,"source_page_end":12,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"caf9b315ca938725a1e2ec005486673325b7d835caa07c4e76e93053ee372b87","normalized_text_hash":"a75ff40f9d8940874255d914034acf8f09fa7f04c2942aa291216f1ceeccb239","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v24-p5-3423238"},{"id":"87f1085a-c6ff-5017-8b07-b4e3688a19e9","document_type":"judgment","category":"judicial","subcategory":"general","title":"شهادة زور -تدليس لدى القاضي يف المحكمة -ثبوت -صرف نظر- تعزير -جلد -تعهد -إعادة إثبات زواج قائم.","document_number":"34269796","case_number":"34242667","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة املتضمن انه تقدم اليهم املدعى عليه الرابع","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/17","year":"1434","subject":"شهادة زور -تدليس لدى القاضي يف المحكمة -ثبوت -صرف نظر- تعزير -جلد -تعهد -إعادة إثبات زواج قائم.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪ 34269796 :‬تاريخه‪1434/7/17 :‬هـ‬\n                        ‫رقم الدعوى‪34242667 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n              ‫‪ 34328805‬تاريخه‪1434/10/12 :‬هـ‬\n\n\n     ‫شــهادة زور ‪ -‬تدليــس لــدى القاضــي يف احملكمــة ‪ -‬ثبــوت ‪ -‬صــرف نظــر‪-‬‬\n                                ‫تعزيــر ‪ -‬جلــد ‪ -‬تعهــد ‪ -‬إعــادة إثبــات زواج قائــم‪.‬‬\n\n\n\n\n     ‫مــا اســتند إليــه القاضــي مــن املبــادئ العامــة وقواعد العدالة يف تســبيب‬\n                                                                         ‫حكمه‪.‬‬\n\n\n\n\n     ‫اتهــام املدعــي العــام للمدعــى عليهمــا الثانــي والرابــع بالتدليــس أمــام‬\n     ‫القاضــي الشــرعي يف أمــر النــكاح واتهــام املدعــى عليهمــا األول‬\n     ‫والثالــث بشــهادة الــزور وبطلــب إثبــات مــا اســند اليهــم واحلكــم عليهــم‬\n                                                         ‫بعقوبــة تعزيريــة رادعــة‪.‬‬\n                                                          ‫ومبواجهة املدعى عليهم‬\n                      ‫‪ -‬أقر املدعى عليهما الثاني والرابع مبا جاء يف الدعوى ‪.‬‬\n     ‫‪ -‬أنكــر املدعــى عليهمــا األول والثالــث بتدليــس املدعــى عليهمــا الثانــي‬\n                                                                            ‫والرابع‪.‬‬\n                                                          ‫وعليه قررت احملكمة‪:‬‬\n     ‫‪ -‬إدانــة املدعــى عليهمــا الثانــي والرابــع مبــا جــاء يف الدعــوى واحلكــم‬\n     ‫عليهمــا بجلدهمــا أربعــن جلــدة دفعــة واحــدة وأخــذ التعهــد املشــدد‬\n‫‪13‬‬\n\f‫عليهمــا بعــدم العــودة ملــا بــدر منهمــا وعــدم ثبــوت إدانــة األول والثالــث‬\n                    ‫بشــهادة الــزور وصــرف النظــر عــن طلــب تعزيرهمــا‪.‬‬\n‫‪ -‬وقــرر املدعــي العــام االعتــراض وطلــب االســتئناف بالئحــة وقــرر‬\n                                                  ‫املدعــى عليهــم القناعــة ‪.‬‬\n                                ‫‪ -‬صدق احلكم من محكمة االستئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة مبكــة املكرمــة برقــم ‪ 34242667‬وتاريــخ‬\n‫‪ 1434/05/26‬ه ـ املقيــدة باحملكمــة برقــم ‪ 341281143‬وتاريــخ‬\n‫‪ 1434/05/26‬ه ـ ففــي يــوم األحــد املوافــق‪ 1434/07/16‬ه ـ افتتحــت‬\n‫اجللسة الساعة ‪ 11 : 30‬وفيها حضر املدعي العام ‪ ......‬مبوجب خطاب‬\n‫التكليــف مــن مرجعــه رقــم ه ـ م ‪/2/‬أ‪ 2108/‬يف ‪1434/5/5‬ه ـ وادعــى‬\n‫علــى احلاضريــن كل مــن ‪ ..... -1‬مينمــاري اجلنســية باالقامــة رقــم (‪)....‬‬\n‫و‪ ..... -2‬ماينمــاري اجلنســية (‪ ).....‬و‪ ..... -3‬ماينمــاري اجلنســية باالقامــة‬\n‫رقــم (‪ ).......‬و‪ ...... -4‬ماينمــاري اجلنســية باالقامــة رقــم (‪ ).....‬حيــث انــه‬\n‫بتاريــخ ‪1434/2/20‬ه ـ تبلــغ مركــز شــرطة اجيــاد عــن حالــة جنائيــة‬\n‫مبوجــب كتــاب فضيلــة القاضــي ‪ ....‬القاضــي باحملكمــة العامة مبكة‬\n‫املكرمــة املتضمــن انــه تقــدم اليهــم املدعــى عليــه الرابــع ‪ ....‬بطلــب عقــد‬\n‫زواجــه باملــرأة ‪ ......‬بواليــة اخيهــا املدعــى عليــه الثاني ‪ .....‬وشــهادة املدعى‬\n‫عليهمــا االول ‪ ....‬والثالــث ‪ ....‬وعقــد لهمــا وصــدر لهمــا القــرار الشــرعي‬\n‫رقــم ‪ 33330561‬يف ‪1433/7/7‬ه ـ وتقــدم لهــم املدعــى عليــه الرابــع بعــد‬\n\n                                                                                         ‫‪14‬‬\n\f     ‫ســبعة اشــهر مفيــدا بــأن الــزواج كان بتاريــخ ‪1432/12/20‬ه ـ وانــه لــم‬\n     ‫يذكــر للمحكمــة خلشــيته مــن تعطــل االجــراءات وصــدق الشــاهدان‬\n     ‫املدعــى عليهمــا االول والثالــث علــى ذلــك وبســماع اقــوال املدعــى عليــه‬\n     ‫الرابــع ‪ ....‬اقــر بانــه قبــل ســتة اشــهر عقــد علــى امــرأة بواليــة املدعــى‬\n     ‫عليــه الثانــي ثــم ذهــب الــى احملكمــة ولــم يذكــر للقاضــي انــه ســبق‬\n     ‫ان عقــد علــى املــرأة لكونــه كان خائفــا وبســماع اقــوال املدعــى عليــه‬\n     ‫الثانــي أقــر بأنــه عقــد ألختــه علــى املدعــى عليــه الرابــع ثــم ذهــب معــه‬\n     ‫إلــى احملكمــة كــون العقــد الــذي معهــم غيــر صحيــح ويريــدون عرضــه‬\n     ‫علــى القاضــي وبســماع اقــوال املدعــى عليــه االول ‪ ....‬اقــر بانــه قبــل ســنة‬\n     ‫ابلغــه الثانــي ان اختــه ســوف تتــزوج ويريــده ان يشــهد علــى ذلــك ثــم ذهــب‬\n     ‫معهــم إلــى احملكمــة ولــم يعلــم بــأن هنــاك زواج ســابق وبســماع اقــوال‬\n     ‫املدعــى عليــه الثالــث ‪ .....‬اقــر بانــه قبــل ســنة طلــب منــه الثانــي ان يشــهد‬\n     ‫علــى زواج اختــه وال يعلــم بأنهــا متزوجــة من الســابق وانتهــى التحقيق الى‬\n     ‫توجيــه االتهــام للمدعــى عليهمــا الثانــي والرابــع بالتدليــس امــام القاضــي‬\n     ‫الشــرعي يف امــر النــكاح واتهــام املدعــى عليهمــا االول والثالــث بشــهادة‬\n     ‫الــزور وذلــك لالدلــة والقرائــن املوضحــة بالدعــوى وحيــث ان مــا اقــدم‬\n     ‫عليــه املدعــى عليهــم وهــم بكامــل ارادتهــم املعتبــرة شــرعا فعــل محــرم‬\n     ‫ومعاقــب عليــه شــرعا لــذا اطلــب اثبــات مــا اســند اليهــم واحلكــم عليهــم‬\n     ‫بعقوبــة تعزيريــة رادعــة هــذه دعــواي وبســؤال املدعــى عليهــم أجــاب‬\n     ‫األول ‪ ...‬والثالــث ‪ ....‬بقولهمــا مــا ذكــره املدعــي العــام مــن شــهادتنا‬\n     ‫لــدى القاضــي علــى الــزواج فصحيــح ومــا ذكــره عــن شــهادة الــزور فغيــر‬\n     ‫صحيــح والواقــع أننــا حضرنــا للمحكمــة للشــهادة علــى عقــد النــكاح‬\n     ‫الــذي ســيجريه القاضــي ولــم نعلــم أنــه يوجــد عقــد ســابق هــذه إجابتنــا‬\n\n\n‫‪15‬‬\n\f‫كمــا أجــاب املدعــى عليــه الثانــي بقولــه ما ذكــره املدعي العــام صحيح‬\n‫وقــد عقــدت للرابــع علــى أختــي بواليتي وبشــهادة شــهود وبحضور مأذون‬\n‫شــرعي وكتبنــا ورقــة بذلــك ثــم تقدمنــا للمحكمــة إلثبــات العقــد‬\n‫ولكنــي كنــت خائفــا وال أعــرف أتصــرف هــذه إجابتــي كمــا أجــاب‬\n‫املدعــى عليــه الرابــع بقولــه مــا ذكــره املدعــي العــام صحيــح حيــث‬\n‫تقدمــت للمحكمــة بطلــب إثبــات الــزواج فرفضــوا اســتقبال طلبــي لعــدم‬\n‫وجــود إقامــة فعقــدت علــى املــرأة بواليــة أخيهــا وشــهادة شــهود ومــأذون‬\n‫شــرعي ثــم حصلــت علــى اإلقامــة وتقدمــت للمحكمــة بطلــب اإلثبــات‬\n‫وحصــل مــا حصــل ولــم نقصــد التدليــس ولكــن هــذا حــال كثيــر مــن‬\n‫البرماويــن واملقصــود اإلثبــات هــذه إجابتــي وأضــاف الثانــي والرابــع‬\n‫إن األول والثالــث ال يعلمــون بالعقــد األول ولــم يحضــروه وقــال املدعــي‬\n‫العــام أطلــب االطــاع علــى املعاملــة وبدراســة املعاملــة لــم أجــد للمدعــى‬\n‫عليهمــا األول والثالــث اعترافــا بالعلــم بالعقــد األول فبنــاء علــى مــا‬\n‫تقــدم مــن الدعــوى واإلجابــة وإلــى إقــرار املدعــى عليهمــا الثانــي والرابــع‬\n‫بدعــوى املدعــي العــام وإنــكار األول والثالــث وال بينــة عليهمــا لــذا فقــد‬\n‫ثبــت لــدي إدانــة املدعــى عليهمــا الثانــي ‪ ....‬والرابــع ‪ ....‬مبــا أســند إليهمــا‬\n‫مــن التدليــس أمــام القاضــي إلثبــات النــكاح وحكمــت بتعزيــر كل‬\n‫واحــد منهمــا بجلــده أربعــن جلــدة دفعــة واحــدة وأخــذ التعهــد املشــدد‬\n‫عليهمــا ‪ -‬بعــدم العــودة ملــا بــدر منهمــا ‪ -‬ولــم يثبــت لــدي إدانــة األول‬\n‫والثالــث بشــهادة الــزور وصرفــت النظــر عــن طلــب تعزيرهمــا وبعــرض‬\n‫احلكــم قنــع املدعــى عليهــم وعــارض املدعــي العــام وطلــب االســتئناف‬\n‫بالئحــة فأجيــب لطلبــه وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n           ‫محمــد وعلــى الــه وصحبــه اجمعــن حــرر يف ‪1434/7/16‬هــ‪.‬‬\n\n\n                                                                                           ‫‪16‬‬\n\f     ‫احلمــد هلل وحــده وبعــد فلــدي انــا ‪ ...‬القاضــي باحملكمــة اجلزائيــة مبكــة‬\n     ‫املكرمــة القائــم بعمــل املكتــب القضائــي الســادس بنــاء علــى خطــاب‬\n     ‫التكليــف الصــادر مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبكــة‬\n     ‫املكرمــة رقــم ‪ 342053882‬يف ‪1434/8/24‬ه ـ وعليــه فقــد عــادت‬\n     ‫املعاملــة مــن محكمــة االســتئناف وبرفقهــا القــرار رقــم ‪34328805‬‬\n     ‫يف ‪1434/10/12‬ه ـ املتضمــن املوافقــة والتصديــق علــى احلكــم وبــاهلل‬\n     ‫التوفيــق ‪.‬قاضــي اســتئناف‪ ..... /‬ختــم‪ .‬توقيــع‪ .‬قاضــي اســتئناف‪/‬د‪......‬‬\n     ‫ختــم‪ .‬توقيــع‪ .‬رئيــس الدائــرة‪ ...../‬ختــم‪ .‬توقيــع لــذا جــرى احلاقــه واثباتــه‬\n                                                         ‫حــرر يف ‪1434/11/12‬ه ـ ‪.‬‬\n\n\n\n\n‫‪17‬‬\n\f18\n\f19\n\f20\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"ca29cb00-ff93-515e-9771-74b0d5d4a25f","source_page_start":13,"source_page_end":20,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2a22f4a1748d1386745c6d6d04124aad4cb5d6e55ab8015c19a31dbd087f0860","normalized_text_hash":"aa1d44257df370348976ab49783dd7b5518a915f15884bd5b723971133faf1c8","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v24-p13-34269796"},{"id":"92ab5759-f587-5032-9d53-40ab77188311","document_type":"judgment","category":"judicial","subcategory":"general","title":"حلف مين كاذبة -اليمن يف اخلصومة جتري على نية املستحلف ال على قصد احلالف وقت حلفه -ظروف مخففة للعقوبة -توبيخ املدعى عليه يف مجلس احلكم وتعزيره بأخذ التعهد .","document_number":"35103751","case_number":"34337025","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1435/1/3","year":"1434","subject":"حلف مين كاذبة -اليمن يف اخلصومة جتري على نية املستحلف ال على قصد احلالف وقت حلفه -ظروف مخففة للعقوبة -توبيخ املدعى عليه يف مجلس احلكم وتعزيره بأخذ التعهد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 35103751 :‬تاريخه‪1435/1/3 :‬هـ‬\n                       ‫رقم الدعوى‪34337025 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n               ‫‪ 35121098‬تاريخه‪1435/1/21 :‬هـ‬\n\n\n     ‫حلــف ميــن كاذبــة ‪ -‬اليمــن يف اخلصومــة جتــري على نية املســتحلف‬\n     ‫ال علــى قصــد احلالــف وقــت حلفــه ‪ -‬ظــروف مخففــة للعقوبــة‪ -‬توبيــخ‬\n                     ‫املدعــى عليــه يف مجلــس احلكــم وتعزيــره بأخــذ التعهــد ‪.‬‬\n\n\n\n\n     ‫‪ -‬قولــه صلــى اهلل عليــه وســلم (مــن اقتطــع حــق امــرئٍ مســلم بيمينــه‬\n                                ‫فقــد أوجــب اهلل لــه النــار وحــرم عليــه اجلنــة) ‪.‬‬\n     ‫‪ -‬عــد النبــي صلــى اهلل عليــه وســلم اليمــن القتطــاع حــق امــرئ مســلم‬\n     ‫إحــدى الكبائــر كمــا يف حديــث ابــن عمــر رضــي اهلل عنــه عنــد االمــام‬\n                                                                               ‫أحمــد‪.‬‬\n\n\n\n\n     ‫جــرى توجيــه االتهــام للمدعــى عليــه باحللــف كذبـ ًا أمــام القاضــي وذلــك‬\n     ‫بعدمــا تقدمــت املدعيــة بصحيفــة دعــوى أمــام احملكمــة العامــة متهمــة‬\n     ‫املدعــى عليــه بقيامــه باحللــف كذب ـ ًا أمــام ناظــر القضيــة حيــال عــدم‬\n     ‫اســتخدامه لبطاقتهــا البنكيــة‪ -‬طلــب املدعــي العــام احلكــم عليــه‬\n     ‫بعقوبــة تعزيريــة يف احلــق العــام‪ -‬بعــرض الدعــوى علــى املدعــى عليــه‬\n     ‫أنكرهــا‪ ،‬ودفــع أنــه حلــف لهــا أنــه لــم يســحب ببطاقــة الصــراف اآلليــة‬\n     ‫التــي تخصهــا مبلغـ ًا لنفســه إال مــا تعطيــه إيــاه بطيــب نفــس منهــا‪ -‬جــرى‬\n\n‫‪21‬‬\n\f‫االطــاع علــى اعتــراف املدعــى عليــه حتقيق ـاً‪ ،‬كمــا جــرى االطــاع‬\n‫علــى صــك احلكــم املتضمــن لليمــن املذكــورة‪ -‬ملــا كانــت اليمــن يف‬\n‫اخلصومــة جتــري علــى نيــة املســتحلف ال علــى قصــد احلالــف وقــت حلفــه‬\n‫لــذا ثبتــت إدانــة املدعــى عليــه باحللــف عنــد القاضــي يف اخلصومــة التــي‬\n‫كانــت بينــه وبــن زوجتــه علــى خــاف الواقــع‪ ،‬ونظــر ًا لكــون املدعــى‬\n‫عليــه كبيــر ًا يف الســن يتصــور منــه اجلهــل يف أحــكام الشــريعة وعــدم‬\n‫فســر ميينــه مبــا هــو محتمــل فقــد‬\n                                    ‫االدراك ملــآالت األفعــال خصوصـ ًا وقــد ّ‬\n‫جــرى االكتفــاء بتوبيــخ املدعــى عليــه يف مجلــس احلكــم وتبيــن لــه‬\n‫عاقبــة اليمــن الفاجــرة ومت احلكــم بأخــذ التعهــد عليــه بعــدم العــودة‬\n‫ملــا حصــل‪ -‬بعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه القناعــة‬\n‫بــه وأمــا املدعــي العــام فقــرر االعتــراض وطلــب التمييــز مكتفي ـ ًا مبــا‬\n‫قدمــه يف الئحــة االدعــاء العــام وبعــد رفــع احلكــم حملكمــة االســتئناف‬\n                                                         ‫متــت املصادقــة عليــه‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬رئيــس احملكمــة العامــة يف عيــون‬\n‫اجلــواء وبنــاء علــى املعاملــة احملالــة لنــا من فضيلة رئيــس احملكمة العامة‬\n‫مبحافظــة عيــون اجلــواء برقــم ‪ 34337025‬وتاريــخ ‪1434/07/19‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 341752473‬وتاريــخ ‪1434/7/19‬ه ـ ففــي‬\n‫يــوم الثالثــاء املوافق‪1434/08/09‬ه ـ افتتحــت اجللســة الســاعة احلاديــة‬\n‫عشــرة صباح ـ ًا وفيهــا حضــر ‪ ......‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم ‪ ......‬بصفتــه املدعــي العــام يف هيئــة التحقيــق واالدعــاء العــام‬\n‫يف عيــون اجلــواء وحضــر حلضــوره املدعــى عليــه ‪......‬ســعودي اجلنســية‬\n\n                                                                                        ‫‪22‬‬\n\f     ‫بالســجل املدنــي رقــم ‪ ......‬وبســؤال املدعــي العــام عــن دعــواه أبــرز الئحــة‬\n     ‫الدعــوى العامــة رقــم ( ه ـ ص‪ -2/9‬أ ‪ )48/‬لعــام ‪1434‬ه ـ يف القضيــة‬\n     ‫رقــم (‪ ( 3361000089‬وفيهــا مــا نصــه‪ »:‬احلمــد هلل وحــده والصــاة‬\n     ‫والســام علــى مــن ال نبــي بعــده وبعــد ‪ :‬بصفتــي عضــو هيئــة التحقيــق‬\n     ‫واالدعــاء العــام بدائــرة محافظــة عيــون اجلــواء أدعــي علــى ‪ ،......-:‬البالــغ‬\n     ‫مــن العمــر(‪ )77‬عام ـ ًا ‪ ،‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم‬\n     ‫(‪ )......‬متعلــم ‪ ،‬متــزوج ‪ ،‬متســبب ‪ ،‬لــم يوقــف ‪.‬بتاريــخ ‪1428/5/6‬ه ـ‬\n     ‫تقدمــت املواطنــة ‪ ...... /‬بصحيفــة دعــوى أمــام احملكمــة العامــة‬\n     ‫ببريــدة تدعــي فيهــا بــأن زوجهــا املذكــور قــد قــام بتطليقهــا بتاريــخ‬\n     ‫‪1428/5/4‬ه ـ وأخــذه لذهــب عائــد لهــا بقيمــة (‪ )60000‬ســتني ألــف‬\n     ‫ريــال والقيــام ببيعــه وكذلــك أخــذه مــن راتبهــا مبلــغ وقــدره (‪)2400‬‬\n     ‫ألفــن وأربعمائــة ريــال وكفالتــه بقــرض يبلــغ (‪ )48000‬ثمــان وأربعــن‬\n     ‫ألــف ريــال مــن أحــد البنــوك وحيازتــه لبطاقــة الصرافــة العائــدة لهــا وقــد‬\n     ‫أدى املذكــور اليمــن أمــام القاضــي ونصــه (أقســم بــاهلل العلــي العظيــم‬\n     ‫أننــي لــم آخــذ البطاقــة ولــم أصــرف منهــا ولــم يقــم أحــد بصرفهــا بطلبــي‬\n     ‫وأن الــذي يســتلم الراتــب هــي وأن املبلــغ الــذي تعطينــي إيــاه إمنــا هــو‬\n                                                                  ‫بطيبــة نفــس منهــا) ‪.‬‬\n     ‫وبتاريــخ ‪1433/4/17‬ه ـ تقدمــت املدعيــة بصحيفــة دعــوى أمــام‬\n     ‫احملكمــة العامــة متهمــة املذكــور بقيامــه باحللــف كذبـ ًا أمــام فضيلــة‬\n                  ‫ناظــر القضيــة حيــال عــدم اســتخدامه لبطاقــة صرافتهــا ‪.‬‬\n     ‫وباســتجواب املذكــور اعتــرف بقيامــه بالصــرف مــن بطاقــة زوجتــه‬\n     ‫الســابقة وأنــه يقــوم بإعطائهــا املــال املصــروف مــن البطاقــة وذكــر أنــه‬\n         ‫يقصــد باحللــف أمــام القاضــي بأنــه لــم يصــرف منهــا شــيء لنفســه ‪.‬‬\n\n\n‫‪23‬‬\n\f‫وملــا أشــير إليــه إقــرار توجيــه االتهــام ل‪......‬باحللــف كذبـ ًا أمــام القاضــي‬\n‫حســبما تضمنــه اعترافــه املــدون علــى الصفحتــن رقــم (‪ )2،1‬مبحضــر‬\n                                             ‫االســتجواب املرفــق لفــه رقــم (‪. )49‬‬\n‫وحيــث أنــه مــا أقــدم عليــه املذكــور فعــل محــرم ومعاقــب عليــه‬\n‫شــرعاً‪،‬لذا أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة‬\n‫تردعــه وتزجــر غيــره اســتناد ًا للمــادة (‪ )126‬مــن نظــام اإلجــراءات‬\n‫اجلزائيــة )علم ـ ًا أن احلــق اخلــاص مــازال قائم ـاً» ( هكــذا ادعــى املدعــي‬\n‫العــام ولــدى عــرض الدعــوى علــى املدعــى عليــه أجــاب بقولــه‪ :‬مــا ذكــره‬\n‫املدعــي العــام مــن أننــي حلفــت كاذبـ ًا أمــام القاضــي الــذي كان ينظــر‬\n‫دعــوى ماليــة مقامــة مــن زوجتــي ضــدي يف احملكمــة العامــة ببريــدة‬\n‫فغيــر صحيــح بــل الصحيــح أننــي حلفــت لهــا بأننــي لــم أســحب ببطاقــة‬\n‫الصــراف اآلليــة التــي تخصهــا مبلغـ ًا لنفســي إال مــا تعطينــي إيــاه بطيــب‬\n‫نفــس منهــا هكــذا أجــاب فســألت املدعــي العــام هــل لديــه بينــة علــى مــا‬\n‫ادعــاه فأجــاب قائـاً‪ :‬بينتــي علــى ذلــك مــا أشــير إليــه يف الئحــة االدعــاء‬\n‫العــام مــن اعتــراف املدعــى عليــه وأطلــب الرجــوع إليــه‪ ،‬هكــذا أجــاب‬\n‫فجــرى االطــاع علــى اســتجواب املدعــى عليــه علــى ص ‪ 2 - 1‬مــن ملــف‬\n‫التحقيــق لفــه ‪ 49‬وقــد وجــد فيــه مــا نصــه « أنــا حلفت أمــام القاضي أني‬\n‫لــم آخــذ البطاقــة ولــم أصــرف منهــا شــيئ ًا لنفســي ولم يقم أحــد بالصرف‬\n‫منهــا لنفســي ومــا أقــوم بــه هــو أنــي آخــذ البطاقــة مــن زوجتــي ثــم أعطيها‬\n‫ملوظــف البنــك ليصــرف لنــا مــن آلــة الصــراف ثــم أعيــد البطاقــة واملبلــغ‬\n‫لزوجتــي « ومــا نصــه « أنــا مــا قصــدت أمــام القاضــي أن أصــرف منهــا‬\n‫شــيئ ًا لنفســي وإمنــا آخــذ البطاقــة وأقــوم بالســحب مــن اآللــة مــن خــال‬\n‫أحــد العاملــن بالبنــك بنــاء لطلــب زوجتــي وحيــث إننــي كبيــر يف الســن‬\n\n\n                                                                                         ‫‪24‬‬\n\f     ‫فلــم يتضــح لــي مــا حلفــت بــه أمــام القاضــي « هــذا مــا تضمنــه اســتجواب‬\n     ‫املدعــى عليــه وبعرضــه عليــه صــادق علــى مــا جــاء فيــه ثــم جــرى االطــاع‬\n     ‫علــى الصــك الصــادر مــن احملكمــة العامــة ببريــدة برقــم ‪11 / 1 / 134‬‬\n     ‫يف ‪1428/7/17‬ه ـ فوجــد متضمن ـ ًا دعــوى مــن مــوكل زوجــة املدعــى‬\n     ‫عليــه ‪......‬ضــد ‪(......‬املدعــى عليــه هنــا) والتــي يطلــب فيهــا املدعــي إلــزام‬\n     ‫املدعــى عليــه بإعــادة مبالــغ أخذهــا مــن موكلتــه وقــد جــاء فيــه مــا نصــه‬\n     ‫(وطلــب املدعــي حلفــه علــى رواتبهــا بأنــه لــم يأخــذ بطاقتهــا ولــم يأخــذ‬\n     ‫أي مبلــغ إال بطيبــة نفــس منهــا فاســتعد بذلــك ثــم قــام وقــال أقســم بــاهلل‬\n     ‫العظيــم أنــي لــم آخــذ البطاقــة ولــم أصــرف فيهــا ولــم يقــم أحــد بصرفهــا‬\n     ‫بطلبــي وأن الــذي يســتلم الراتــب هــي وأن املبلــغ الــذي تعطينــي امنــا هــو‬\n     ‫بطيــب نفــس منهــا هكــذا حلــف) املنتهــي برجــوع حاكمــه عمــا حكــم‬\n     ‫بــه وللتأمــل واصــدار مــا يلــزم جــرى رفــع اجللســة وحــددت للطرفــن‬\n     ‫موعــد ًا يف يــوم الســبت املوافــق ‪1434/11/8‬ه ـ الســاعة العاشــرة‬\n     ‫صباحـ ًا وعليــه حصــل التوقيــع وقــد أقفلــت هــذه اجللســة الســاعة احلاديــة‬\n     ‫عشــرة صباح ـ ًا وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n     ‫آلــه وصحبــه وســلم حــرر يف ‪1434/8/9‬ه ـ احلمــد هلل وحــده وبعــد فلــدي‬\n     ‫أنــا ‪......‬رئيــس احملكمــة العامــة مبحافظــة عيــون اجلــواء وبنــاء علــى‬\n     ‫املعاملــة املقيــدة باحملكمــة برقم ‪ 341752473‬وتاريخ ‪1434/7/19‬هـ‬\n     ‫ففــي يــوم الثالثــاء املوافــق‪ 1434/11/04‬ه ـ افتتحــت اجللســة الســاعة‬\n     ‫‪ 00:11‬صباح ـ ًا وفيهــا حضــر املدعــي العــام بدائــرة التحقيــق واالدعــاء‬\n     ‫العــام مبحافظــة عيــون اجلــواء ‪......‬واملدعــى عليــه ‪......‬وبدراســة القضيــة‬\n     ‫وتأملهــا وملــا كان املدعــي العــام يطلــب يف دعــواه هــذه احلكــم بتعزيــر‬\n     ‫املدعــى عليــه جــزاء حلفــه كاذب ـ ًا أمــام القاضــي يف القضيــة الصــادر‬\n\n\n‫‪25‬‬\n\f‫فيهــا الصــك رقــم ‪ 11/1/134‬يف ‪1428/7/17‬ه ـ مــن احملكمــة العامة‬\n‫ببريــدة املنتهــي برجــوع القاضــي عمــا حكــم بــه وملــا كان املدعــى عليــه‬\n‫مقــر ًا بــأداء اليمــن املرصــود نصهــا يف ســياق الدعــوى يف اجللســة املاضية‬\n‫مبينـ ًا أن قصــده وقــت حلفــه أنــه لــم يصــرف مــن بطاقــة الصــراف اآللــي‬\n‫التابعــة لزوجتــه شــيئ ًا لنفســه وملــا كانــت اليمــن يف اخلصومــة جتــري‬\n‫علــى نيــة املســتحلف ال علــى قصــد احلالــف وقــت حلفــه فقــد ثبــت لــدي‬\n‫ادانــة املدعــى عليــه ‪......‬باحللــف عنــد القاضــي يف اخلصومــة التــي كانــت‬\n‫بينــه وبــن زوجتــه علــى خــاف الواقــع وحيــث جــاء الوعيــد الشــديد ملــن‬\n‫ـرئ مســلم بيمينــه يف قولــه صلــى اهلل عليــه وســلم (مــن‬  ‫اقتطــع حــق امـ ٍ‬\n‫ـرئ مســلم بيمينــه فقــد أوجــب اهلل لــه النــار وحــرم عليــه‬\n                                                               ‫اقتطــع حــق امـ ٍ‬\n‫وعدهــا النبــي صلــى اهلل عليــه وســلم احــدى الكبائــر كمــا يف‬     ‫اجلنــة) ّ‬\n‫حديــث ابــن عمــر رضــي اهلل عنــه عنــد االمــام احمــد وملــا كان املدعــى‬\n‫عليــه كبيــر ًا يف الســن يتصــور منــه اجلهــل يف أحــكام الشــريعة وعــدم‬\n‫فســر ميينــه مبــا هــو محتمــل‬ ‫االدراك ملــآالت األفعــال خصوص ـ ًا وقــد ّ‬\n‫فلذلــك فقــد اكتفيــت يف احلــق العــام بتوبيــخ املدعــى عليــه يف مجلــس‬\n‫احلكــم وبينــت لــه عاقبــة اليمــن الفاجــرة ففهــم ذلــك وحكمــت بأخــذ‬\n‫التعهــد عليــه بعــدم العــودة ملــا حصــل منــه هــذا مــا حكمــت بــه يف احلــق‬\n‫العــام وبعرضــه علــى الطرفــن قــرر املدعــى عليــه القناعة بــه وأما املدعي‬\n‫العــام فقــد أبــدى اعتراضــه وطلــب التمييــز مكتفيـ ًا مبــا قدمــه يف الئحة‬\n‫ـاء عليــه فســيجري اصــدار قــرار شــرعي بهــذا احلكــم‬    ‫االدعــاء العــام وبنـ ً‬\n‫ـاء علــى املــادة ‪193‬‬ ‫وبعثــه حملكمــة االســتئناف مبنطقــة القصيــم بنـ ً‬\n‫مــن نظــام االجــراءات اجلزائيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/11/4‬ه ـ الســاعة‬\n\n\n                                                                                       ‫‪26‬‬\n\f     ‫‪ 11:30‬احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة األولى‬\n     ‫لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة القصيــم علــى‬\n     ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة يف محافظــة عيــون‬\n     ‫اجلــواء الشــيخ‪....../‬برقم ‪ 341752473‬وتاريــخ ‪1435/1/11‬هــ؛ املقيــدة‬\n     ‫لدينــا برق ــم ‪ 341752473‬وتاريــخ ‪1435/1/14‬هــ؛ املرفــق بهــا القــرار‬\n     ‫رقــم ‪ 35103701‬وتاريــخ ‪1435/1/3‬هــ؛ الصــادر مــن فضيلتــه ؛اخلــاص‬\n     ‫بدعــوى املدعــي العــام ضد‪....../‬؛التهامــه باحللــف كاذب ـ ًا وقــد تضمــن‬\n     ‫القــرار حكــم فضيلتــه بتوبيــخ املدعــى عليــه وأخــذ التعهــد علــى النحــو‬\n     ‫املفصــل فيــه؛ وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا‬\n     ‫باألكثريــة املصادقــة علــى احلكــم‪ .‬واهلل املوفــق‪ ،‬وصلــى اهلل علــى‬\n                                         ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪27‬‬\n\f28\n\f29\n\f30\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"ca29cb00-ff93-515e-9771-74b0d5d4a25f","source_page_start":21,"source_page_end":30,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"945d92277bd2b9844f3fce782af3644a170798546560e77b9d5a3761b268af73","normalized_text_hash":"a03aa25d2c83f92c25a9480091812093e67eb50d21d09da89ee227fec9084aed","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v24-p21-35103751"},{"id":"4ec60bab-eef8-5eed-b414-078348d6ae2c","document_type":"judgment","category":"judicial","subcategory":"general","title":"تفحيط-مخالفات مرورية -تقدير قيمة سيارة مستأجرة -إقرار بالتفحيط -تعزير بالسجن والغرامة مبثل قيمة السيارة املرتكب عليها اجلرمية كونها مستأجرة.","document_number":"33400860","case_number":"33183096","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/09/03","year":"1434","subject":"تفحيط-مخالفات مرورية -تقدير قيمة سيارة مستأجرة -إقرار بالتفحيط -تعزير بالسجن والغرامة مبثل قيمة السيارة املرتكب عليها اجلرمية كونها مستأجرة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 33400860:‬تاريخه‪1433/09/03 :‬هـ‬\n                          ‫رقم الدعوى‪33183096:‬‬\n                    ‫رقم قرار التصديق من محكمة‬\n          ‫االستئناف‪ 341163:‬تاريخه‪1434/01/04:‬هـ‬\n\n\n\n     ‫تفحيط‪-‬مخالفــات مروريــة ‪ -‬تقديــر قيمــة ســيارة مســتأجرة‪ -‬إقــرار‬\n     ‫بالتفحيــط‪ -‬تعزيــر بالســجن والغرامــة مبثــل قيمــة الســيارة املرتكــب‬\n                                           ‫عليهــا اجلرميــة كونهــا مســتأجرة‪.‬‬\n\n\n\n\n     ‫‪ -‬الفقــرة (ج) مــن املــادة (‪ )69‬مــن نظــام املــرور والفقــرة (‪ )2/69‬مــن‬\n                                         ‫الالئحــة التنفيذيــة لنظــام املــرور ‪.‬‬\n\n\n\n\n     ‫مت توجيــه االتهــام للمدعــى عليــه مبمارســة التفحيــط للمــرة الثالثــة‬\n     ‫وذلــك بعــد اســتيقافه الرتكابــه مخالفــة التفحيــط وعــدم حملــه رخصــة‬\n     ‫قيــادة وتنزيــل املركبــة وتبــن أن عليــه (‪ )32‬مخالفــة مروريــة منهــا‬\n     ‫(‪ )3‬مخالفــات تفحيــط وأن املركبــة مســتأجرة‪ -‬طلــب املدعــي العــام‬\n     ‫بتعزيــره بســجنه وتغرميــه بدفــع قيمــة املثــل للمركبــة التــي مــارس عليهــا‬\n     ‫مخالفــة التفحيــط اســتنادا للفقــرة (ج) مــن املــادة (‪ )69‬مــن نظــام املــرور‬\n     ‫‪ -‬بعــرض الدعــوى علــى املدعــى عليــه صــادق عليها‪-‬جــرى االطــاع‬\n     ‫علــى تقديــر قيمــة الســيارة الصــادر مــن ثالثــة معــارض مببلــغ خمســن‬\n     ‫ألــف ريــال كمــا جــرى االطــاع علــى محضــر ضبــط املخالفــة املروريــة‬\n\n\n‫‪31‬‬\n\f‫املتضمــن طبــق مــا ذكــر املدعــي العــام يف دعــواه‪ -‬ثبتــت إدانــة املدعــى‬\n‫عليــه مبمارســة التفحيــط للمــرة الثالثــة ومت احلكــم عليــه بســجنه ملــدة‬\n‫شــهرين‪ ،‬وتغرميــه مبلــغ خمســن ألــف ريــال تدفــع للجهــة املختصــة‪-‬‬\n‫بعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه عــدم القناعــة باحلكــم‬\n‫وطلــب االســتئناف بالئحــة وقــرر املدعــي العــام عــدم االعتــراض‪-‬‬\n                               ‫تصديــق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي‬\n‫أنــا ‪ ....‬القاضــي باحملكمــة اجلزائيــة بالدمــام بنــاء علــى املعاملــة الــواردة‬\n‫مــن هيئــة التحقيــق واإلدعــاء العــام واملقيــدة لــدى احملكمــة برقــم‬\n‫‪ 33482273‬وتاريــخ ‪1433/3/14‬ه ـ واحملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة بالدمــام برقــم ‪ 33183096‬وتاريــخ ‪1433/3/14‬ه ـ‬\n‫افتتحــت اجللســة يف يــوم األحــد ‪1433/9/3‬ه ـ الســاعة الثانيــة وفيهــا‬\n‫ا فيهــا بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة‬‫قــدم املدعــي العــام ‪ ...‬دعــواه قائ ـ ً‬\n‫اإلدعــاء العــام لفــرع املنطقــة الشــرقية أدعــي علــى‪ .... /‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪ ....‬حيــث إنــه باالطــاع علــى محضــر‬\n‫ضبــط املخالفــة املروريــة املعــد مــن قبــل دوريــة املــرور الســرية تبــن أنــه‬\n‫بتاريــخ ‪1433/2/16‬ه ـ مت اســتيقاف ســيارة مــن نــوع نيســان بكــب‬\n‫لونهــا ذهبــي رقــم اللوحــة (…صنــع ســنة ‪2010‬م بقيــادة املدعــى عليــه‬\n‫وذلــك الرتكابــه مخالفــة التفحيــط وعــدم حملــه رخصــة قيــادة وتنزيــل‬\n‫املركبــة وتبــن أن عليــه (‪ )32‬مخالفــة مروريــة منهــا (‪ )3‬مخالفــات‬\n‫تفحيــط وأن املركبــة مســتأجرة باســم …‪ .‬وباســتجواب املدعــى عليــه‬\n                                                                                         ‫‪32‬‬\n\f     ‫أقــر مبمارســته التفحيــط وقــد انتهــى التحقيــق إلــى مســؤولية … جتــاه‬\n     ‫مخالفــة ممارســة التفحيــط للمــرة الثالثــة وذلــك لألدلة والقرائــن التالية‪:‬‬\n     ‫‪-1‬إقــرار املدعــى عليــه املنــوه عنــه واملــدون علــى الصفحــة رقــم (‪)3-2‬‬\n     ‫مــن ملــف التحقيــق املرفــق لفــة رقــم (‪ -2 )1‬محضــر ضبــط املخالفــة‬\n     ‫املرفــق لفــة (‪ -3 )18‬بيــان مخالفــات التفحيــط املســجلة عليــه املرفــق‬\n     ‫لفــة (‪ )5-3‬وحيــث إن مــا أقــدم عليــه املدعــى عليــه وهــو بكامــل أهليتــه‬\n     ‫املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه نظامـ ًا أطلــب إثبــات مــا أســند‬\n     ‫إليــه والنظــر يف احلكــم بســجنه وتغرميــه بدفــع قيمــة املثــل للمركبــة‬\n     ‫املوصوفــة التــي مــارس عليهــا مخالفــة التفحيــط اســتنادا للفقــرة (ج)‬\n     ‫مــن املــادة (‪ )69‬مــن نظــام املــرور هكــذا ادعــى وبعــرض الدعــوى‬\n     ‫ا مــا ذكــره املدعــي العــام مــن قيامــي‬    ‫علــى املدعــى عليــه أجــاب قائ ـ ً‬\n     ‫بالتفحيــط للمــرة الثالثــة صحيــح هكــذا أجــاب ثــم جــرى الرجــوع‬\n     ‫إلــى املعاملــة فوجــدت علــى لفــة رقــم (‪ )9‬تقديــر لقيمــة الســيارة مببلــغ‬\n     ‫خمســن ألــف ريــال صــادر مــن ثالثــة معــارض كمــا وجــدت علــى لفــة‬\n     ‫رقــم (‪ )18‬محضــر ضبــط املخالفــة املروريــة املتضمــن طبــق مــا ذكــر‬\n     ‫ـاء علــى مــا تقــدم مــن دعــوى املدعــي العــام‬  ‫املدعــي العــام يف دعــواه فبنـ ً‬\n     ‫وإجابــة املدعــى عليــه وإقــراره بالدعــوى وهــو بكامــل أهليتــه املعتبــرة‬\n     ‫شــرع ًا وبنــاء علــى الفقــرة (ج) مــن املــادة (‪ )69‬مــن نظــام املــرور والفقــرة‬\n     ‫ـاء علــى التقديــر الــذي‬\n                              ‫(‪ )2/69‬مــن الالئحــة التنفيذيــة لنظــام املــرور وبنـ ً‬\n     ‫قيمــت بــه الســيارة لــذا فقــد ثبــت لــدي إدانــة املدعــى عليــه مبمارســة‬\n     ‫التفحيط للمرة الثالثة وقررت اآلتي‪ :‬أوالً‪ :‬ســجنه ملدة شــهرين حتتســب‬\n     ‫منهــا مــدة إيقافــه‪ .‬ثاني ـاً‪ :‬تغــرمي املدعــى عليــه بدفــع مبلــغ خمســن ألــف‬\n     ‫ريــال تدفــع للجهــة املختصــة وبذلــك حكمــت وبعــرض احلكــم علــى‬\n\n\n‫‪33‬‬\n\f‫الطرفــن قــرر املدعــى عليــه عــدم القناعــة باحلكــم وطلــب االســتئناف‬\n‫بالئحــة يقدمهــا فأفهمتــه بأنــه ســوف يجــري بعــد قليــل تســليمه نســخة‬\n‫مــن احلكــم ليقــدم اعتراضــه خــال ثالثــن يوم ـ ًا مــن اآلن يكــون‬\n‫حقــه يف االســتئناف بعــد مضــي هــذه املــدة ســاقط ًا ففهــم ذلــك وأمــا‬\n‫املدعــي العــام فقــرر عــدم االعتــراض وبــاهلل التوفيــق وصلــى اهلل وســلم‬\n‫علــى نبينــا محمــد‪ .‬حــرر يف احلمــد هلل وحــده وبعــد ففــي يــوم األثنــن‬\n‫‪1434/1/26‬ه ـ افتتحــت اجللســة الســاعة التاســعة والربــع وفيهــا وردتنــا‬\n‫املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية وبرفقهــا القــرار‬\n‫الصــادر مــن الدائــرة اجلزائيــة األولــى برقــم ‪ 341163‬يف ‪1434/1/4‬ه ـ‬\n‫املتضمــن املصادقــة علــى احلكــم وبــاهلل التوفيــق وصلــى اهلل وســلم علــى‬\n                   ‫نبينــا محمــد‪ .‬حــرر يف ‪1434/1/26‬ه ـ ‪1433/9/3‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                 ‫‪34‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"ca29cb00-ff93-515e-9771-74b0d5d4a25f","source_page_start":31,"source_page_end":34,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d6611d2fb2c48b0a6d107036e0307334ea9e5cb7b69605adf4a9206eda6dd692","normalized_text_hash":"cba58cca973a568afd052aee1fdb0c69c764f1548e917fce64a9a74ec87a0fbe","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v24-p31-33400860"},{"id":"850543f8-9588-5e84-8676-1369926d95c5","document_type":"judgment","category":"judicial","subcategory":"general","title":"تفحيط -تفحيط وقيادة بتهور للمرة الثالثة -مسؤولية املدعى عليه جتاه مخالفته املرورية بنسبة - %100اقرار بالتفحيط وقيادة السيارة بتهور -إثبات إدانة -تعزير بالسجن ومصادرة السيارة املستخدمة بالتفحيط -الفقرة ( ج ) من املادة ( ) 69من نظام املرور.","document_number":"3422084","case_number":"33400147","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف باملنطقة الشرقية مبوجب اخلطاب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/01/25","year":"1434","subject":"تفحيط -تفحيط وقيادة بتهور للمرة الثالثة -مسؤولية املدعى عليه جتاه مخالفته املرورية بنسبة - %100اقرار بالتفحيط وقيادة السيارة بتهور -إثبات إدانة -تعزير بالسجن ومصادرة السيارة املستخدمة بالتفحيط -الفقرة ( ج ) من املادة ( ) 69من نظام املرور.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك ‪ 3422084:‬تاريخه‪1434/01/25 :‬هـ‬\n                          ‫رقم الدعوى‪33400147:‬‬\n                    ‫رقم قرار التصديق من محكمة‬\n         ‫االستئناف‪ 34204315:‬تاريخه‪1434/05/04:‬ه‬\n\n\n\n     ‫تفحيــط ‪ -‬تفحيــط وقيــادة بتهــور للمــرة الثالثــة ‪ -‬مســؤولية املدعــى‬\n     ‫عليــه جتــاه مخالفتــه املروريــة بنســبة ‪ - %100‬اقــرار بالتفحيــط وقيــادة‬\n     ‫الســيارة بتهــور ‪ -‬إثبــات إدانــة ‪ -‬تعزيــر بالســجن ومصــادرة الســيارة‬\n                                                        ‫املســتخدمة بالتفحيــط‬\n\n\n\n\n                               ‫‪ -‬الفقرة ( ج ) من املادة ( ‪ ) 69‬من نظام املرور‪.‬‬\n\n\n\n\n     ‫مت توجيــه االتهــام ل ــلمدعى عليــه بالقيــام بالتفحيــط والقيــادة بتهــور‬\n     ‫للمــرة الثالثــة وحتملــه كامــل املســؤولية بنســبة ‪ %100‬جتــاه مخالفاتــه‬\n     ‫وذلــك بعــد القبــض عليــه بعــد ممارســة «التفحيــط» وتبــن أن لديــه عــدد‬\n     ‫(‪ )11‬مخالفــة مروريــة منهــا ثــاث مخالفــات تفحيــط ‪ -‬بالبحــث عمــا‬\n     ‫إذا كان لديــه ســوابق اتضــح عــدم وجــود ســوابق مســجلة عليــه‪ -‬طلــب‬\n     ‫املدعــي العــام احلكــم علــى املدعــى عليــه بعقوبــة تعزيريــة ومبصــادرة‬\n     ‫الســيارة اســتناد ًا للمــادة (‪/69‬ج) مــن نظــام املــرور ‪ -‬بعــرض دعــوى‬\n     ‫ا وقــرر‬‫املدعــي العــام علــى املدعــى عليــه صــادق عليهــا جملــة وتفصي ـ ً‬\n     ‫أن ملكيــة الســيارة عائــدة إليــه‪ -‬مت احلكــم عليــه بســجنه ملــدة ثالثــة‬\n\n\n‫‪35‬‬\n\f‫أشــهر ومصــادرة الســيارة املشــار إليهــا يف الدعــوى‪ -‬بعــرض احلكــم‬\n‫علــى الطرفــن قــرر املدعــى عليــه االعتــراض بالئح ـ ٍة اعتراضيــة وقــرر‬\n‫املدعــي العــام عــدم االعتــراض وبعــد رفــع احلكــم حملكمــة االســتئناف‬\n                                                       ‫متــت املصادقــة عليــه‪.‬‬\n\n\n\n\n‫اجلزائيــة‬\n    ‫ّ‬        ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي يف احملكمــة‬\n‫بالدمــام ويف يــوم األربعــاء املوافق‪1434/01/21‬ه ـ افتتحــت اجللســة‬\n‫الســاعة ‪ 08 : 45‬وفيهــا قــدم املدعــي العــام ‪ ...‬دعــواه ضــد املدعــى عليــه‬\n‫ا فيهــا ‪ :‬إنــه بتاريخ‪1433/3/17‬ه ـ وأثنــاء قيــام الدوريــة األمنيــة‬  ‫‪ .....‬قائـ ً‬\n‫بعملهــا مبدينــة الدمــام مت مالحظــة ســيارة مــن نــوع (كابــرس) تاريــخ‬\n‫الصنــع (‪2007‬م) حتمــل اللوحــة رقــم (‪ ). . . .‬ميــارس مخالفــة التفحيــط‬\n‫والقيــادة بتهــور ومت التعميــم علــى الســيارة ويف تاريــخ ‪1433/4/12‬ه ـ مت‬\n‫القبــض علــى الســيارة املذكــورة بقيــادة املدعــى عليــه وتبــن أن لديــه‬\n‫عــدد (‪ )11‬مخالفــة مروريــة منهــا عــدد (‪ )3‬مخالفــات تفحيــط وبســماع‬\n‫أقوالــه واســتجوابه ‪ :‬أقــر بصحــة الواقعــة وأن الســيارة التــي معــه تعــود‬\n‫ملكيتهــا لــه شــخصي ًا وانتهــى التحقيــق معــه إلــى توجيــه االتهــام ل ــه‬\n‫بالقيــام مبخالفــة التفحيــط والقيــادة بتهــور للمــرة الثالثــة وحتملــه‬\n‫كامــل املســؤولية بنســبة ‪ %100‬جتــاه مخالفاتــه وذلــك لألدلــة والقرائــن‬\n‫التاليــة‪ -1:‬مــا جــاء بأقوالــه املدونــة علــى الصفحــات رقــم (‪3‬ـ ــ‪ )4‬املرفقــة‬\n‫علــى اللفــة رقــم (‪ -2)1‬مــا جــاء بقــرارات هيئــة الفصــل واملنازعــات جتــاه‬\n‫مخالفــة (التفحيــط) الثــاث املرفقــة على اللفات رقم ( ‪14‬ـ ‪15‬ـ‪-3)16‬ما‬\n‫جــاء بصحيفــة املخالفــات املســجلة عليــه وعددهــا (‪ )11‬مخالفــة املرفقــة‬\n\n                                                                                        ‫‪36‬‬\n\f     ‫علــى اللفــة رقــم (‪ )4‬وبالبحــث عمــا إذا كان لديــه ســوابق اتضــح عــدم‬\n     ‫وجــود ســوابق مســجلة عليــه وحيــث إن مــا أقــدم عليــه املدعــى عليــه وهــو‬\n     ‫ومعاقب عليه شــرع ًا ونظام ًا‬\n                                ‫ٌ‬       ‫بكامــل أهليتــه املعتبــرة شــرع ًا فعــلٌ محــرم‬\n     ‫أطلــب إثبــات مــا ُأســند إليــه واحلكــم عليه بعقوبــة تعزيرية تزجــره وتردع‬\n     ‫غيــره ومبصــادرة الســيارة املشــار إليهــا اســتناد ًا للمــادة (‪/69‬ج) من نظام‬\n     ‫املــرور واهلل املوفــق ويف هــذه اجللســة حضــر املدعــى عليــه ‪ ....‬ســعودي‬\n     ‫اجلنســية مبوجــب بطاقــة الهويــة الوطنيــة املــدون بهــا الرقــم ‪ ...‬وبعــرض‬\n     ‫ا ‪ :‬مــا ذكــره املدعــي العــام يف‬    ‫دعــوى املدعــي العــام عليــه أجــاب قائ ـ ً‬\n     ‫دعــواه صحيــح فقــد قمــت بالتفحيــط وقيــادة الســيارة بتهــور وصــدرت‬\n     ‫علــى مخالفــة مروريــة وهــذه املخالفــة ُتعتبــر املخالفــة املروريــة الثالثــة يف‬\n     ‫التفحيــط وأنــا مقتنـ ٌـع بإدانتــي يف هــذه املخالفــات الثــاث بنســبة ‪%100‬‬\n     ‫والســيارة املذكــورة يف الدعــوى تخصني وباســمي هــذه إجابتي ‪ .‬فنظر ًا‬\n     ‫ملــا تقــدم مــن الدعــوى واإلجابــة وحيــث صــادق املدعــى عليــه علــى دعــوى‬\n     ‫ـور يف جوابــه أعــاه وبعــد االطــاع‬      ‫املدعــي العــام وأقــر مبــا هــو مذكـ ٌ‬\n     ‫ـاء علــى الفقــرة ( ج ) مــن املــادة رقــم ( ‪ ) 69‬مــن‬ ‫علــى طيــات املعاملــة وبنـ ً‬\n     ‫نظــام املــرور لذلــك كلــه فقــد ثبــت لــدي إدانــة املدعــى عليــه بقيــادة‬\n     ‫الســيارة بتهــور وقيامــه بالتفحيــط وصــدور املخالفــة املروريــة الثالثــة يف‬\n     ‫ذلــك ومســؤوليته جتــاه هــذه املخالفــات الثــاث بنســبة ‪ %100‬وقــررت‬\n     ‫معاقبتــه علــى ذلــك كلــه مبــا يلــي ‪ :‬أوالً‪ -‬بســجنه ملــدة ثالثــة أشــهر‬\n     ‫ُيحســب منهــا مــدة إيقافــه علــى ذمــة القضيــة قبــل إطالقــه بالكفالــة‬\n     ‫ثانيـاً‪ -‬مصــادرة ســيارته املشــار إلــى أوصافهــا يف الدعــوى وبذلــك أجمــع‬\n     ‫حكمــت وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه االعتــراض‬\n     ‫بالئحـ ٍة اعتراضيــة مقدمـ ًة منــه ف ُأجيــب لطلبــه وجــرى إفهامــه أن عليــه‬\n\n\n‫‪37‬‬\n\f‫املراجعــة يــوم الســبت ‪1434/1/24‬ه ـ الســاعة ‪ 12.30‬الســتالم صــورة‬\n‫مــن احلكــم وأنــه يف التاريــخ املذكــور ســوف يتــم إيــداع القــرار ملــف‬\n‫الدعــوى وســوف يكــون ذلــك اإليــداع مجريـ ًا ملــدة الثالثــن يومـ ًا ُيقــدم‬\n‫خاللهــا الئحتــه االعتراضيــة وأنــه مبضــي هــذه املــدة دون تقــدمي الالئحــة‬\n‫ويرفــع احلكــم حملكمــة االســتئناف‬         ‫ســوف يســقط حقــه يف تقدميهــا ُ‬\n‫بدونهــا فامتثــل وأمــا املدعــي العــام فقــرر عــدم االعتــراض واهلل املوفــق‬\n‫وصلــى اهلل علــى نبينــا محمــد وآلــه وســلم احلمــد هلل وحــده وبعــد ويف يــوم‬\n‫اإلثنــن املوافق‪1434/01/26‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــى‬\n‫عليــه وجــرى تســليمه صــورة مــن احلكــم الصــادر برقــم ‪ 3422084‬يف‬\n‫‪1434/1/25‬ه ـ وجــرى إفهامــه بــأن عليــه تقــدمي الئحتــه االعتراضيــة‬\n‫خــال املــدة املتبقيــة وقدرهــا ( ‪ ) 29‬تســعه وعشــرون يوم ـ ًا مــن تاريــخ‬\n‫اليــوم وأنــه مبضــي هــذه املــدة دون تقــدمي الالئحــة ســوف يســقط حقــه يف‬\n‫ويرفــع احلكــم مبشــيئة اهلل تعالــى حملكمــة االســتئناف بدونهــا‬     ‫تقدميهــا ُ‬\n‫فامتثــل واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وســلم ‪ .‬احلمــد‬\n‫هلل وحــده وبعــد ويف يــوم اإلثنــن املوافق‪1434/02/25‬ه ـ افتتحــت‬\n‫اجللســة وقــد وردت الالئحــة االعتراضيــة املقدمــة مــن املدعــى عليــه‬\n‫املقيــدة برقــم ‪ 34445549‬وتاريــخ ‪1434/2/23‬ه ـ وجــرى االطــاع‬\n‫عليهــا ولــم أجــد فيهــا مــا يوجــب الرجــوع عمــا حكمــت بــه وســوف‬\n‫يتــم رفــع احلكــم حملكمــة االســتئناف بالشــرقية لتدقيقــه واهلل املوفــق‬\n‫وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم احلمــدهلل وحــده وبعــد‬\n‫ويف يــوم االثنــن املوافق‪1434/06/05‬ه ـ فتحــت اجللســة وقــد وردت‬\n‫املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية مبوجــب اخلطــاب‬\n‫رقــم ‪ 34648389‬يف ‪1434/05/07‬ه ـ وبرفقهــا قــرار أصحــاب الفضيلــة‬\n\n\n                                                                                      ‫‪38‬‬\n\f     ‫قضــاة الدائــرة اجلزائيــة األولــى مبحكمــة االســتئناف باملنطقة الشــرقية‬\n     ‫رقــم ‪ 34204315‬يف ‪1434/05/04‬ه ـ املتضمــن املصادقــة علــى احلكــم‬\n     ‫لــذا جــرى إحلاقــه واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وســلم ‪.‬‬\n\n\n\n\n‫‪39‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"ca29cb00-ff93-515e-9771-74b0d5d4a25f","source_page_start":35,"source_page_end":39,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0f2f22dcc2575d7d8d319d916016f4db6079366922ca8cb5fac8513e50842d0b","normalized_text_hash":"88df1e5ac1f4053888ba9c83d89a09e6258660f82dd46b7fc5dfcbef0c60e0d4","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v24-p35-3422084"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"e1eab3f2-2955-58c1-b1ca-52754c2e0845","document_type":"judgment","category":"judicial","subcategory":"general","title":"ممارسة مهنة بطريقة غير نظامية -توليد وإجهاض النساء - شهادة على إقرار -إنكار املدعى عليها -ثبوت إدانة املدعى عليها -تعزير بالسجن ومصادرة األجهزة الطبية -صرف النظر عن مصادرة املبلغ املالي املضبوط .","document_number":"3446763","case_number":"33702646","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/02/5","year":"1434","subject":"ممارسة مهنة بطريقة غير نظامية -توليد وإجهاض النساء - شهادة على إقرار -إنكار املدعى عليها -ثبوت إدانة املدعى عليها -تعزير بالسجن ومصادرة األجهزة الطبية -صرف النظر عن مصادرة املبلغ املالي املضبوط .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 3446763 :‬تاريخه ‪1434/02/5 :‬هـ‬\n                        ‫رقم الدعوى‪33702646 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34181595‬تاريخه‪1434/5/5 :‬هـ‬\n\n\n      ‫ممارســة مهنــة بطريقــة غيــر نظاميــة ‪ -‬توليــد وإجهــاض النســاء ‪-‬‬\n      ‫شــهادة علــى إقــرار ‪ -‬إنــكار املدعــى عليهــا ‪ -‬ثبــوت إدانــة املدعــى عليهــا‬\n      ‫‪ -‬تعزيــر بالســجن ومصــادرة األجهــزة الطبيــة ‪ -‬صــرف النظــر عــن‬\n                                                ‫مصــادرة املبلــغ املالــي املضبــوط ‪.‬‬\n\n\n\n\n                             ‫‪ .1‬قاعدة (األصل أن ما بحوزة اإلنسان ملك له)‪.‬‬\n                                   ‫‪ .2‬ما أشار إليه القاضي يف تسبيب حكمه‪.‬‬\n\n\n\n\n      ‫الئحــة الدعــوى ضــد املدعــى عليهــا بتوجيــه االتهــام لهمــا مبزاولــة‬\n      ‫مهنــة توليــد وإجهــاض النســاء بطريقــة غيــر نظاميــة بغــرض الكســب‬\n      ‫املــادي وطلــب إثبــات مــا أســند إليهمــا وتعزيرهــا شــرع ًا ‪ ،‬حيــث وردت‬\n      ‫معلومــات عــن قيــام املدعــى عليهــا بعمليــات التوليــد واإلجهــاض بطريقــة‬\n      ‫غيــر نظاميــة ‪ -‬فتــم طلــب اإلذن مــن اجلهــات الرســمية لتفتيــش منزلهــا‬\n      ‫‪ -‬فتمــت املوافقــة علــى ذلــك‪ -‬فوجــد يف بيتهــا عــدد مــن األدوات الطبيــة‬\n      ‫املوصوفــة يف الدعــوى ‪ -‬كمــا اعترفــت أمــام الفرقــة القابضــة بأنهــا‬\n      ‫تقــوم بالتوليــد للفقــراء‪ ،‬وطلــب املدعــي العــام تعزيرهــا لقــاء ذلــك وطلــب‬\n      ‫مصــادرة األدوات واألجهــزة الطبيــة واملبلــغ املالــي‪ ،‬أنكــرت املدعــى‬\n\n‫‪339‬‬\n\f‫عليهــا مــا جــاء بدعــوى املدعــي العــام‪ ،‬بطلــب البينــة مــن املدعــي العــام‬\n‫علــى دعــواه احضــر الشــاهد والشــاهدتني الذيــن شــهدوا علــى إقــرار‬\n‫املــرأة بالتوليــد للفقــراء‪ ،‬الذيــن ال يحملــون إثبــات‪ ،‬حكمــت احملكمــة‬\n‫بتعزيــر املدعــى عليهــا بالســجن واجللــد لقــاء إدانتهــا بتوليــد النســاء‬\n‫بطريقــة غيــر نظاميــة ومبصــادرة األدوات الطبيــة املضبوطــة والتصــرف‬\n‫بهــا حســب األنظمــة والتعليمــات وصــرف النظــر عــن طلــب املدعــي العام‬\n‫مصــادرة املبلــغ احلكومــي لعــدم ثبــوت كونــه حصيلــة عمليــة توليــد ‪،‬‬\n‫قنعــت املدعــى عليهــا باحلكــم وقــرر املدعــي العــام اعتراضــه احلكــم‬\n         ‫بالئحــة االعتــراض‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة اجلزائيــة‬\n‫مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة مبكــة املكرمــة برقــم وتاريــخ ‪1434/12/25‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم وتاريــخ ‪1433/12/25‬ه ـ ففــي يــوم األحــد‬\n‫املوافــق ‪1434/01/18‬ه ـ افتتحــت اجللســة الســاعة ‪ 10 : 45‬وفيهــا‬\n‫حضــر املدعــي العــام مبوجــب خطــاب التكليــف مــن مرجعــه رقــم ‪1513‬‬\n‫يف ‪1431/11/11‬ه ـ وادعــى علــى احلاضــرة معــه باملجلــس الشــرعي ‪.....‬‬\n‫ا بدعــواه حيــث أنــه باالطــاع علــى األوراق‬  ‫اجلنســية باإلقامــة رقــم قائ ـ ً‬\n‫الــواردة بخطــاب مركــز شــرطة ‪ .....‬رقــم ‪ 370096‬يف ‪1433/12/5‬ه ـ‬\n‫املشــتملة علــى محضــر القبــض املعــد مــن قبــل البحــث املتضمــن أنــه‬\n‫وبنــاء علــى املعلومــات الــواردة لهــم بخصــوص قيــام املدعــى عليهــا‬\n‫بعمليــات التوليــد واإلجهــاض بطريقــة غيــر نظاميــة وبعــد التأكــد‬\n\n                                                                                     ‫‪340‬‬\n\f      ‫مت الرفــع ملقــام اإلمــارة لطلــب اإلذن يف تفتيــش منزلهــا حيــث جــاء‬\n      ‫التوجيــه باملوافقــة فبتاريــخ ‪1433/12/4‬ه ـ جــرى القبــض عليهــا بعــد‬\n      ‫أن أدخلــت املصــدر الســري ملنزلهــا الكائــن بشــارع ‪ ...‬للكشــف عليهــا‬\n      ‫وقــد وجــد بحوزتهــا جهــاز جــوال صينــي لونــه ذهبــي وبــه شــريحة رقــم‬\n      ‫(‪ ).......‬وجــوال آخــر مــن نــوع ( ‪ ) .....‬ال يعمــل وليــس بــه شــريحة ومبلــغ‬\n      ‫(‪ 520‬خمســمائة وعشــرون ريــال ) وجــواز ســفر يحمــل الرقــم (‪)....‬‬\n      ‫كمــا عثــر داخــل املنــزل املكــون مــن غرفــة واحــدة مبنافعهــا علــى مــا‬\n      ‫يلــي ‪ :‬عــدد(‪ )3‬جهــاز قيــاس ضغــط عــدد(‪ )2‬ســماعة أذن عــدد(‪)26‬‬\n      ‫حبــة خياطــة عــدد (‪ )2‬كرتــون تخطيــط حمــل عــدد (‪ )27‬براويــز إبــر‬\n      ‫عــدد(‪ )1‬مســحات طبيــة ‪ ،‬عــدد(‪ )1‬لــي مغــذي ‪ ،‬عــدد(‪ )6‬كرتــون إبــر‬\n      ‫ميزوســيت ‪ ،‬عــدد(‪ )2‬مقــص ‪ ،‬عــدد(‪ )11‬قــارورة قــزاز صغيــرة (بنــج )‬\n      ‫‪ ،‬عــدد(‪ )5‬كرتــون إبــر قلــم إنســولني ‪ ،‬عــدد(‪ )7‬كرتــون عــاج معــدة‬\n      ‫‪ ،‬عــدد(‪ )2‬كرتــون عــاج دوخــة ‪ ،‬عــدد(‪ )2‬كرتــون قطــرات للعــن ‪،‬‬\n      ‫عــدد(‪ )1‬شــنطة صغيــرة ســوداء بهــا أدوات عمليــات جراحيــة ‪ ،‬عــدد (‪)3‬‬\n      ‫كرتــون بوتاســيوم ‪ ،‬عــدد (‪ )1‬علبــة بداخلهــا (‪ )54‬كبســولة ‪ ،‬عــدد‬\n      ‫(‪ )31‬كرتــون (ســينتوكنون ) ‪ ،‬عــدد (‪ )1‬جهــاز حتليــل اللــون أحمــر‬\n      ‫بداخلــه (‪ )8‬قواريــر صغيــرة وبســماع أقــوال املدعــى عليهــا ‪/‬أفــادت‬\n      ‫بــأن املــرأة املصــدر حضــرت لهــا ملنزلهــا ومعهــا امــرأة حامــل وطلبــوا‬\n      ‫الكشــف عليهــا فرفضــت وأخبرتهــم أن عليهــم التوجــه للمستشــفى‬\n      ‫إلجراء الكشــف ‪ ،‬كما أفات أن األجهزة واألدوات الطبية املضبوطة‬\n      ‫معهــا باملنــزل قــد اشــترتها إلرســالها لشــقيقتها املمرضــة بالســودان‬\n      ‫ألنهــا طلبتهــا ذلــك وباســتجوابها‪ /‬افــادت بأنــه مت القبــض عليهــا داخــل‬\n      ‫منزلهــا الكائــن خلــف بشــارع ‪...‬واملكــون مــن غرفــة واحــدة تســكنها‬\n\n\n‫‪341‬‬\n\f‫وزوجهــا فقــط وأنهــا ال تعمــل وليــس لهــا مصــدر رزق ســوى زوجهــا ‪،‬‬\n‫وان مــا عثــر داخلــه علــى األدوات واألجهــزة الطبيــة املفنــدة بالتفصيــل‬\n‫مبحضــر القبــض التــي تســتخدم جميعهــا يف مجــال توليــد النســاء قــد‬\n‫اشــترتها لبعثهــا للســودان حيــث مقــر إقامتهــا وحيــث تــؤدي هــي مهنــة‬\n‫توليــد النســاء هنــاك مبستشــفى الــوالدة ‪ ،‬كمــا بــررت تناقضهــا مــع‬\n‫مــا أدلــت بــه بســماع أقوالهــا مــن أن األدوات الطبيــة املضبوطــة معهــا‬\n‫لشــقيقتها الطبيبــة بالســودان وأنهــا موكلــة بشــرائها وبعثهــا لهــا ‪،‬‬\n‫بأنهــا ذكــرت ذلــك بالفعــل ألن شــقيقتها ممرضــة نســاء هنــاك وقــد‬\n‫انتهــى التحقيــق إلــى توجيــه االتهــام للمدعــى عليهــا‪ /‬مبزاولــة مهنــة‬\n‫توليــد وإجهــاض النســاء بطريقــة غيــر نظاميــة بغــرض الكســب املــادي‬\n‫وذلــك لألدلــة والقرائــن التاليــة ‪ -1:‬شــهادة الشــهود املدونــة مبحضــر‬\n‫القبــض والتفتيــش املنــوه عنــه واملرفــق لفــه (‪ -2 )3-2‬مــا جــاء يف تناقــض‬\n‫أقوالهــا ‪ ،‬إضافــة إلقرارهــا بــأن املنــزل ال يســكنه غيرهــا وزوجهــا ‪،‬‬\n‫وأن املضبوطــات التــي داخــل املنــزل عائــدة لهــا وهــي مــن قامــت بشــرائها‬\n‫‪ ،‬قرائــن تــدل علــى صحــة مــا نســب إليهــا وحيــث إن مــا قامــت بــه املدعــى‬\n‫عليهــا فعــل محــرم ومعاقــب عليــه شــرع ًا لــذا اطلــب إثبــات مــا أســند‬\n‫إليهــا وتعزيرهــا شــرع ًا ‪ ،‬واحلكــم مبصــادرة األجهــزة واألدوات الطبيــة‬\n‫‪ ،‬واملبلــغ املالــي البالــغ (‪ 520‬ريــال) خمســمائة وعشــرون ريــا ًال ‪ .‬هــذه‬\n‫دعــواي وبســؤال املدعــى عليهــا أجابــت بقولهــا مــا ذكــره املدعــي العــام‬\n‫مــن ضبــط جميــع املضبوطــات الطبيــة املذكــورة يف منزلــي فصحيــح‬\n‫ومــا ذكــره مــن قيامــي بالتوليــد واإلجهــاض فغيــر صحيــح وأنــا ال‬\n‫أســتعمل هــذه األدوات والواقــع أننــي اشــتريت هــذه األدوات الطبيــة‬\n‫ألرســلها ألختــي املقيمــة يف الســودان والتــي تعمــل قابلــة لتوليــد النســاء‬\n\n\n                                                                                     ‫‪342‬‬\n\f      ‫حيــث أوصتنــي بشــراء أفضــل األدوات وإرســالها لهــا ولكــن قبــض‬\n      ‫علــي قبــل ســفري بهــا هــذه إجابتــي وقــال املدعــي العــام الصحيــح مــا‬\n      ‫ذكــرت وبطلــب البينــة قــال ســأفيدكم يف اجللســة القادمــة لــذا رفعــت‬\n      ‫اجللســة ففــي يــوم الســبت املوافــق ‪1434/2/2‬ه ـ افتتحــت اجللســة وحضر‬\n      ‫فيهــا املدعــي العــام واملدعــى عليهــا ولــم يحضــر املدعــي العــام بينتــه لــذا‬\n      ‫رفعــت اجللســة إلحضارهــا ويف يــوم الثالثــاء املوافــق ‪1434/4/12‬ه ـ‬\n      ‫افتتحــت اجللســة وحضــر فيهــا املدعــي العــام واملدعــى عليهــا وحضــر‬\n      ‫للشــهادة وادائهــا ‪ ......‬بســجل مدنــي رقــم (‪ )....‬ســعودية اجلنســية بســجل‬\n      ‫مدنــي رقــم وشــهدا بقولهمــا أننــا شــاركنا يف مداهمــة غرفــة املدعــى‬\n      ‫عليهــا ووجدنــا األدوات الطبيــة املذكــورة ووجدنــا بعضهــا مســتعمال‬\n      ‫وبعضهــا يف الثالجــة وقــد اعترفــت املدعــى عليهــا مبزاولــة مهنــة التوليــد‬\n      ‫للفقــراء والذيــن ال يحملــون اثبــات هويــة وأنكــرت االجهــاض هــذه‬\n      ‫شــهادتنا كمــا حضــرت للشــهادة ‪ ....‬ســعودية اجلنســية بســجل مدنــي‬\n      ‫رقــم وشــهدت بقولهــا انــه جــرى تكليفــي مبواجهــة املدعــى عليهــا بعــد‬\n      ‫اإلخباريــة عنهــا فذهبــت إليهــا بغرفتهــا وطلبــت منهــا إجــراء اإلجهــاض‬\n      ‫فأفادتنــي بانهــا ال تقــوم باإلجهــاض وأنهــا تقــوم بالكشــف والتوليــد‬\n      ‫فقــط والعمــل كدايــة وعندمــا ذكــرت لــي ذلــك ورأيــت املعــدات الطبيــة‬\n      ‫اعطيــت اشــارة القبــض هــذه شــهادتي وقالــت املدعــى عليهــا مــا ذكــره‬\n      ‫الشــهود غيــر صحيــح وال اعرفهــم قبــل القبــض علــي ثــم جــرى تعديــل‬\n      ‫الشــهود الثالثــة مــن قبــل ‪ .......‬و‪ ........‬وقالــت املدعــى عليهــا ان املبلــغ‬\n      ‫املضبــوط معــي ملكــي وهــو مجمــوع مــن املصاريــف التــي يعطينــي‬\n      ‫إياهــا زوجــي وقــال املدعــي العــام ليــس لــدي بينــة علــى أن املبلــغ حصيلــة‬\n      ‫عمليــات التوليــد فرفعــت اجللســة للتأمــل ويف يــوم االثنــن املوافــق ‪/ 25‬‬\n\n\n‫‪343‬‬\n\f‫‪1434/2‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي العــام واملدعــى عليهــا‬\n‫وقــد جــرى تأمــل القضيــة فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n‫وإلــى إقــرار املدعــى عليهــا بحيــازة املضبوطــات الطبيــة املذكــورة يف‬\n‫منزلهــا وإنكارهــا اســتعمالها وإنكارهــا التوليــد واإلجهــاض وال بينــة‬\n‫علــى اإلجهــاض وبنــاء علــى شــهادة البينــة املعدلــة شــرعا حيــث شــهد‬\n‫الرجــل واملرأتــان علــى إقــرار املدعــى عليهــا بالقيــام بالتوليــد كمــا‬\n‫شــهدوا بــأن بعــض األدوات مســتعمل وبعضهــا يف الثالجــة لــذا فقــد‬\n‫ثبــت لــدي إدانــة املدعــى عليهــا مبزاولــة مهنــة توليــد النســاء بطريقــة‬\n‫غيــر نظاميــة وحكمــت بتعزيرهــا علــى ذلــك بالســجن مــدة أربعــة اشــهر‬\n‫ومصــادرة األدوات الطبيــة املضبوطــة والتصــرف بهــا حســب األنظمــة‬\n‫والتعليمــات ولــم يثبــت لــدي إدانتهــا بالقيــام بعمليــات اإلجهــاض كمــا‬\n‫صرفــت النظــر عــن طلــب املدعــي العــام مصــادرة املبلــغ املالــي املضبــوط‬\n‫بحوزتهــا وقــدره خمســمائة وعشــرون ريــاال لعــدم ثبــوت كونــه حصيلــة‬\n‫عمليــات توليــد وألن األصــل أن مــا بحــوزة اإلنســان ملــك لــه وبعــرض‬\n‫احلكــم علــى املدعــى عليهــا قنعــت بــه وقــد عــارض املدعــي العــام وطلــب‬\n                      ‫االســتئناف بالئحــة فأجيــب لطلبــه وبــاهلل التوفيــق ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ثــم عــادة املعاملــة مــن محكمــة االســتئناف‬\n‫وبرفقهــا القــرار رقــم يف ‪1434/4/8‬ه ـ املتضمــن املوافقــة والتصديــق‬\n‫علــى احلكــم وبــاهلل التوفيــق ‪.‬قاضــي اســتئناف‪ /‬ختــم‪ .‬توقيــع ‪.‬قاضــي‬\n‫اســتئناف‪ /‬ختــم ‪.‬توقيــع ‪.‬رئيــس الدائــرة‪ /‬ختــم ‪.‬توقيــع لــذا جــرى إحلاقــه‬\n                                               ‫واثباتــه حــرر يف ‪1434/5/5‬هــ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد‪-:‬‬\n‫فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة األولــى يف محكمــة‬\n\n\n                                                                                   ‫‪344‬‬\n\f      ‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبكــة املكرمــة برقــم‬\n      ‫وتاريــخ ‪1434/3/28‬هـ ـ املرفــق بهــا القــرار الشــرعي رقــم وتاريــخ‬\n      ‫‪1434/2/25‬هـ ـ الصــادر مــن فضيلــة الشــيخ‪ ...../‬القاضــي يف احملكمة‬\n      ‫اجلزائيــة مبكــة املكرمــة ‪ ،‬املتضمــن دعــوى املدعــي العــام ضــد ‪....../‬‬\n      ‫نيجيريــة اجلنســية املتهمــة بقضيــة ممارســة مهنــة التوليــد واإلجهــاض‬\n      ‫بطريقــة غيــر نظاميــة احملكــوم فيــه مبــا دون باطنــه‪ .‬وبدراســة احلكــم‬\n      ‫وصــورة ضبطــه والالئحــة االعتراضيــة قررنــا املوافقــة علــى احلكــم‪،‬‬\n      ‫واهلل املوفــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪345‬‬\n\f346\n\f                      ‫كشاف املوضوعات‬\n\n‫الصفحة‬                     ‫املوضوع‬                      ‫التصنيف‬   ‫م‬\n\n\n         ‫شخصا‬\n          ‫ً‬   ‫دعوى عامة وخاصة ضد مدعى عليه ضرب‬\n  ‫‪5‬‬                                                      ‫اعتداء‬   ‫‪1‬‬\n                ‫بعصا على رأسه أدت لوفاته‬\n\n\n           ‫دعوى عامة وخاصة لرمي املدعى عليه فنجانا‬\n  ‫‪16‬‬       ‫والتسبب يف إصابة املدعي باحلق اخلاص بجرح‬      ‫اعتداء‬   ‫‪2‬‬\n                 ‫بالرأس احتاج عشرة أيام للعالج‬\n\n\n         ‫دعوى عامة ضد زوج ضرب زوجته‪ ،‬وتنازلت الزوجة‬\n  ‫‪25‬‬                                                     ‫اعتداء‬   ‫‪3‬‬\n                         ‫عن حقها اخلاص‬\n\n\n          ‫دعوى عامة ضد مدعى عليه بالشروع يف قتل زوج‬\n  ‫‪34‬‬                                                     ‫اعتداء‬   ‫‪4‬‬\n            ‫أخته وذلك بضربه بفأس يف أطرافه األربعة‬\n\n\n          ‫دعوى عامة ضد مدعى عليه لقيامه بدخول منزل‬\n  ‫‪41‬‬                                                     ‫اعتداء‬   ‫‪5‬‬\n         ‫عنو ًة وطعن صاحبه بسكني مما تسبب يف إصابته‬\n\n\n            ‫دعوى عامة ضد مدعى عليه بطعن شخص‪،‬‬\n  ‫‪45‬‬                                                     ‫اعتداء‬   ‫‪6‬‬\n             ‫واملدعى عليه يدفع بأنه دافع عن نفسه‬\n\n\n          ‫دعوى عامة ضد مدعى عليه بقيامه بسكب زيت‬\n  ‫‪52‬‬                                                     ‫اعتداء‬   ‫‪7‬‬\n           ‫ساخن على أحد السجناء مما تسبب يف إصابته‬\n\n\n          ‫مطالبة مدعية (مقيمة عند أهلها) بتعزير زوجها‬\n  ‫‪57‬‬                                                     ‫اعتداء‬   ‫‪8‬‬\n            ‫لضربه لها وسبها وشتمها وتعريضه بقذفها‬\n\f‫الصفحة‬                      ‫املوضوع‬                         ‫التصنيف‬   ‫م‬\n\n\n          ‫دعوى عامة وخاصة ضد مدعى عليها التهامها‬\n  ‫‪65‬‬                                                         ‫اعتداء‬   ‫‪9‬‬\n         ‫بإساءة سمعة امرأة والتشهير بها يف مواقع اإلنترنت‬\n\n\n            ‫مطالبة مدعية بتعزير زوجها إلسائته عشرتها‬\n  ‫‪75‬‬                                                         ‫اعتداء‬   ‫‪10‬‬\n                    ‫وضربها والشروع يف قتلها‬\n\n\n         ‫دعوى عامة ضد مدعى عليهما أحدهما لم يحضر‬\n  ‫‪81‬‬     ‫باجتماعهما على شرب مسكر إثر القبض عليهما‬            ‫اعتداء‬   ‫‪11‬‬\n                         ‫نتيجة مضاربة‬\n\n\n            ‫دعوى عامة وخاصة ضد مدعى عليه العتدائه‬\n            ‫بسيارته على مواطنني يسيران على أقدامهما‬\n  ‫‪89‬‬                                                         ‫اعتداء‬   ‫‪12‬‬\n           ‫مبطاردتهما بقصد إصابتهما‪ ،‬وإصابة أحدهما‬\n                         ‫والهروب من املوقع‬\n\n\n          ‫عمدا‬\n           ‫دعوى عامة بتعزير مدعى عليه لضربه آخر ً‬\n  ‫‪98‬‬                                                         ‫اعتداء‬   ‫‪13‬‬\n                     ‫نتج عنه إصابته‬\n\n\n         ‫دعوى عامة وخاصة ضد مدعى عليها بضرب زوجها‬\n ‫‪103‬‬                                                         ‫اعتداء‬   ‫‪14‬‬\n                   ‫بكأس زجاج على رأسه‬\n\n\n           ‫مطالبة مدعية تأديب مدعى عليه كان زوجا لها‬\n         ‫اتهمها أثناء نظر قضية حضانة أوالدهما حكم فيها‬\n ‫‪109‬‬       ‫بحضانتها‪ ،‬بأنها مصابة باضطرابات عقلية وأنها‬       ‫اعتداء‬   ‫‪15‬‬\n                           ‫حاولت االنتحار‬\n\f‫الصفحة‬                      ‫املوضوع‬                       ‫التصنيف‬   ‫م‬\n\n\n         ‫دعوى عامة وخاصة ضد مدعى عليه إلتالفه إطارات‬\n ‫‪115‬‬     ‫سيارة املدعي باحلق اخلاص وقطع التيار الكهربائي‬    ‫اعتداء‬   ‫‪16‬‬\n                 ‫عن منزله وانتحال شخصية الغير‬\n\n\n          ‫دعوى عامة بتعزير مدعى عليهما العتدائهما على‬\n ‫‪126‬‬      ‫بعض والتسبب يف اإلصابة التي حلقت بكل منهما‬       ‫اعتداء‬   ‫‪17‬‬\n                    ‫على إثر سوء تفاهم بينهما‬\n\n\n          ‫دعوى عامة بتعزير مدعى عليهم سبعة العتدائهم‬\n ‫‪131‬‬      ‫على بعض بأدوات حادة والتسبب باإلصابات التي‬       ‫اعتداء‬   ‫‪18‬‬\n                ‫حلقت بهم على إثر سوء تفاهم بينهم‬\n\n\n           ‫دعوى عامة وخاصة ضد مدعى عليه بأذيته جاره‬\n ‫‪145‬‬      ‫وعمه من خالل تسوره على سترة منزلهم واطالعه‬       ‫اعتداء‬   ‫‪19‬‬\n                          ‫على عورات منزله‬\n\n\n           ‫دعوى عامة وخاصة ضد مدعى عليهم عشرة‬\n ‫‪156‬‬       ‫بالتحريض على اقتحام منزل والتجمهر وقذف‬          ‫اعتداء‬   ‫‪20‬‬\n              ‫حجارة عليه والقفز ومحاولة اقتحامه‬\n\n\n          ‫دعوى عامة ضد مدعى عليه لقيامه باالعتداء على‬\n ‫‪177‬‬                                                       ‫اعتداء‬   ‫‪21‬‬\n          ‫زوجته بالضرب وخنقها بيده والتسبب يف إصابتها‬\n\n\n          ‫دعوى عامة ضد مقيم العتدائه على أحد الوافدين‬\n ‫‪182‬‬     ‫وسرقة ما طور كهربائي والتستر على شركائه يف‬        ‫اعتداء‬   ‫‪22‬‬\n                              ‫اجلرمية‬\n\f‫الصفحة‬                      ‫املوضوع‬                      ‫التصنيف‬   ‫م‬\n\n\n          ‫دعوى عامة ضد مدعى عليه العتدائه على رجال‬\n ‫‪188‬‬        ‫األمن بإحلاق الضرر مبركبتيهم بعد محاولة‬       ‫اعتداء‬   ‫‪23‬‬\n                            ‫استيقافه‬\n\n\n         ‫دعوى عامة مدعى عليه العتدائه على زوجته التي‬\n         ‫تنازلت عن حقها بالضرب بيده وجتاوز حد التأديب‬\n ‫‪193‬‬                                                      ‫اعتداء‬   ‫‪24‬‬\n          ‫الشرعي والتسبب يف جرح وفقد جزء من إحدى‬\n                            ‫أسنانها‬\n\n\n         ‫دعوى عامة ضد مدعى عليه إلشهاره السالح على‬\n           ‫مواطن‪ ،‬بقصد التهديد ومقاومة رجل األمن‪،‬‬\n ‫‪199‬‬                                                      ‫اعتداء‬   ‫‪25‬‬\n          ‫واالعتداء على مركبته بالصدم والهروب منه‪،‬‬\n          ‫وصدم سيارة مواطن عمدا وانتهاك حرمة منزل‬\n\n\n         ‫دعوى عامة ضد مدعى عليه لطعنه شقيقه املجني‬\n ‫‪205‬‬                                                      ‫اعتداء‬   ‫‪26‬‬\n                         ‫عليه وإصابته‬\n\n\n            ‫دعوى عامة ضد مدعى عليه الرتكابه جرمية‬\n ‫‪211‬‬      ‫االجتار بالبشر بتعذيب طفله القاصر ‪ ،‬و جتاوزه‬    ‫اعتداء‬   ‫‪27‬‬\n             ‫حد التأديب الشرعي‪ ،‬والتسبب يف إصابته‬\n\n\n         ‫دعوى عامة ضد مدعى عليه لطعنه شخصا تنازل‬\n ‫‪222‬‬     ‫عن حقه اخلاص على يده اليمنى طعنتني بسكني‬         ‫اعتداء‬   ‫‪28‬‬\n                         ‫وإصابته‬\n\n\n         ‫دعوى عامة ضد مدعى عليه (مريض نفسي) لتعديه‬\n ‫‪227‬‬                                                      ‫اعتداء‬   ‫‪29‬‬\n          ‫بالضرب على موظف حكومي أثناء تأديته عمله‬\n\f‫الصفحة‬                       ‫املوضوع‬                        ‫التصنيف‬   ‫م‬\n\n\n         ‫دعوى عامة ضد مدعى عليه إلشهاره السالح على‬\n ‫‪232‬‬      ‫زوجته التي تنازلت عن حقها اخلاص وتهديدها‬           ‫اعتداء‬   ‫‪30‬‬\n                 ‫وضربها وإحداث إصابات بها‬\n\n\n         ‫وتعد‬\n         ‫ٍّ‬   ‫دعوى عامة ضد مدعى عليهم للخلوة احملرمة‬\n ‫‪236‬‬     ‫لفظي على جهة الضبط وتهديدهم بالقتل ومحاولة‬          ‫اعتداء‬   ‫‪31‬‬\n                              ‫تهريب‬\n\n\n          ‫عمدا‬\n            ‫دعوى عامة ضد مدعى عليه لصدمه سيارة ً‬\n ‫‪245‬‬       ‫وإحداث تلفيات بها والتلفظ على صاحبها نتيجة‬        ‫اعتداء‬   ‫‪32‬‬\n                    ‫سوء تفاهم بينه وبني صاحبها‬\n\n\n          ‫دعوى عامة ضد مدعى عليه العتدائه عمد ًا على‬\n ‫‪252‬‬      ‫شخص تنازل عن حقه اخلاص بضربه على رأسه‬              ‫اعتداء‬   ‫‪33‬‬\n                  ‫بأداة خشبية و التسبب يف إصابته‬\n\n\n         ‫دعوى عامة ضد مدعى عليها لضربها امرأة بحذاء‬\n ‫‪257‬‬                                                         ‫اعتداء‬   ‫‪34‬‬\n             ‫على عينها اليمنى مما أدى إلى إصابتها‬\n\n\n          ‫دعوى عامة ضد مدعى عليه لتهديده رجل أمن‬\n ‫‪263‬‬     ‫والتعدي عليه بألفاظ غير الئقة و اعتداء بالضرب‬       ‫اعتداء‬   ‫‪35‬‬\n                ‫على أحد املوقوفني أثناء إيقافه‬\n\n\n         ‫دعوى عامة ضد مدعى عليه لشروعه يف قتل زوجته‬\n ‫‪269‬‬     ‫التي تنازلت عن حقها اخلاص واالعتداء بضربها مما‬      ‫اعتداء‬   ‫‪36‬‬\n           ‫أدى إلصابتها وطلب إيقاع العقوبة التعزيرية عليه‬\n\n\n           ‫دعوى عامة ضد مدعى عليه إلطالقه النار على‬\n ‫‪276‬‬                                                         ‫اعتداء‬   ‫‪37‬‬\n             ‫سيارة شخص آخر مما تسبب يف إحراقها‬\n\f‫الصفحة‬                      ‫املوضوع‬                       ‫التصنيف‬      ‫م‬\n\n\n         ‫دعوى عامة وخاصة ضد مدعى عليه لوضعه حجارة‬\n ‫‪280‬‬       ‫وبهائم على الطريق عمد ًا مما تسبب يف حدوث‬       ‫اعتداء‬      ‫‪38‬‬\n                 ‫تلفيات لسيارتني وإصابة امرأة‬\n\n\n           ‫دعوى عامة ضد مدعى عليه لقيامه بسب رجال‬          ‫مقاومة‬\n ‫‪291‬‬                                                                   ‫‪39‬‬\n              ‫األمن وقذفهم واحلكم عليه بحد القذف‬           ‫سلطات‬\n\n\n         ‫دعوى عامة ضد مدعى عليه لهروبه من رجال األمن‬\n                                                           ‫مقاومة‬\n ‫‪294‬‬     ‫وإشهاره السالح عليهم والتستر على مرافقه الهارب‬                ‫‪40‬‬\n                                                           ‫سلطات‬\n                         ‫من رجال األمن‬\n\n\n           ‫دعوى عامة ضد مدعى عليه (حدث) لهروبه من‬          ‫مقاومة‬\n ‫‪301‬‬                                                                   ‫‪41‬‬\n                  ‫نقطة تفتيش وصدم دورية أمنية‬              ‫سلطات‬\n\n\n          ‫دعوى عامة ضد مدعى عليه لصدمه دورية أمنية‬\n                                                           ‫مقاومة‬\n ‫‪307‬‬     ‫مما تسبب يف إصابة قائدها املتنازل عن حقه اخلاص‬                ‫‪42‬‬\n                                                           ‫سلطات‬\n              ‫وإتالف ممتلكات عامة وهربه من املوقع‬\n\n\n           ‫دعوى عامة ضد مدعى عليهم أربعة ملجاهرتهم‬        ‫اإلفطار يف‬\n ‫‪313‬‬                                                                   ‫‪43‬‬\n                      ‫بالفطر يف نهار رمضان‬                 ‫رمضان‬\n\n\n         ‫دعوى عامة ضد مدعى عليه لفطره يف نهار رمضان‬       ‫اإلفطار يف‬\n ‫‪321‬‬                                                                   ‫‪44‬‬\n                    ‫عامدا من غير عذر‬\n                                  ‫ً‬  ‫عاملًا‬                ‫رمضان‬\n\n\n            ‫دعوى عامة ضد مدعى عليه إلفطاره يف نهار‬        ‫اإلفطار يف‬\n ‫‪324‬‬                                                                   ‫‪45‬‬\n         ‫رمضان وهروبه من الدورية األمنية وصدم سيارتها‬      ‫رمضان‬\n\f‫الصفحة‬                      ‫املوضوع‬                      ‫التصنيف‬   ‫م‬\n\n\n                                                          ‫انتحال‬\n ‫‪333‬‬     ‫دعوى عامة ضد مدعى عليه النتحاله شخصية محام‬                ‫‪46‬‬\n                                                         ‫شخصية‬\n\n\n          ‫دعوى عامة ضد مدعى عليها ملزاولتها مهنة توليد‬\n                                                          ‫انتحال‬\n ‫‪339‬‬        ‫وإجهاض النساء بطريقة غير نظامية بغرض‬                   ‫‪47‬‬\n                                                         ‫شخصية‬\n                           ‫الكسب املادي‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":339,"source_page_end":353,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"e6ed8a1a7c3447178b4298c4cfa61fea579b82b4923d9fb1a6696325b2340837","normalized_text_hash":"f028bef243c79dde0a4252ff9f38ed42e93e6386f79ca584c2329484870bd7c8","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p339-3446763"},{"id":"284061b0-81e9-525e-a41f-aba35606d971","document_type":"judgment","category":"judicial","subcategory":"general","title":"تزوير -تستر على واقعة تزوير بتقدمي معلومات غير صحيحة جلهة حكومية -ظروف مخففة للتعزير -تعزير بالتوبيخ وأخذ التعهد.","document_number":"3423238","case_number":"33135559","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بينبع","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/26","year":"1434","subject":"تزوير -تستر على واقعة تزوير بتقدمي معلومات غير صحيحة جلهة حكومية -ظروف مخففة للتعزير -تعزير بالتوبيخ وأخذ التعهد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪ 3423238:‬تاريخه‪1434/1/26 :‬هـ‬\n                       ‫رقم الدعوى‪33135559 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 3422619‬تاريخه‪1434/5/22:‬هـ‬\n\n\n    ‫تزويــر‪ -‬تســتر علــى واقعــة تزويــر بتقــدمي معلومــاتٍ غيــر صحيحــة جلهة‬\n     ‫حكوميــة ‪ -‬ظــروف مخففــة للتعزيــر ‪ -‬تعزيــر بالتوبيــخ وأخــذ التعهد‪.‬‬\n\n\n\n\n            ‫‪ -‬قوله صلى اهلل عليه وسلم ((أقيلوا ذوي الهيئات عثراتهم ))‪.‬‬\n\n\n\n\n    ‫مت توجيــه االتهــام للمدعــى عليــه بالتســتر علــى واقعــة تزويــر تتمثــل‬\n    ‫بالتقــدم مبعلومــات غيــر صحيحــة مبســاعدة شــخص آخــر حيــث أرفــق‬\n    ‫تقريــر ًا طبي ـ ًا غيــر صحيــح لزوجتــه لطلــب املوافقــة علــى الــزواج مــن‬\n    ‫أجنبيــة‪ -‬بالبحــث عــن ســوابقه تبــن عــدم وجــود ســوابق عليــه‪ -‬طلــب‬\n    ‫املدعــي العــام احلكــم علــى املدعــى عليــه بعقوبة تعزيريــة‪ -‬بعرض دعوى‬\n    ‫املدعــي العــام علــى املدعــى عليــه صــادق عليهــا ودفــع أنــه كان محتاجــا‬\n    ‫املعقــب ولــم‬\n             ‫إلــى الــزواج بزوجــة ثالثــة وأن ورقــة التقريــر الطبــي وضعهــا ِّ‬\n    ‫يعلــم هــو عــن مضمونهــا ولــو علــم أنهــا مــزورة مــا وافــق عليهــا‪ ،‬وقــرر‬\n    ‫أنــه صاحــب أســرة حيــث يعــول اثنتــي عشــر نفس ـ ًا كمــا أنــه يعمــل‬\n    ‫معلم ـاً‪ -‬جــرى االطــاع علــى ســجل األســرة اخلــاص بــه فوجــد يتضمــن‬\n    ‫أن لــه عشــرة مــن األوالد مــا بــن أبنــاء وبنــات‪ -‬نظــر ًا لكــون املدعــى‬\n    ‫عليــه ذو عيــال وخشــية علــى ضيــاع مســتقبل مــن يعولهــم مت احلكــم‬\n‫‪5‬‬\n\f‫بتعزيــر املدعــى عليــه بتوبيخــه يف مجلــس احلكــم وأخــذ التعهــد الشــديد‬\n‫والــازم عليــه بعــدم العــودة إلــى مثــل مــا بــدر منــه ‪ -‬بعــرض احلكــم علــى‬\n‫املدعــى عليــه قــرر قناعتــه بــه وبعرضــه علــى املدعــي العــام قــرر عــدم‬\n‫القناعــة وطلــب االســتئناف مكتفيـ ًا بالئحــة الدعــوى العامــة وبعــد رفــع‬\n                      ‫احلكــم حملكمــة االســتئناف متــت املصادقــة عليهــا‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .........‬القــاض ـ ــي يف احملكمــة العامــة‬\n‫بينبــع وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بينبع‪/‬املســاعد برقــم ‪ 33135559‬وتاريــخ ‪1433/02/22‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 33354860‬وتاريــخ ‪1433/2/22‬ه ـ ففــي يــوم‬\n             ‫االثنــن املوافق‪1433/11/22‬ه ـ افتتحــت اجلـ ــلسـ ــة السـ ــاعة‬\n‫‪ 10 : 30‬وفيهــا حضــر املدعــي العــام بينبــع ‪ ......‬واملكلــف مــن قبــل‬\n‫ال بصفتي مدعيا‬      ‫م ــرجعه برقم ‪......‬وتاريخ ‪1426/12/22‬هـ وادعى قائ ً‬\n‫عامــا بدائــرة االدعــاء العــام بينبــع أدعــي علــى ‪ 39 ......‬عامــا ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪......‬لــم يوقــف يقيــم مبحافظــة‬\n‫ينبــع وحيــث إنــه بتاريــخ ‪1429/3/22‬ه ـ ورد إلــى الدائــرة خطــاب ســعادة‬\n‫محافــظ ينبــع رقــم ‪......‬املتضمــن التحقيــق مــع املدعــى عليــه الرتكابــه‬\n‫مخالفــة تتمثــل بالتقــدم مبعلومــات غيــر صحيحــة مبســاعدة آخــر حيــث‬\n‫أرفــق تقريــر ًا طبي ـ ًا غيــر صحيــح لزوجتــه لطلــب املوافقــة علــى الــزواج‬\n‫مــن أجنبيــة وباســتجوابه أنــه قــام بتوكيــل شــخص يدعــى ‪ ......‬ملتابعــة‬\n‫املعاملــة يف وزارة الداخليــة وأنــه شــاهد مــن ضمــن األوراق التــي كان‬\n‫ينــوي الوكيــل تقدميهــا إلــى الــوزارة تقريــر ًا طبي ـ ًا لزوجتــه صــادر ًا مــن‬\n\n                                                                                        ‫‪6‬‬\n\f    ‫مستشــفى لــم يراجعــه ومتضمن ـ ًا ملعلومــات غيــر صحيحــة وقــد انتهــى‬\n    ‫التحقيــق إلــى توجيــه االتهــام إليــه بالتســتر علــى واقعــة تزويــر وذلــك ملــا‬\n    ‫جــاء يف أقوالــه املدونــة ص ‪ 1‬ـ ‪ 4‬مــن دفتــر التحقيــق املرفــق لفــة ‪22‬‬\n    ‫وببحــث حالتــه اجلنائيــة تبــن عــدم وجــود ســوابق مســجلة عليــه وحيث إن‬\n    ‫مــا أقــدم عليــه املتهــم وهــو بكامــل أهليتــه املعتبــرة شــرع ًا فعــل محــرم‬\n    ‫ومعاقــب عليــه شــرع ًا أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة‬\n    ‫تعزيريــة هكــذا ادعــى املدعــي العــام وحيــث إنــه مت تكليــف املدعــى‬\n    ‫عليــه باحلضــور هــذا اليــوم وذلــك بخطابنــا املوجــه ملديــر أمــن احملكمــة‬\n    ‫برقــم ‪ 331790492‬وتاريــخ ‪1433/10/14‬ه ـ ولــم يحضــر لــذا وبنــاء‬\n    ‫علــى املــادة احلاديــة واألربعــن بعــد املائــة مــن نظــام اإلجــراءات اجلزائيــة‬\n    ‫ونصهــا اآلتــي إذا لــم يحضــر املتهــم املكلــف باحلضــور حســب النظــام يف‬\n    ‫اليــوم املعــن يف ورقــة التكليــف باحلضــور ولــم يرســل وكيــا عنــه يف‬\n    ‫األحــوال التــي يســوغ فيهــا التوكيــل فيســمع القاضــي دعــوى املدعــي‬\n    ‫وبيناتــه ويرصدهــا يف ضبــط القضيــة وال يحكــم إال بعــد حضــور املتهــم‬\n    ‫لــذا فقــد جــرى رفــع اجللســة ويف جلســة أخــرى لــدي أنــا ‪ ......‬القاضــي‬\n    ‫باحملكمــة العامــة بينبــع والقائــم بعمــل الشــيخ ‪ ......‬حضــر املدعــي العــام‬\n    ‫واملدعــى عليه‪......‬ثــم جــرى عــرض الئحــة املدعــي العــام علــى املدعــى‬\n    ‫ا مــا جــاء يف الئحــة‬  ‫عليــه احلاضــر وبســؤاله عمــا جــاء فيهــا أجــاب قائ ـ ً‬\n    ‫املدعــي العــام صحيــح وحقيقــة األمــر أنــي كنــت محتاجـ ًا إلــى الــزواج‬\n    ‫بزوجــة ثالثــة ولــم أكــن مســتطيع ًا أن أتــزوج ســعودية وذلــك ألن لــدي‬\n    ‫ظروفـ ًا خاصــة ال تســمح لــي بذلــك فقمــت بالتقــدمي علــى وزارة الداخليــة‬\n    ‫بطلــب اإلذن لــي بالــزواج مــن أجنبيــة فذهبــت إلــى الريــاض وقابلــت‬\n    ‫شــخص ًا يدعــى ‪ ......‬وأخبرنــي بأنــه معقــب ويســتطيع أن يتابــع معاملتــي‬\n\n\n‫‪7‬‬\n\f‫بــوزارة الداخليــة وينهــي إجراءاتهــا فاقتنعــت بــه وبكالمــه ثــم أعطيتــه‬\n‫معاملتــي ليتابعهــا بالــوزارة ورجعــت إلــى محافظــة ينبــع حيــث أقيــم‬\n‫فاتصــل بــي بعــد عــدة أيــام وأخبرنــي أنــه البــد لقبــول املعاملــة مــن أن‬\n‫تكــون زوجتــي تعانــي مــن مــرض أو متــر بظــروف صحيــة فأخبرتــه أن‬\n‫ا تعانــي مــن بعــض األمــراض فقــال لــي إنــه وضــع ورقــة يف‬      ‫زوجتــي فع ـ ً‬\n‫معاملتــي تفيــد بذلــك ولــم أكــن أعلــم مبحتواهــا ولــو علمــت أن القضيــة‬\n‫قضيــة تزويــر ملــا وافقــت علــى فعلــه وأنــا رجــل ذو عيــال حيــث أننــي أعــول‬\n‫اثنــي عشــر نفسـ ًا وأنــا معلــم ودخلــي محــدود وأخشــى أن أفقــد وظيفتــي‬\n‫وتضيــع أســرتي الكبيــرة هكــذا أجــاب ثــم قــدم أصــل ســجل األســرة‬\n‫اخلــاص بــه وباالطــاع عليــه وجــد أن لديــه عشــرة مــن األوالد مــا بــن‬\n‫أبنــاء وبنــات ثــم جــرى الرجــوع للمعاملــة ووجــد بهــا وعلــى ملــف التحقيــق‬\n‫لفــة (‪ )22‬ص(‪ )4-3-2-1‬محضــر اســتجواب للمدعــى عليــه احلاضــر‬\n‫املــؤرخ يف ‪1429/4/29‬ه ـ وليــس فيــه ســوى مــا ذكــره املدعــى عليــه يف‬\n‫ا ال بينــة‬\n          ‫جوابــه وبســؤال املدعــي العــام هــل لديــه زيــادة بينــة أجــاب قائـ ً‬\n‫لــدي ســوى مــا ذكرتــه هكــذا ‪ .‬أجــاب هــذا وألجــل مــا جــاء يف الدعــوى‬\n‫واإلجابــة وملصادقــة املدعــى عليــه علــى جــاء يف دعــوى املدعــي العــام‬\n‫وملــا ظهــر لــي مــن حــال املدعــى عليــه مــن أنــه مــن ذوي الهيئــات ولقولــه‬\n‫صلــى اهلل عليــه وســلم ((أقيلــوا ذوي الهيئــات عثراتهــم)) وألن املدعــى‬\n‫عليــه ذو عيــال وخشــية علــى ضيــاع مســتقبل مــن يعولهــم لــذا فقــد قــررت‬\n‫تعزيــر املدعــى عليــه احلاضــر بتوبيخــه يف مجلــس احلكــم وأخــذ التعهــد‬\n‫الشــديد والــازم عليــه بعــدم العــودة إلــى مثــل مــا بــدر منــه هــذا مــا‬\n‫ظهــر لــي وبــه حكمــت وبعــرض احلكــم علــى املدعــى عليــه قــرر قناعتــه‬\n‫بــه وبعرضــه علــى املدعــي العــام قــرر عــدم القناعــة وطلــب االســتئناف‬\n\n\n                                                                                       ‫‪8‬‬\n\f    ‫مكتفي ـ ًا بالئحــة الدعــوى العامــة وأمــرت برفــع املعاملــة لالســتئناف‬\n    ‫حســب املتبــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                     ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/1/19‬ه ـ ‪.‬‬\n    ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n    ‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة اخلامســة مبحكمــة االســتئناف‬\n    ‫يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n    ‫رئيــس احملكمــة العامــة بينبــع املســاعد برقــم ‪32969456‬وتاريــخ‬\n    ‫‪1434/5/6‬ه ـ املرفــق بها القرار رقم ‪ 3423238‬وتاريخ‪1434/1/26‬هـ‬\n    ‫الصــادر مــن فضيلــة الشــيخ‪....../‬القاضي باحملكمــة العامــة بينبــع‬\n    ‫القائــم بعمــل فضيلــة الشــيخ ‪......‬املتضمــن دعــوى املدعــي العــام ضــد ‪/‬‬\n    ‫‪ ......‬فســعودي اجلنســية املتهــم يف التســتر علــى واقعــة تزويــر ‪ ،‬احملكــوم‬\n    ‫فيــه مبــا دون بباطنــه ‪ ،‬وبدراســة القــرار وصــورة ضبطــه قررنــا املوافقــة‬\n    ‫علــى احلكــم ‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                                 ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪9‬‬\n\f10\n\f11\n\f12\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"ca29cb00-ff93-515e-9771-74b0d5d4a25f","source_page_start":5,"source_page_end":12,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"caf9b315ca938725a1e2ec005486673325b7d835caa07c4e76e93053ee372b87","normalized_text_hash":"a75ff40f9d8940874255d914034acf8f09fa7f04c2942aa291216f1ceeccb239","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v24-p5-3423238"},{"id":"87f1085a-c6ff-5017-8b07-b4e3688a19e9","document_type":"judgment","category":"judicial","subcategory":"general","title":"شهادة زور -تدليس لدى القاضي يف المحكمة -ثبوت -صرف نظر- تعزير -جلد -تعهد -إعادة إثبات زواج قائم.","document_number":"34269796","case_number":"34242667","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة املتضمن انه تقدم اليهم املدعى عليه الرابع","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/17","year":"1434","subject":"شهادة زور -تدليس لدى القاضي يف المحكمة -ثبوت -صرف نظر- تعزير -جلد -تعهد -إعادة إثبات زواج قائم.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪ 34269796 :‬تاريخه‪1434/7/17 :‬هـ‬\n                        ‫رقم الدعوى‪34242667 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n              ‫‪ 34328805‬تاريخه‪1434/10/12 :‬هـ‬\n\n\n     ‫شــهادة زور ‪ -‬تدليــس لــدى القاضــي يف احملكمــة ‪ -‬ثبــوت ‪ -‬صــرف نظــر‪-‬‬\n                                ‫تعزيــر ‪ -‬جلــد ‪ -‬تعهــد ‪ -‬إعــادة إثبــات زواج قائــم‪.‬‬\n\n\n\n\n     ‫مــا اســتند إليــه القاضــي مــن املبــادئ العامــة وقواعد العدالة يف تســبيب‬\n                                                                         ‫حكمه‪.‬‬\n\n\n\n\n     ‫اتهــام املدعــي العــام للمدعــى عليهمــا الثانــي والرابــع بالتدليــس أمــام‬\n     ‫القاضــي الشــرعي يف أمــر النــكاح واتهــام املدعــى عليهمــا األول‬\n     ‫والثالــث بشــهادة الــزور وبطلــب إثبــات مــا اســند اليهــم واحلكــم عليهــم‬\n                                                         ‫بعقوبــة تعزيريــة رادعــة‪.‬‬\n                                                          ‫ومبواجهة املدعى عليهم‬\n                      ‫‪ -‬أقر املدعى عليهما الثاني والرابع مبا جاء يف الدعوى ‪.‬‬\n     ‫‪ -‬أنكــر املدعــى عليهمــا األول والثالــث بتدليــس املدعــى عليهمــا الثانــي‬\n                                                                            ‫والرابع‪.‬‬\n                                                          ‫وعليه قررت احملكمة‪:‬‬\n     ‫‪ -‬إدانــة املدعــى عليهمــا الثانــي والرابــع مبــا جــاء يف الدعــوى واحلكــم‬\n     ‫عليهمــا بجلدهمــا أربعــن جلــدة دفعــة واحــدة وأخــذ التعهــد املشــدد‬\n‫‪13‬‬\n\f‫عليهمــا بعــدم العــودة ملــا بــدر منهمــا وعــدم ثبــوت إدانــة األول والثالــث‬\n                    ‫بشــهادة الــزور وصــرف النظــر عــن طلــب تعزيرهمــا‪.‬‬\n‫‪ -‬وقــرر املدعــي العــام االعتــراض وطلــب االســتئناف بالئحــة وقــرر‬\n                                                  ‫املدعــى عليهــم القناعــة ‪.‬‬\n                                ‫‪ -‬صدق احلكم من محكمة االستئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة مبكــة املكرمــة برقــم ‪ 34242667‬وتاريــخ‬\n‫‪ 1434/05/26‬ه ـ املقيــدة باحملكمــة برقــم ‪ 341281143‬وتاريــخ‬\n‫‪ 1434/05/26‬ه ـ ففــي يــوم األحــد املوافــق‪ 1434/07/16‬ه ـ افتتحــت‬\n‫اجللسة الساعة ‪ 11 : 30‬وفيها حضر املدعي العام ‪ ......‬مبوجب خطاب‬\n‫التكليــف مــن مرجعــه رقــم ه ـ م ‪/2/‬أ‪ 2108/‬يف ‪1434/5/5‬ه ـ وادعــى‬\n‫علــى احلاضريــن كل مــن ‪ ..... -1‬مينمــاري اجلنســية باالقامــة رقــم (‪)....‬‬\n‫و‪ ..... -2‬ماينمــاري اجلنســية (‪ ).....‬و‪ ..... -3‬ماينمــاري اجلنســية باالقامــة‬\n‫رقــم (‪ ).......‬و‪ ...... -4‬ماينمــاري اجلنســية باالقامــة رقــم (‪ ).....‬حيــث انــه‬\n‫بتاريــخ ‪1434/2/20‬ه ـ تبلــغ مركــز شــرطة اجيــاد عــن حالــة جنائيــة‬\n‫مبوجــب كتــاب فضيلــة القاضــي ‪ ....‬القاضــي باحملكمــة العامة مبكة‬\n‫املكرمــة املتضمــن انــه تقــدم اليهــم املدعــى عليــه الرابــع ‪ ....‬بطلــب عقــد‬\n‫زواجــه باملــرأة ‪ ......‬بواليــة اخيهــا املدعــى عليــه الثاني ‪ .....‬وشــهادة املدعى‬\n‫عليهمــا االول ‪ ....‬والثالــث ‪ ....‬وعقــد لهمــا وصــدر لهمــا القــرار الشــرعي‬\n‫رقــم ‪ 33330561‬يف ‪1433/7/7‬ه ـ وتقــدم لهــم املدعــى عليــه الرابــع بعــد‬\n\n                                                                                         ‫‪14‬‬\n\f     ‫ســبعة اشــهر مفيــدا بــأن الــزواج كان بتاريــخ ‪1432/12/20‬ه ـ وانــه لــم‬\n     ‫يذكــر للمحكمــة خلشــيته مــن تعطــل االجــراءات وصــدق الشــاهدان‬\n     ‫املدعــى عليهمــا االول والثالــث علــى ذلــك وبســماع اقــوال املدعــى عليــه‬\n     ‫الرابــع ‪ ....‬اقــر بانــه قبــل ســتة اشــهر عقــد علــى امــرأة بواليــة املدعــى‬\n     ‫عليــه الثانــي ثــم ذهــب الــى احملكمــة ولــم يذكــر للقاضــي انــه ســبق‬\n     ‫ان عقــد علــى املــرأة لكونــه كان خائفــا وبســماع اقــوال املدعــى عليــه‬\n     ‫الثانــي أقــر بأنــه عقــد ألختــه علــى املدعــى عليــه الرابــع ثــم ذهــب معــه‬\n     ‫إلــى احملكمــة كــون العقــد الــذي معهــم غيــر صحيــح ويريــدون عرضــه‬\n     ‫علــى القاضــي وبســماع اقــوال املدعــى عليــه االول ‪ ....‬اقــر بانــه قبــل ســنة‬\n     ‫ابلغــه الثانــي ان اختــه ســوف تتــزوج ويريــده ان يشــهد علــى ذلــك ثــم ذهــب‬\n     ‫معهــم إلــى احملكمــة ولــم يعلــم بــأن هنــاك زواج ســابق وبســماع اقــوال‬\n     ‫املدعــى عليــه الثالــث ‪ .....‬اقــر بانــه قبــل ســنة طلــب منــه الثانــي ان يشــهد‬\n     ‫علــى زواج اختــه وال يعلــم بأنهــا متزوجــة من الســابق وانتهــى التحقيق الى‬\n     ‫توجيــه االتهــام للمدعــى عليهمــا الثانــي والرابــع بالتدليــس امــام القاضــي‬\n     ‫الشــرعي يف امــر النــكاح واتهــام املدعــى عليهمــا االول والثالــث بشــهادة‬\n     ‫الــزور وذلــك لالدلــة والقرائــن املوضحــة بالدعــوى وحيــث ان مــا اقــدم‬\n     ‫عليــه املدعــى عليهــم وهــم بكامــل ارادتهــم املعتبــرة شــرعا فعــل محــرم‬\n     ‫ومعاقــب عليــه شــرعا لــذا اطلــب اثبــات مــا اســند اليهــم واحلكــم عليهــم‬\n     ‫بعقوبــة تعزيريــة رادعــة هــذه دعــواي وبســؤال املدعــى عليهــم أجــاب‬\n     ‫األول ‪ ...‬والثالــث ‪ ....‬بقولهمــا مــا ذكــره املدعــي العــام مــن شــهادتنا‬\n     ‫لــدى القاضــي علــى الــزواج فصحيــح ومــا ذكــره عــن شــهادة الــزور فغيــر‬\n     ‫صحيــح والواقــع أننــا حضرنــا للمحكمــة للشــهادة علــى عقــد النــكاح‬\n     ‫الــذي ســيجريه القاضــي ولــم نعلــم أنــه يوجــد عقــد ســابق هــذه إجابتنــا‬\n\n\n‫‪15‬‬\n\f‫كمــا أجــاب املدعــى عليــه الثانــي بقولــه ما ذكــره املدعي العــام صحيح‬\n‫وقــد عقــدت للرابــع علــى أختــي بواليتي وبشــهادة شــهود وبحضور مأذون‬\n‫شــرعي وكتبنــا ورقــة بذلــك ثــم تقدمنــا للمحكمــة إلثبــات العقــد‬\n‫ولكنــي كنــت خائفــا وال أعــرف أتصــرف هــذه إجابتــي كمــا أجــاب‬\n‫املدعــى عليــه الرابــع بقولــه مــا ذكــره املدعــي العــام صحيــح حيــث‬\n‫تقدمــت للمحكمــة بطلــب إثبــات الــزواج فرفضــوا اســتقبال طلبــي لعــدم‬\n‫وجــود إقامــة فعقــدت علــى املــرأة بواليــة أخيهــا وشــهادة شــهود ومــأذون‬\n‫شــرعي ثــم حصلــت علــى اإلقامــة وتقدمــت للمحكمــة بطلــب اإلثبــات‬\n‫وحصــل مــا حصــل ولــم نقصــد التدليــس ولكــن هــذا حــال كثيــر مــن‬\n‫البرماويــن واملقصــود اإلثبــات هــذه إجابتــي وأضــاف الثانــي والرابــع‬\n‫إن األول والثالــث ال يعلمــون بالعقــد األول ولــم يحضــروه وقــال املدعــي‬\n‫العــام أطلــب االطــاع علــى املعاملــة وبدراســة املعاملــة لــم أجــد للمدعــى‬\n‫عليهمــا األول والثالــث اعترافــا بالعلــم بالعقــد األول فبنــاء علــى مــا‬\n‫تقــدم مــن الدعــوى واإلجابــة وإلــى إقــرار املدعــى عليهمــا الثانــي والرابــع‬\n‫بدعــوى املدعــي العــام وإنــكار األول والثالــث وال بينــة عليهمــا لــذا فقــد‬\n‫ثبــت لــدي إدانــة املدعــى عليهمــا الثانــي ‪ ....‬والرابــع ‪ ....‬مبــا أســند إليهمــا‬\n‫مــن التدليــس أمــام القاضــي إلثبــات النــكاح وحكمــت بتعزيــر كل‬\n‫واحــد منهمــا بجلــده أربعــن جلــدة دفعــة واحــدة وأخــذ التعهــد املشــدد‬\n‫عليهمــا ‪ -‬بعــدم العــودة ملــا بــدر منهمــا ‪ -‬ولــم يثبــت لــدي إدانــة األول‬\n‫والثالــث بشــهادة الــزور وصرفــت النظــر عــن طلــب تعزيرهمــا وبعــرض‬\n‫احلكــم قنــع املدعــى عليهــم وعــارض املدعــي العــام وطلــب االســتئناف‬\n‫بالئحــة فأجيــب لطلبــه وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n           ‫محمــد وعلــى الــه وصحبــه اجمعــن حــرر يف ‪1434/7/16‬هــ‪.‬‬\n\n\n                                                                                           ‫‪16‬‬\n\f     ‫احلمــد هلل وحــده وبعــد فلــدي انــا ‪ ...‬القاضــي باحملكمــة اجلزائيــة مبكــة‬\n     ‫املكرمــة القائــم بعمــل املكتــب القضائــي الســادس بنــاء علــى خطــاب‬\n     ‫التكليــف الصــادر مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبكــة‬\n     ‫املكرمــة رقــم ‪ 342053882‬يف ‪1434/8/24‬ه ـ وعليــه فقــد عــادت‬\n     ‫املعاملــة مــن محكمــة االســتئناف وبرفقهــا القــرار رقــم ‪34328805‬‬\n     ‫يف ‪1434/10/12‬ه ـ املتضمــن املوافقــة والتصديــق علــى احلكــم وبــاهلل‬\n     ‫التوفيــق ‪.‬قاضــي اســتئناف‪ ..... /‬ختــم‪ .‬توقيــع‪ .‬قاضــي اســتئناف‪/‬د‪......‬‬\n     ‫ختــم‪ .‬توقيــع‪ .‬رئيــس الدائــرة‪ ...../‬ختــم‪ .‬توقيــع لــذا جــرى احلاقــه واثباتــه‬\n                                                         ‫حــرر يف ‪1434/11/12‬ه ـ ‪.‬‬\n\n\n\n\n‫‪17‬‬\n\f18\n\f19\n\f20\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"ca29cb00-ff93-515e-9771-74b0d5d4a25f","source_page_start":13,"source_page_end":20,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2a22f4a1748d1386745c6d6d04124aad4cb5d6e55ab8015c19a31dbd087f0860","normalized_text_hash":"aa1d44257df370348976ab49783dd7b5518a915f15884bd5b723971133faf1c8","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v24-p13-34269796"},{"id":"92ab5759-f587-5032-9d53-40ab77188311","document_type":"judgment","category":"judicial","subcategory":"general","title":"حلف مين كاذبة -اليمن يف اخلصومة جتري على نية املستحلف ال على قصد احلالف وقت حلفه -ظروف مخففة للعقوبة -توبيخ املدعى عليه يف مجلس احلكم وتعزيره بأخذ التعهد .","document_number":"35103751","case_number":"34337025","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1435/1/3","year":"1434","subject":"حلف مين كاذبة -اليمن يف اخلصومة جتري على نية املستحلف ال على قصد احلالف وقت حلفه -ظروف مخففة للعقوبة -توبيخ املدعى عليه يف مجلس احلكم وتعزيره بأخذ التعهد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 35103751 :‬تاريخه‪1435/1/3 :‬هـ‬\n                       ‫رقم الدعوى‪34337025 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n               ‫‪ 35121098‬تاريخه‪1435/1/21 :‬هـ‬\n\n\n     ‫حلــف ميــن كاذبــة ‪ -‬اليمــن يف اخلصومــة جتــري على نية املســتحلف‬\n     ‫ال علــى قصــد احلالــف وقــت حلفــه ‪ -‬ظــروف مخففــة للعقوبــة‪ -‬توبيــخ‬\n                     ‫املدعــى عليــه يف مجلــس احلكــم وتعزيــره بأخــذ التعهــد ‪.‬‬\n\n\n\n\n     ‫‪ -‬قولــه صلــى اهلل عليــه وســلم (مــن اقتطــع حــق امــرئٍ مســلم بيمينــه‬\n                                ‫فقــد أوجــب اهلل لــه النــار وحــرم عليــه اجلنــة) ‪.‬‬\n     ‫‪ -‬عــد النبــي صلــى اهلل عليــه وســلم اليمــن القتطــاع حــق امــرئ مســلم‬\n     ‫إحــدى الكبائــر كمــا يف حديــث ابــن عمــر رضــي اهلل عنــه عنــد االمــام‬\n                                                                               ‫أحمــد‪.‬‬\n\n\n\n\n     ‫جــرى توجيــه االتهــام للمدعــى عليــه باحللــف كذبـ ًا أمــام القاضــي وذلــك‬\n     ‫بعدمــا تقدمــت املدعيــة بصحيفــة دعــوى أمــام احملكمــة العامــة متهمــة‬\n     ‫املدعــى عليــه بقيامــه باحللــف كذب ـ ًا أمــام ناظــر القضيــة حيــال عــدم‬\n     ‫اســتخدامه لبطاقتهــا البنكيــة‪ -‬طلــب املدعــي العــام احلكــم عليــه‬\n     ‫بعقوبــة تعزيريــة يف احلــق العــام‪ -‬بعــرض الدعــوى علــى املدعــى عليــه‬\n     ‫أنكرهــا‪ ،‬ودفــع أنــه حلــف لهــا أنــه لــم يســحب ببطاقــة الصــراف اآلليــة‬\n     ‫التــي تخصهــا مبلغـ ًا لنفســه إال مــا تعطيــه إيــاه بطيــب نفــس منهــا‪ -‬جــرى‬\n\n‫‪21‬‬\n\f‫االطــاع علــى اعتــراف املدعــى عليــه حتقيق ـاً‪ ،‬كمــا جــرى االطــاع‬\n‫علــى صــك احلكــم املتضمــن لليمــن املذكــورة‪ -‬ملــا كانــت اليمــن يف‬\n‫اخلصومــة جتــري علــى نيــة املســتحلف ال علــى قصــد احلالــف وقــت حلفــه‬\n‫لــذا ثبتــت إدانــة املدعــى عليــه باحللــف عنــد القاضــي يف اخلصومــة التــي‬\n‫كانــت بينــه وبــن زوجتــه علــى خــاف الواقــع‪ ،‬ونظــر ًا لكــون املدعــى‬\n‫عليــه كبيــر ًا يف الســن يتصــور منــه اجلهــل يف أحــكام الشــريعة وعــدم‬\n‫فســر ميينــه مبــا هــو محتمــل فقــد‬\n                                    ‫االدراك ملــآالت األفعــال خصوصـ ًا وقــد ّ‬\n‫جــرى االكتفــاء بتوبيــخ املدعــى عليــه يف مجلــس احلكــم وتبيــن لــه‬\n‫عاقبــة اليمــن الفاجــرة ومت احلكــم بأخــذ التعهــد عليــه بعــدم العــودة‬\n‫ملــا حصــل‪ -‬بعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه القناعــة‬\n‫بــه وأمــا املدعــي العــام فقــرر االعتــراض وطلــب التمييــز مكتفي ـ ًا مبــا‬\n‫قدمــه يف الئحــة االدعــاء العــام وبعــد رفــع احلكــم حملكمــة االســتئناف‬\n                                                         ‫متــت املصادقــة عليــه‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬رئيــس احملكمــة العامــة يف عيــون‬\n‫اجلــواء وبنــاء علــى املعاملــة احملالــة لنــا من فضيلة رئيــس احملكمة العامة‬\n‫مبحافظــة عيــون اجلــواء برقــم ‪ 34337025‬وتاريــخ ‪1434/07/19‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 341752473‬وتاريــخ ‪1434/7/19‬ه ـ ففــي‬\n‫يــوم الثالثــاء املوافق‪1434/08/09‬ه ـ افتتحــت اجللســة الســاعة احلاديــة‬\n‫عشــرة صباح ـ ًا وفيهــا حضــر ‪ ......‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم ‪ ......‬بصفتــه املدعــي العــام يف هيئــة التحقيــق واالدعــاء العــام‬\n‫يف عيــون اجلــواء وحضــر حلضــوره املدعــى عليــه ‪......‬ســعودي اجلنســية‬\n\n                                                                                        ‫‪22‬‬\n\f     ‫بالســجل املدنــي رقــم ‪ ......‬وبســؤال املدعــي العــام عــن دعــواه أبــرز الئحــة‬\n     ‫الدعــوى العامــة رقــم ( ه ـ ص‪ -2/9‬أ ‪ )48/‬لعــام ‪1434‬ه ـ يف القضيــة‬\n     ‫رقــم (‪ ( 3361000089‬وفيهــا مــا نصــه‪ »:‬احلمــد هلل وحــده والصــاة‬\n     ‫والســام علــى مــن ال نبــي بعــده وبعــد ‪ :‬بصفتــي عضــو هيئــة التحقيــق‬\n     ‫واالدعــاء العــام بدائــرة محافظــة عيــون اجلــواء أدعــي علــى ‪ ،......-:‬البالــغ‬\n     ‫مــن العمــر(‪ )77‬عام ـ ًا ‪ ،‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم‬\n     ‫(‪ )......‬متعلــم ‪ ،‬متــزوج ‪ ،‬متســبب ‪ ،‬لــم يوقــف ‪.‬بتاريــخ ‪1428/5/6‬ه ـ‬\n     ‫تقدمــت املواطنــة ‪ ...... /‬بصحيفــة دعــوى أمــام احملكمــة العامــة‬\n     ‫ببريــدة تدعــي فيهــا بــأن زوجهــا املذكــور قــد قــام بتطليقهــا بتاريــخ‬\n     ‫‪1428/5/4‬ه ـ وأخــذه لذهــب عائــد لهــا بقيمــة (‪ )60000‬ســتني ألــف‬\n     ‫ريــال والقيــام ببيعــه وكذلــك أخــذه مــن راتبهــا مبلــغ وقــدره (‪)2400‬‬\n     ‫ألفــن وأربعمائــة ريــال وكفالتــه بقــرض يبلــغ (‪ )48000‬ثمــان وأربعــن‬\n     ‫ألــف ريــال مــن أحــد البنــوك وحيازتــه لبطاقــة الصرافــة العائــدة لهــا وقــد‬\n     ‫أدى املذكــور اليمــن أمــام القاضــي ونصــه (أقســم بــاهلل العلــي العظيــم‬\n     ‫أننــي لــم آخــذ البطاقــة ولــم أصــرف منهــا ولــم يقــم أحــد بصرفهــا بطلبــي‬\n     ‫وأن الــذي يســتلم الراتــب هــي وأن املبلــغ الــذي تعطينــي إيــاه إمنــا هــو‬\n                                                                  ‫بطيبــة نفــس منهــا) ‪.‬‬\n     ‫وبتاريــخ ‪1433/4/17‬ه ـ تقدمــت املدعيــة بصحيفــة دعــوى أمــام‬\n     ‫احملكمــة العامــة متهمــة املذكــور بقيامــه باحللــف كذبـ ًا أمــام فضيلــة‬\n                  ‫ناظــر القضيــة حيــال عــدم اســتخدامه لبطاقــة صرافتهــا ‪.‬‬\n     ‫وباســتجواب املذكــور اعتــرف بقيامــه بالصــرف مــن بطاقــة زوجتــه‬\n     ‫الســابقة وأنــه يقــوم بإعطائهــا املــال املصــروف مــن البطاقــة وذكــر أنــه‬\n         ‫يقصــد باحللــف أمــام القاضــي بأنــه لــم يصــرف منهــا شــيء لنفســه ‪.‬‬\n\n\n‫‪23‬‬\n\f‫وملــا أشــير إليــه إقــرار توجيــه االتهــام ل‪......‬باحللــف كذبـ ًا أمــام القاضــي‬\n‫حســبما تضمنــه اعترافــه املــدون علــى الصفحتــن رقــم (‪ )2،1‬مبحضــر‬\n                                             ‫االســتجواب املرفــق لفــه رقــم (‪. )49‬‬\n‫وحيــث أنــه مــا أقــدم عليــه املذكــور فعــل محــرم ومعاقــب عليــه‬\n‫شــرعاً‪،‬لذا أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة‬\n‫تردعــه وتزجــر غيــره اســتناد ًا للمــادة (‪ )126‬مــن نظــام اإلجــراءات‬\n‫اجلزائيــة )علم ـ ًا أن احلــق اخلــاص مــازال قائم ـاً» ( هكــذا ادعــى املدعــي‬\n‫العــام ولــدى عــرض الدعــوى علــى املدعــى عليــه أجــاب بقولــه‪ :‬مــا ذكــره‬\n‫املدعــي العــام مــن أننــي حلفــت كاذبـ ًا أمــام القاضــي الــذي كان ينظــر‬\n‫دعــوى ماليــة مقامــة مــن زوجتــي ضــدي يف احملكمــة العامــة ببريــدة‬\n‫فغيــر صحيــح بــل الصحيــح أننــي حلفــت لهــا بأننــي لــم أســحب ببطاقــة‬\n‫الصــراف اآلليــة التــي تخصهــا مبلغـ ًا لنفســي إال مــا تعطينــي إيــاه بطيــب‬\n‫نفــس منهــا هكــذا أجــاب فســألت املدعــي العــام هــل لديــه بينــة علــى مــا‬\n‫ادعــاه فأجــاب قائـاً‪ :‬بينتــي علــى ذلــك مــا أشــير إليــه يف الئحــة االدعــاء‬\n‫العــام مــن اعتــراف املدعــى عليــه وأطلــب الرجــوع إليــه‪ ،‬هكــذا أجــاب‬\n‫فجــرى االطــاع علــى اســتجواب املدعــى عليــه علــى ص ‪ 2 - 1‬مــن ملــف‬\n‫التحقيــق لفــه ‪ 49‬وقــد وجــد فيــه مــا نصــه « أنــا حلفت أمــام القاضي أني‬\n‫لــم آخــذ البطاقــة ولــم أصــرف منهــا شــيئ ًا لنفســي ولم يقم أحــد بالصرف‬\n‫منهــا لنفســي ومــا أقــوم بــه هــو أنــي آخــذ البطاقــة مــن زوجتــي ثــم أعطيها‬\n‫ملوظــف البنــك ليصــرف لنــا مــن آلــة الصــراف ثــم أعيــد البطاقــة واملبلــغ‬\n‫لزوجتــي « ومــا نصــه « أنــا مــا قصــدت أمــام القاضــي أن أصــرف منهــا‬\n‫شــيئ ًا لنفســي وإمنــا آخــذ البطاقــة وأقــوم بالســحب مــن اآللــة مــن خــال‬\n‫أحــد العاملــن بالبنــك بنــاء لطلــب زوجتــي وحيــث إننــي كبيــر يف الســن‬\n\n\n                                                                                         ‫‪24‬‬\n\f     ‫فلــم يتضــح لــي مــا حلفــت بــه أمــام القاضــي « هــذا مــا تضمنــه اســتجواب‬\n     ‫املدعــى عليــه وبعرضــه عليــه صــادق علــى مــا جــاء فيــه ثــم جــرى االطــاع‬\n     ‫علــى الصــك الصــادر مــن احملكمــة العامــة ببريــدة برقــم ‪11 / 1 / 134‬‬\n     ‫يف ‪1428/7/17‬ه ـ فوجــد متضمن ـ ًا دعــوى مــن مــوكل زوجــة املدعــى‬\n     ‫عليــه ‪......‬ضــد ‪(......‬املدعــى عليــه هنــا) والتــي يطلــب فيهــا املدعــي إلــزام‬\n     ‫املدعــى عليــه بإعــادة مبالــغ أخذهــا مــن موكلتــه وقــد جــاء فيــه مــا نصــه‬\n     ‫(وطلــب املدعــي حلفــه علــى رواتبهــا بأنــه لــم يأخــذ بطاقتهــا ولــم يأخــذ‬\n     ‫أي مبلــغ إال بطيبــة نفــس منهــا فاســتعد بذلــك ثــم قــام وقــال أقســم بــاهلل‬\n     ‫العظيــم أنــي لــم آخــذ البطاقــة ولــم أصــرف فيهــا ولــم يقــم أحــد بصرفهــا‬\n     ‫بطلبــي وأن الــذي يســتلم الراتــب هــي وأن املبلــغ الــذي تعطينــي امنــا هــو‬\n     ‫بطيــب نفــس منهــا هكــذا حلــف) املنتهــي برجــوع حاكمــه عمــا حكــم‬\n     ‫بــه وللتأمــل واصــدار مــا يلــزم جــرى رفــع اجللســة وحــددت للطرفــن‬\n     ‫موعــد ًا يف يــوم الســبت املوافــق ‪1434/11/8‬ه ـ الســاعة العاشــرة‬\n     ‫صباحـ ًا وعليــه حصــل التوقيــع وقــد أقفلــت هــذه اجللســة الســاعة احلاديــة‬\n     ‫عشــرة صباح ـ ًا وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n     ‫آلــه وصحبــه وســلم حــرر يف ‪1434/8/9‬ه ـ احلمــد هلل وحــده وبعــد فلــدي‬\n     ‫أنــا ‪......‬رئيــس احملكمــة العامــة مبحافظــة عيــون اجلــواء وبنــاء علــى‬\n     ‫املعاملــة املقيــدة باحملكمــة برقم ‪ 341752473‬وتاريخ ‪1434/7/19‬هـ‬\n     ‫ففــي يــوم الثالثــاء املوافــق‪ 1434/11/04‬ه ـ افتتحــت اجللســة الســاعة‬\n     ‫‪ 00:11‬صباح ـ ًا وفيهــا حضــر املدعــي العــام بدائــرة التحقيــق واالدعــاء‬\n     ‫العــام مبحافظــة عيــون اجلــواء ‪......‬واملدعــى عليــه ‪......‬وبدراســة القضيــة‬\n     ‫وتأملهــا وملــا كان املدعــي العــام يطلــب يف دعــواه هــذه احلكــم بتعزيــر‬\n     ‫املدعــى عليــه جــزاء حلفــه كاذب ـ ًا أمــام القاضــي يف القضيــة الصــادر‬\n\n\n‫‪25‬‬\n\f‫فيهــا الصــك رقــم ‪ 11/1/134‬يف ‪1428/7/17‬ه ـ مــن احملكمــة العامة‬\n‫ببريــدة املنتهــي برجــوع القاضــي عمــا حكــم بــه وملــا كان املدعــى عليــه‬\n‫مقــر ًا بــأداء اليمــن املرصــود نصهــا يف ســياق الدعــوى يف اجللســة املاضية‬\n‫مبينـ ًا أن قصــده وقــت حلفــه أنــه لــم يصــرف مــن بطاقــة الصــراف اآللــي‬\n‫التابعــة لزوجتــه شــيئ ًا لنفســه وملــا كانــت اليمــن يف اخلصومــة جتــري‬\n‫علــى نيــة املســتحلف ال علــى قصــد احلالــف وقــت حلفــه فقــد ثبــت لــدي‬\n‫ادانــة املدعــى عليــه ‪......‬باحللــف عنــد القاضــي يف اخلصومــة التــي كانــت‬\n‫بينــه وبــن زوجتــه علــى خــاف الواقــع وحيــث جــاء الوعيــد الشــديد ملــن‬\n‫ـرئ مســلم بيمينــه يف قولــه صلــى اهلل عليــه وســلم (مــن‬  ‫اقتطــع حــق امـ ٍ‬\n‫ـرئ مســلم بيمينــه فقــد أوجــب اهلل لــه النــار وحــرم عليــه‬\n                                                               ‫اقتطــع حــق امـ ٍ‬\n‫وعدهــا النبــي صلــى اهلل عليــه وســلم احــدى الكبائــر كمــا يف‬     ‫اجلنــة) ّ‬\n‫حديــث ابــن عمــر رضــي اهلل عنــه عنــد االمــام احمــد وملــا كان املدعــى‬\n‫عليــه كبيــر ًا يف الســن يتصــور منــه اجلهــل يف أحــكام الشــريعة وعــدم‬\n‫فســر ميينــه مبــا هــو محتمــل‬ ‫االدراك ملــآالت األفعــال خصوص ـ ًا وقــد ّ‬\n‫فلذلــك فقــد اكتفيــت يف احلــق العــام بتوبيــخ املدعــى عليــه يف مجلــس‬\n‫احلكــم وبينــت لــه عاقبــة اليمــن الفاجــرة ففهــم ذلــك وحكمــت بأخــذ‬\n‫التعهــد عليــه بعــدم العــودة ملــا حصــل منــه هــذا مــا حكمــت بــه يف احلــق‬\n‫العــام وبعرضــه علــى الطرفــن قــرر املدعــى عليــه القناعة بــه وأما املدعي‬\n‫العــام فقــد أبــدى اعتراضــه وطلــب التمييــز مكتفيـ ًا مبــا قدمــه يف الئحة‬\n‫ـاء عليــه فســيجري اصــدار قــرار شــرعي بهــذا احلكــم‬    ‫االدعــاء العــام وبنـ ً‬\n‫ـاء علــى املــادة ‪193‬‬ ‫وبعثــه حملكمــة االســتئناف مبنطقــة القصيــم بنـ ً‬\n‫مــن نظــام االجــراءات اجلزائيــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/11/4‬ه ـ الســاعة‬\n\n\n                                                                                       ‫‪26‬‬\n\f     ‫‪ 11:30‬احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة األولى‬\n     ‫لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة القصيــم علــى‬\n     ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة يف محافظــة عيــون‬\n     ‫اجلــواء الشــيخ‪....../‬برقم ‪ 341752473‬وتاريــخ ‪1435/1/11‬هــ؛ املقيــدة‬\n     ‫لدينــا برق ــم ‪ 341752473‬وتاريــخ ‪1435/1/14‬هــ؛ املرفــق بهــا القــرار‬\n     ‫رقــم ‪ 35103701‬وتاريــخ ‪1435/1/3‬هــ؛ الصــادر مــن فضيلتــه ؛اخلــاص‬\n     ‫بدعــوى املدعــي العــام ضد‪....../‬؛التهامــه باحللــف كاذب ـ ًا وقــد تضمــن‬\n     ‫القــرار حكــم فضيلتــه بتوبيــخ املدعــى عليــه وأخــذ التعهــد علــى النحــو‬\n     ‫املفصــل فيــه؛ وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا‬\n     ‫باألكثريــة املصادقــة علــى احلكــم‪ .‬واهلل املوفــق‪ ،‬وصلــى اهلل علــى‬\n                                         ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪27‬‬\n\f28\n\f29\n\f30\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"ca29cb00-ff93-515e-9771-74b0d5d4a25f","source_page_start":21,"source_page_end":30,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"945d92277bd2b9844f3fce782af3644a170798546560e77b9d5a3761b268af73","normalized_text_hash":"a03aa25d2c83f92c25a9480091812093e67eb50d21d09da89ee227fec9084aed","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v24-p21-35103751"},{"id":"4ec60bab-eef8-5eed-b414-078348d6ae2c","document_type":"judgment","category":"judicial","subcategory":"general","title":"تفحيط-مخالفات مرورية -تقدير قيمة سيارة مستأجرة -إقرار بالتفحيط -تعزير بالسجن والغرامة مبثل قيمة السيارة املرتكب عليها اجلرمية كونها مستأجرة.","document_number":"33400860","case_number":"33183096","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/09/03","year":"1434","subject":"تفحيط-مخالفات مرورية -تقدير قيمة سيارة مستأجرة -إقرار بالتفحيط -تعزير بالسجن والغرامة مبثل قيمة السيارة املرتكب عليها اجلرمية كونها مستأجرة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 33400860:‬تاريخه‪1433/09/03 :‬هـ‬\n                          ‫رقم الدعوى‪33183096:‬‬\n                    ‫رقم قرار التصديق من محكمة‬\n          ‫االستئناف‪ 341163:‬تاريخه‪1434/01/04:‬هـ‬\n\n\n\n     ‫تفحيط‪-‬مخالفــات مروريــة ‪ -‬تقديــر قيمــة ســيارة مســتأجرة‪ -‬إقــرار‬\n     ‫بالتفحيــط‪ -‬تعزيــر بالســجن والغرامــة مبثــل قيمــة الســيارة املرتكــب‬\n                                           ‫عليهــا اجلرميــة كونهــا مســتأجرة‪.‬‬\n\n\n\n\n     ‫‪ -‬الفقــرة (ج) مــن املــادة (‪ )69‬مــن نظــام املــرور والفقــرة (‪ )2/69‬مــن‬\n                                         ‫الالئحــة التنفيذيــة لنظــام املــرور ‪.‬‬\n\n\n\n\n     ‫مت توجيــه االتهــام للمدعــى عليــه مبمارســة التفحيــط للمــرة الثالثــة‬\n     ‫وذلــك بعــد اســتيقافه الرتكابــه مخالفــة التفحيــط وعــدم حملــه رخصــة‬\n     ‫قيــادة وتنزيــل املركبــة وتبــن أن عليــه (‪ )32‬مخالفــة مروريــة منهــا‬\n     ‫(‪ )3‬مخالفــات تفحيــط وأن املركبــة مســتأجرة‪ -‬طلــب املدعــي العــام‬\n     ‫بتعزيــره بســجنه وتغرميــه بدفــع قيمــة املثــل للمركبــة التــي مــارس عليهــا‬\n     ‫مخالفــة التفحيــط اســتنادا للفقــرة (ج) مــن املــادة (‪ )69‬مــن نظــام املــرور‬\n     ‫‪ -‬بعــرض الدعــوى علــى املدعــى عليــه صــادق عليها‪-‬جــرى االطــاع‬\n     ‫علــى تقديــر قيمــة الســيارة الصــادر مــن ثالثــة معــارض مببلــغ خمســن‬\n     ‫ألــف ريــال كمــا جــرى االطــاع علــى محضــر ضبــط املخالفــة املروريــة‬\n\n\n‫‪31‬‬\n\f‫املتضمــن طبــق مــا ذكــر املدعــي العــام يف دعــواه‪ -‬ثبتــت إدانــة املدعــى‬\n‫عليــه مبمارســة التفحيــط للمــرة الثالثــة ومت احلكــم عليــه بســجنه ملــدة‬\n‫شــهرين‪ ،‬وتغرميــه مبلــغ خمســن ألــف ريــال تدفــع للجهــة املختصــة‪-‬‬\n‫بعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه عــدم القناعــة باحلكــم‬\n‫وطلــب االســتئناف بالئحــة وقــرر املدعــي العــام عــدم االعتــراض‪-‬‬\n                               ‫تصديــق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي‬\n‫أنــا ‪ ....‬القاضــي باحملكمــة اجلزائيــة بالدمــام بنــاء علــى املعاملــة الــواردة‬\n‫مــن هيئــة التحقيــق واإلدعــاء العــام واملقيــدة لــدى احملكمــة برقــم‬\n‫‪ 33482273‬وتاريــخ ‪1433/3/14‬ه ـ واحملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة بالدمــام برقــم ‪ 33183096‬وتاريــخ ‪1433/3/14‬ه ـ‬\n‫افتتحــت اجللســة يف يــوم األحــد ‪1433/9/3‬ه ـ الســاعة الثانيــة وفيهــا‬\n‫ا فيهــا بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة‬‫قــدم املدعــي العــام ‪ ...‬دعــواه قائ ـ ً‬\n‫اإلدعــاء العــام لفــرع املنطقــة الشــرقية أدعــي علــى‪ .... /‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪ ....‬حيــث إنــه باالطــاع علــى محضــر‬\n‫ضبــط املخالفــة املروريــة املعــد مــن قبــل دوريــة املــرور الســرية تبــن أنــه‬\n‫بتاريــخ ‪1433/2/16‬ه ـ مت اســتيقاف ســيارة مــن نــوع نيســان بكــب‬\n‫لونهــا ذهبــي رقــم اللوحــة (…صنــع ســنة ‪2010‬م بقيــادة املدعــى عليــه‬\n‫وذلــك الرتكابــه مخالفــة التفحيــط وعــدم حملــه رخصــة قيــادة وتنزيــل‬\n‫املركبــة وتبــن أن عليــه (‪ )32‬مخالفــة مروريــة منهــا (‪ )3‬مخالفــات‬\n‫تفحيــط وأن املركبــة مســتأجرة باســم …‪ .‬وباســتجواب املدعــى عليــه‬\n                                                                                         ‫‪32‬‬\n\f     ‫أقــر مبمارســته التفحيــط وقــد انتهــى التحقيــق إلــى مســؤولية … جتــاه‬\n     ‫مخالفــة ممارســة التفحيــط للمــرة الثالثــة وذلــك لألدلة والقرائــن التالية‪:‬‬\n     ‫‪-1‬إقــرار املدعــى عليــه املنــوه عنــه واملــدون علــى الصفحــة رقــم (‪)3-2‬‬\n     ‫مــن ملــف التحقيــق املرفــق لفــة رقــم (‪ -2 )1‬محضــر ضبــط املخالفــة‬\n     ‫املرفــق لفــة (‪ -3 )18‬بيــان مخالفــات التفحيــط املســجلة عليــه املرفــق‬\n     ‫لفــة (‪ )5-3‬وحيــث إن مــا أقــدم عليــه املدعــى عليــه وهــو بكامــل أهليتــه‬\n     ‫املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه نظامـ ًا أطلــب إثبــات مــا أســند‬\n     ‫إليــه والنظــر يف احلكــم بســجنه وتغرميــه بدفــع قيمــة املثــل للمركبــة‬\n     ‫املوصوفــة التــي مــارس عليهــا مخالفــة التفحيــط اســتنادا للفقــرة (ج)‬\n     ‫مــن املــادة (‪ )69‬مــن نظــام املــرور هكــذا ادعــى وبعــرض الدعــوى‬\n     ‫ا مــا ذكــره املدعــي العــام مــن قيامــي‬    ‫علــى املدعــى عليــه أجــاب قائ ـ ً‬\n     ‫بالتفحيــط للمــرة الثالثــة صحيــح هكــذا أجــاب ثــم جــرى الرجــوع‬\n     ‫إلــى املعاملــة فوجــدت علــى لفــة رقــم (‪ )9‬تقديــر لقيمــة الســيارة مببلــغ‬\n     ‫خمســن ألــف ريــال صــادر مــن ثالثــة معــارض كمــا وجــدت علــى لفــة‬\n     ‫رقــم (‪ )18‬محضــر ضبــط املخالفــة املروريــة املتضمــن طبــق مــا ذكــر‬\n     ‫ـاء علــى مــا تقــدم مــن دعــوى املدعــي العــام‬  ‫املدعــي العــام يف دعــواه فبنـ ً‬\n     ‫وإجابــة املدعــى عليــه وإقــراره بالدعــوى وهــو بكامــل أهليتــه املعتبــرة‬\n     ‫شــرع ًا وبنــاء علــى الفقــرة (ج) مــن املــادة (‪ )69‬مــن نظــام املــرور والفقــرة‬\n     ‫ـاء علــى التقديــر الــذي‬\n                              ‫(‪ )2/69‬مــن الالئحــة التنفيذيــة لنظــام املــرور وبنـ ً‬\n     ‫قيمــت بــه الســيارة لــذا فقــد ثبــت لــدي إدانــة املدعــى عليــه مبمارســة‬\n     ‫التفحيط للمرة الثالثة وقررت اآلتي‪ :‬أوالً‪ :‬ســجنه ملدة شــهرين حتتســب‬\n     ‫منهــا مــدة إيقافــه‪ .‬ثاني ـاً‪ :‬تغــرمي املدعــى عليــه بدفــع مبلــغ خمســن ألــف‬\n     ‫ريــال تدفــع للجهــة املختصــة وبذلــك حكمــت وبعــرض احلكــم علــى‬\n\n\n‫‪33‬‬\n\f‫الطرفــن قــرر املدعــى عليــه عــدم القناعــة باحلكــم وطلــب االســتئناف‬\n‫بالئحــة يقدمهــا فأفهمتــه بأنــه ســوف يجــري بعــد قليــل تســليمه نســخة‬\n‫مــن احلكــم ليقــدم اعتراضــه خــال ثالثــن يوم ـ ًا مــن اآلن يكــون‬\n‫حقــه يف االســتئناف بعــد مضــي هــذه املــدة ســاقط ًا ففهــم ذلــك وأمــا‬\n‫املدعــي العــام فقــرر عــدم االعتــراض وبــاهلل التوفيــق وصلــى اهلل وســلم‬\n‫علــى نبينــا محمــد‪ .‬حــرر يف احلمــد هلل وحــده وبعــد ففــي يــوم األثنــن‬\n‫‪1434/1/26‬ه ـ افتتحــت اجللســة الســاعة التاســعة والربــع وفيهــا وردتنــا‬\n‫املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية وبرفقهــا القــرار‬\n‫الصــادر مــن الدائــرة اجلزائيــة األولــى برقــم ‪ 341163‬يف ‪1434/1/4‬ه ـ‬\n‫املتضمــن املصادقــة علــى احلكــم وبــاهلل التوفيــق وصلــى اهلل وســلم علــى‬\n                   ‫نبينــا محمــد‪ .‬حــرر يف ‪1434/1/26‬ه ـ ‪1433/9/3‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                 ‫‪34‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"ca29cb00-ff93-515e-9771-74b0d5d4a25f","source_page_start":31,"source_page_end":34,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d6611d2fb2c48b0a6d107036e0307334ea9e5cb7b69605adf4a9206eda6dd692","normalized_text_hash":"cba58cca973a568afd052aee1fdb0c69c764f1548e917fce64a9a74ec87a0fbe","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v24-p31-33400860"},{"id":"850543f8-9588-5e84-8676-1369926d95c5","document_type":"judgment","category":"judicial","subcategory":"general","title":"تفحيط -تفحيط وقيادة بتهور للمرة الثالثة -مسؤولية املدعى عليه جتاه مخالفته املرورية بنسبة - %100اقرار بالتفحيط وقيادة السيارة بتهور -إثبات إدانة -تعزير بالسجن ومصادرة السيارة املستخدمة بالتفحيط -الفقرة ( ج ) من املادة ( ) 69من نظام املرور.","document_number":"3422084","case_number":"33400147","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف باملنطقة الشرقية مبوجب اخلطاب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/01/25","year":"1434","subject":"تفحيط -تفحيط وقيادة بتهور للمرة الثالثة -مسؤولية املدعى عليه جتاه مخالفته املرورية بنسبة - %100اقرار بالتفحيط وقيادة السيارة بتهور -إثبات إدانة -تعزير بالسجن ومصادرة السيارة املستخدمة بالتفحيط -الفقرة ( ج ) من املادة ( ) 69من نظام املرور.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك ‪ 3422084:‬تاريخه‪1434/01/25 :‬هـ‬\n                          ‫رقم الدعوى‪33400147:‬‬\n                    ‫رقم قرار التصديق من محكمة‬\n         ‫االستئناف‪ 34204315:‬تاريخه‪1434/05/04:‬ه‬\n\n\n\n     ‫تفحيــط ‪ -‬تفحيــط وقيــادة بتهــور للمــرة الثالثــة ‪ -‬مســؤولية املدعــى‬\n     ‫عليــه جتــاه مخالفتــه املروريــة بنســبة ‪ - %100‬اقــرار بالتفحيــط وقيــادة‬\n     ‫الســيارة بتهــور ‪ -‬إثبــات إدانــة ‪ -‬تعزيــر بالســجن ومصــادرة الســيارة‬\n                                                        ‫املســتخدمة بالتفحيــط‬\n\n\n\n\n                               ‫‪ -‬الفقرة ( ج ) من املادة ( ‪ ) 69‬من نظام املرور‪.‬‬\n\n\n\n\n     ‫مت توجيــه االتهــام ل ــلمدعى عليــه بالقيــام بالتفحيــط والقيــادة بتهــور‬\n     ‫للمــرة الثالثــة وحتملــه كامــل املســؤولية بنســبة ‪ %100‬جتــاه مخالفاتــه‬\n     ‫وذلــك بعــد القبــض عليــه بعــد ممارســة «التفحيــط» وتبــن أن لديــه عــدد‬\n     ‫(‪ )11‬مخالفــة مروريــة منهــا ثــاث مخالفــات تفحيــط ‪ -‬بالبحــث عمــا‬\n     ‫إذا كان لديــه ســوابق اتضــح عــدم وجــود ســوابق مســجلة عليــه‪ -‬طلــب‬\n     ‫املدعــي العــام احلكــم علــى املدعــى عليــه بعقوبــة تعزيريــة ومبصــادرة‬\n     ‫الســيارة اســتناد ًا للمــادة (‪/69‬ج) مــن نظــام املــرور ‪ -‬بعــرض دعــوى‬\n     ‫ا وقــرر‬‫املدعــي العــام علــى املدعــى عليــه صــادق عليهــا جملــة وتفصي ـ ً‬\n     ‫أن ملكيــة الســيارة عائــدة إليــه‪ -‬مت احلكــم عليــه بســجنه ملــدة ثالثــة‬\n\n\n‫‪35‬‬\n\f‫أشــهر ومصــادرة الســيارة املشــار إليهــا يف الدعــوى‪ -‬بعــرض احلكــم‬\n‫علــى الطرفــن قــرر املدعــى عليــه االعتــراض بالئح ـ ٍة اعتراضيــة وقــرر‬\n‫املدعــي العــام عــدم االعتــراض وبعــد رفــع احلكــم حملكمــة االســتئناف‬\n                                                       ‫متــت املصادقــة عليــه‪.‬‬\n\n\n\n\n‫اجلزائيــة‬\n    ‫ّ‬        ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي يف احملكمــة‬\n‫بالدمــام ويف يــوم األربعــاء املوافق‪1434/01/21‬ه ـ افتتحــت اجللســة‬\n‫الســاعة ‪ 08 : 45‬وفيهــا قــدم املدعــي العــام ‪ ...‬دعــواه ضــد املدعــى عليــه‬\n‫ا فيهــا ‪ :‬إنــه بتاريخ‪1433/3/17‬ه ـ وأثنــاء قيــام الدوريــة األمنيــة‬  ‫‪ .....‬قائـ ً‬\n‫بعملهــا مبدينــة الدمــام مت مالحظــة ســيارة مــن نــوع (كابــرس) تاريــخ‬\n‫الصنــع (‪2007‬م) حتمــل اللوحــة رقــم (‪ ). . . .‬ميــارس مخالفــة التفحيــط‬\n‫والقيــادة بتهــور ومت التعميــم علــى الســيارة ويف تاريــخ ‪1433/4/12‬ه ـ مت‬\n‫القبــض علــى الســيارة املذكــورة بقيــادة املدعــى عليــه وتبــن أن لديــه‬\n‫عــدد (‪ )11‬مخالفــة مروريــة منهــا عــدد (‪ )3‬مخالفــات تفحيــط وبســماع‬\n‫أقوالــه واســتجوابه ‪ :‬أقــر بصحــة الواقعــة وأن الســيارة التــي معــه تعــود‬\n‫ملكيتهــا لــه شــخصي ًا وانتهــى التحقيــق معــه إلــى توجيــه االتهــام ل ــه‬\n‫بالقيــام مبخالفــة التفحيــط والقيــادة بتهــور للمــرة الثالثــة وحتملــه‬\n‫كامــل املســؤولية بنســبة ‪ %100‬جتــاه مخالفاتــه وذلــك لألدلــة والقرائــن‬\n‫التاليــة‪ -1:‬مــا جــاء بأقوالــه املدونــة علــى الصفحــات رقــم (‪3‬ـ ــ‪ )4‬املرفقــة‬\n‫علــى اللفــة رقــم (‪ -2)1‬مــا جــاء بقــرارات هيئــة الفصــل واملنازعــات جتــاه‬\n‫مخالفــة (التفحيــط) الثــاث املرفقــة على اللفات رقم ( ‪14‬ـ ‪15‬ـ‪-3)16‬ما‬\n‫جــاء بصحيفــة املخالفــات املســجلة عليــه وعددهــا (‪ )11‬مخالفــة املرفقــة‬\n\n                                                                                        ‫‪36‬‬\n\f     ‫علــى اللفــة رقــم (‪ )4‬وبالبحــث عمــا إذا كان لديــه ســوابق اتضــح عــدم‬\n     ‫وجــود ســوابق مســجلة عليــه وحيــث إن مــا أقــدم عليــه املدعــى عليــه وهــو‬\n     ‫ومعاقب عليه شــرع ًا ونظام ًا‬\n                                ‫ٌ‬       ‫بكامــل أهليتــه املعتبــرة شــرع ًا فعــلٌ محــرم‬\n     ‫أطلــب إثبــات مــا ُأســند إليــه واحلكــم عليه بعقوبــة تعزيرية تزجــره وتردع‬\n     ‫غيــره ومبصــادرة الســيارة املشــار إليهــا اســتناد ًا للمــادة (‪/69‬ج) من نظام‬\n     ‫املــرور واهلل املوفــق ويف هــذه اجللســة حضــر املدعــى عليــه ‪ ....‬ســعودي‬\n     ‫اجلنســية مبوجــب بطاقــة الهويــة الوطنيــة املــدون بهــا الرقــم ‪ ...‬وبعــرض‬\n     ‫ا ‪ :‬مــا ذكــره املدعــي العــام يف‬    ‫دعــوى املدعــي العــام عليــه أجــاب قائ ـ ً‬\n     ‫دعــواه صحيــح فقــد قمــت بالتفحيــط وقيــادة الســيارة بتهــور وصــدرت‬\n     ‫علــى مخالفــة مروريــة وهــذه املخالفــة ُتعتبــر املخالفــة املروريــة الثالثــة يف‬\n     ‫التفحيــط وأنــا مقتنـ ٌـع بإدانتــي يف هــذه املخالفــات الثــاث بنســبة ‪%100‬‬\n     ‫والســيارة املذكــورة يف الدعــوى تخصني وباســمي هــذه إجابتي ‪ .‬فنظر ًا‬\n     ‫ملــا تقــدم مــن الدعــوى واإلجابــة وحيــث صــادق املدعــى عليــه علــى دعــوى‬\n     ‫ـور يف جوابــه أعــاه وبعــد االطــاع‬      ‫املدعــي العــام وأقــر مبــا هــو مذكـ ٌ‬\n     ‫ـاء علــى الفقــرة ( ج ) مــن املــادة رقــم ( ‪ ) 69‬مــن‬ ‫علــى طيــات املعاملــة وبنـ ً‬\n     ‫نظــام املــرور لذلــك كلــه فقــد ثبــت لــدي إدانــة املدعــى عليــه بقيــادة‬\n     ‫الســيارة بتهــور وقيامــه بالتفحيــط وصــدور املخالفــة املروريــة الثالثــة يف‬\n     ‫ذلــك ومســؤوليته جتــاه هــذه املخالفــات الثــاث بنســبة ‪ %100‬وقــررت‬\n     ‫معاقبتــه علــى ذلــك كلــه مبــا يلــي ‪ :‬أوالً‪ -‬بســجنه ملــدة ثالثــة أشــهر‬\n     ‫ُيحســب منهــا مــدة إيقافــه علــى ذمــة القضيــة قبــل إطالقــه بالكفالــة‬\n     ‫ثانيـاً‪ -‬مصــادرة ســيارته املشــار إلــى أوصافهــا يف الدعــوى وبذلــك أجمــع‬\n     ‫حكمــت وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه االعتــراض‬\n     ‫بالئحـ ٍة اعتراضيــة مقدمـ ًة منــه ف ُأجيــب لطلبــه وجــرى إفهامــه أن عليــه‬\n\n\n‫‪37‬‬\n\f‫املراجعــة يــوم الســبت ‪1434/1/24‬ه ـ الســاعة ‪ 12.30‬الســتالم صــورة‬\n‫مــن احلكــم وأنــه يف التاريــخ املذكــور ســوف يتــم إيــداع القــرار ملــف‬\n‫الدعــوى وســوف يكــون ذلــك اإليــداع مجريـ ًا ملــدة الثالثــن يومـ ًا ُيقــدم‬\n‫خاللهــا الئحتــه االعتراضيــة وأنــه مبضــي هــذه املــدة دون تقــدمي الالئحــة‬\n‫ويرفــع احلكــم حملكمــة االســتئناف‬         ‫ســوف يســقط حقــه يف تقدميهــا ُ‬\n‫بدونهــا فامتثــل وأمــا املدعــي العــام فقــرر عــدم االعتــراض واهلل املوفــق‬\n‫وصلــى اهلل علــى نبينــا محمــد وآلــه وســلم احلمــد هلل وحــده وبعــد ويف يــوم‬\n‫اإلثنــن املوافق‪1434/01/26‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــى‬\n‫عليــه وجــرى تســليمه صــورة مــن احلكــم الصــادر برقــم ‪ 3422084‬يف‬\n‫‪1434/1/25‬ه ـ وجــرى إفهامــه بــأن عليــه تقــدمي الئحتــه االعتراضيــة‬\n‫خــال املــدة املتبقيــة وقدرهــا ( ‪ ) 29‬تســعه وعشــرون يوم ـ ًا مــن تاريــخ‬\n‫اليــوم وأنــه مبضــي هــذه املــدة دون تقــدمي الالئحــة ســوف يســقط حقــه يف‬\n‫ويرفــع احلكــم مبشــيئة اهلل تعالــى حملكمــة االســتئناف بدونهــا‬     ‫تقدميهــا ُ‬\n‫فامتثــل واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وســلم ‪ .‬احلمــد‬\n‫هلل وحــده وبعــد ويف يــوم اإلثنــن املوافق‪1434/02/25‬ه ـ افتتحــت‬\n‫اجللســة وقــد وردت الالئحــة االعتراضيــة املقدمــة مــن املدعــى عليــه‬\n‫املقيــدة برقــم ‪ 34445549‬وتاريــخ ‪1434/2/23‬ه ـ وجــرى االطــاع‬\n‫عليهــا ولــم أجــد فيهــا مــا يوجــب الرجــوع عمــا حكمــت بــه وســوف‬\n‫يتــم رفــع احلكــم حملكمــة االســتئناف بالشــرقية لتدقيقــه واهلل املوفــق‬\n‫وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم احلمــدهلل وحــده وبعــد‬\n‫ويف يــوم االثنــن املوافق‪1434/06/05‬ه ـ فتحــت اجللســة وقــد وردت‬\n‫املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية مبوجــب اخلطــاب‬\n‫رقــم ‪ 34648389‬يف ‪1434/05/07‬ه ـ وبرفقهــا قــرار أصحــاب الفضيلــة‬\n\n\n                                                                                      ‫‪38‬‬\n\f     ‫قضــاة الدائــرة اجلزائيــة األولــى مبحكمــة االســتئناف باملنطقة الشــرقية‬\n     ‫رقــم ‪ 34204315‬يف ‪1434/05/04‬ه ـ املتضمــن املصادقــة علــى احلكــم‬\n     ‫لــذا جــرى إحلاقــه واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وســلم ‪.‬‬\n\n\n\n\n‫‪39‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"ca29cb00-ff93-515e-9771-74b0d5d4a25f","source_page_start":35,"source_page_end":39,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0f2f22dcc2575d7d8d319d916016f4db6079366922ca8cb5fac8513e50842d0b","normalized_text_hash":"88df1e5ac1f4053888ba9c83d89a09e6258660f82dd46b7fc5dfcbef0c60e0d4","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v24-p35-3422084"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
